pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are dead, but residuals below ~20 are practically unusable for typical items.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0; // heavy penalty for near-dead gaps
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit post-residual, the gap is likely dead — penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave bad gaps
    if bin_residual == bin_capacity {
        // neutral base; slightly penalized so existing decent bins win
        score = 25.0 + open_bins_count as f64 * 0.3;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // room for lookahead pairing in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (chained perfect fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 800.0;
        } else if post >= next {
            // Next item fits after this placement: reward closeness.
            score -= 300.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus if next item would then fill the bin perfectly.
            if (post - next) == 0 {
                score -= 200.0;
            }
        } else {
            // Next item cannot fit: penalize dead space proportionally.
            score += 50.0 + 2.0 * diff;
        }
    }

    // Compare post_residual against mean residual: leaving post_residual
    // far below mean creates unusable small pockets.
    let post = post_residual as f64;
    if post < mean_residual {
        score += 0.5 * (mean_residual - post);
    } else {
        score -= 0.2 * (post - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Late in the stream, prefer tighter packing (smaller post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Slight penalty for very small residual pockets (< 10) that likely
    // cannot fit future items (items >= 1, but small pockets are risky).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small leftovers are "dead space"
    // classes; reward residuals that fall into reusable harmonic buckets.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr <= 5 {
        score += 25.0; // unusable sliver
    } else if pr <= 15 {
        score += 10.0; // low-utility class
    } else if pr <= 30 {
        score -= 6.0; // good reusable class
    } else {
        score -= 12.0; // large residual, still flexible
    }

    // Modulo-10 harmonic: residuals divisible by 10 pair well with the
    // typical item granularity.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: can the next item exactly fit the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 20.0; // near-perfect chain
        } else if next_item_size > pr {
            score += 8.0; // next item cannot use this bin anyway
        }
        // Harmonic pair: next item leaves a multiple-of-10 remainder
        if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is poor or
    // the item would leave a nasty sliver in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain
        // (amortization) and when this bin would host a large item cleanly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 20.0 + 40.0 * progress;
        if item_size >= 50 {
            score -= 10.0;
        }
        if post_residual <= 5 && item_size < 50 {
            score -= 25.0; // big item almost filling a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else {
        // Prefer tighter existing bins relative to the mean residual.
        score += (bin_residual as f64 - mean_residual) * 0.3;
        // Penalize scattering across too many open bins.
        score += open_bins_count as f64 * 0.5;
    }

    // Early stream: be slightly greedy toward compact fits.
    if step_index < total_items / 4 {
        score += post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual can still fit the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // stranded gap that next item cannot use
        }
    }

    // Pressure from number of open bins: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: make it unattractive unless open bins are scarce
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * -2.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    // Slight preference for tighter existing fits relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but penalize near-waste.
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * cap * 0.35;

    // Penalize dead space: post residuals that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 25.0 + next_item_size as f64 * 0.4;
        } else {
            // Next item won't fit here; penalize leaving moderately-sized gaps.
            score += (post_residual as f64) * 0.25;
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: maximize fill of the stream's end.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 6.0;
    }

    // Global state: when many bins are open, consolidate rather than spread.
    let open_f = open_bins_count as f64;
    score += open_f * 1.5;

    // Mean residual coupling: if this bin's residual is below average, it's
    // already "dense" — finishing it is good; leaving it sparse is wasteful.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Time horizon: early in the stream, allow more exploratory new-bin opens;
    // late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0;
    score += (1.0 - progress) * 10.0;

    // New-bin candidate calibration: an empty bin gets the base post_residual
    // (= capacity - item_size). Make new bins attractive only for large items
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap;
        score -= 15.0 + avg_fullness * 40.0 + (item_size as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    let min_item = 1u32;
    let dead_threshold = if next_item_size > 0 { next_item_size.max(min_item) } else { min_item };

    if post_residual > 0 && post_residual < dead_threshold {
        // Unusable sliver: heavy penalty, worse the closer it is to zero utility.
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else if post_residual == 0 {
        // Perfect closure of a bin: strongly reward.
        score -= 60.0;
    } else {
        // Reward tight fits quadratically.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a large, reusable gap in existing bins (poor fits).
    if bin_residual == bin_capacity {
        // Mild baseline preference to reuse bins; overcome only by very tight fits there.
        score += 12.0;
    }

    // Mean residual coupling: when open bins are already loose, discourage more slack.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when the item fits an open bin
    // badly (large dead space would be created) or stream is early.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: post_residual == item_size here.
        // Penalize slightly so tight fits in open bins always win.
        score += 15.0;
        // But if placing in this item would leave a big usable gap anyway,
        // a fresh bin is fine; discount by open-bin pressure.
        score -= (open_bins_count as f64) * 0.5;
    }

    // Lookahead: if the next item could exactly use the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if next item cannot fit into post_residual and post_residual is small.
    if next_item_size > post_residual && post_residual < 15 && post_residual > 0 {
        score += 15.0;
    }

    // Mild pressure from number of open bins: prefer filling existing bins
    // when many are open.
    score += (open_bins_count as f64) * 0.3;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a "ragged" bin; finishing it off is good.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual - 10.0 {
        score -= 5.0;
    }

    // Progress: later in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can use well are toxic.
    let dead = if post_residual == 0 {
        -60.0 // perfect fit: strongest reward
    } else if post_residual < 10 {
        120.0 // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        30.0 // nearly dead gap
    } else if post_residual < 40 {
        5.0
    } else {
        -5.0 // roomy residual is reusable
    };
    score += dead;

    // Reward tight relative fit.
    score += 0.35 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation when bins are few,
    // encourage fresh bin when many bins already sprawl with slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: attractive only if it enables a good future pairing.
    if bin_residual == bin_capacity {
        let next_fits_fresh = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        if next_fits_fresh {
            score -= 18.0;
        } else {
            score += 40.0;
        }
    } else if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0; // lookahead exactly fills this bin
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here anyway; slack is less valuable
    }

    // Slight preference for bins tighter than the fleet mean.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth non-linear couplings with progress.
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + 0.5 * progress);          // dead space penalized more late in stream
    score -= 20.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - progress); // tight fits rewarded early

    // Cubic interaction: medium residuals are least harmful; extremes penalized.
    let mid = prn - 0.5;
    score += 15.0 * mid * mid * mid * mid;

    // Reward using bins whose residual matches the item closely (smooth kernel).
    let fit = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * fit * fit;

    // Last-chance bonus: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly, more when open bins are empty-ish and early.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
        // But allow a new bin if it perfectly fits the next item too.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 60.0;
        }
    }

    // Lookahead: prefer bins leaving residual compatible with the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 8.0 * (gap / cap);
        if pr >= next_item_size as f64 && gap < 10.0 {
            score -= 12.0;
        }
    }

    // Dampen preference for bins deviating from mean residual (smooth dispersion term).
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strongly favor this bin.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 + 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to how wasted the space is.
            score += 10.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space penalty: tiny leftovers are nearly unusable (items >= 1, but waste).
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., item barely fits anywhere). Penalize mildly so open bins are preferred,
    // but relax the penalty late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += fit_pressure + 20.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_residual.saturating_sub(item_size)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "resonant" class (multiples of 10, or very small) are more reusable.
    let pr = post_residual;
    let class = pr / 10; // integer division harmonic class (0..10)

    // Reward residuals that are exactly divisible into useful chunks (mod 10 == 0)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Penalize "dead" residuals that no typical item can use
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Non-linear dead-space penalty: quadratic growth of waste for small leftovers
    score += (class as f64).powi(2) * 0.4;

    // Perfect fit is ideal
    if pr == 0 {
        score -= 50.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly in the
    // post residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
            if next_post < 10 {
                score += 12.0; // would create dead space for the next item
            }
        } else {
            // next item cannot fit here; slight penalty for tight bins
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins early, reward when open bins are fragmented
        score += 30.0 + 40.0 * (1.0 - progress) - 0.8 * open_bins_count as f64;
        if tightness < 0.2 {
            score -= 20.0; // large item in fresh bin is acceptable
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor)
    let avg = mean_residual;
    if (bin_residual as f64) < avg {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Modulo-3 harmonic jitter on item class to break ties deterministically
    let item_class = item_size % 3;
    score -= item_class as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits here after current item: chain reward scaled by leftover
            let chain_left = post_residual - next_item_size;
            score -= 300.0 - (chain_left as f64).min(200.0);
        } else {
            // next item cannot use the post residual: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible = post_residual as f64;
        score += 50.0 + best_possible * 0.2;
    }

    // Late-stream consolidation: prefer filling existing bins toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong subtraction for near-zero post residual.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or closely matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 150.0;
        } else if diff <= 5 {
            score -= 60.0;
        } else if diff <= 15 {
            score -= 15.0;
        } else {
            // Penalize post residuals that neither fit next item nor are small.
            score += diff as f64 * 0.3;
        }
        // If next item cannot fit in post residual, mild penalty proportional
        // to how far off we are.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin bonus: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: penalize moderately so it's only chosen when no
    // open bin offers a good fit, but keep it competitive vs. terrible fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

