    }
    // Classes divisible by 5 are "harmonic" — easier to fill later
    if class == 0 || class == 5 {
        score -= 12.0;
    }
    // Exact division: post_residual divides capacity evenly -> reusable slots
    if pr > 0 && (bin_capacity as i64) % pr == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n <= pr {
            // next item fits exactly-ish: strong reward
            if n == pr {
                score -= 200.0;
            } else {
                let gap = pr - n;
                // reward small gaps (near-perfect chain), penalize large gaps mildly
                score -= 40.0 - (gap as f64).min(40.0);
                if gap <= 5 {
                    score -= 20.0;
                }
            }
        } else {
            // next item won't fit here: penalize proportionally to overflow
            score += ((n - pr) as f64) * 0.8;
        }
    }

    // Last-chance bin: only fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer opening fresh bin only when fits are poor
    if bin_residual == bin_capacity {
        // mild default bonus toward reuse: new bin slightly penalized
        score += 30.0;
        // but if no open bin fits well (post_residual large relative to item), allow new bin
        if post_residual > bin_capacity / 2 {
            score -= 55.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's "wasted space"
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // Stream progression: late in stream, tighten up (avoid many tiny residuals)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Small residual penalty scaled by open bins count (fragmentation cost)
    if post_residual > 0 && post_residual < 10 {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), scaled non-linearly
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth stream-progress coupling: later in stream, penalize wasted residual more strongly
    let progress_coupling = pr_norm * progress * (progress - 0.5) * 40.0;
    score += progress_coupling * pr;

    // Penalize post-residual that is too small to fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let shortfall = (nxt - pr) / cap;
            score += shortfall * shortfall * 120.0 * (0.5 + progress);
        } else {
            // Reward residual that can still host the next item
            score -= 15.0 * (1.0 - (pr - nxt).abs() / cap);
        }
    } else {
        // Last item: strongly prefer minimal residual
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Last-chance bin bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mildly discourage fragmenting when many bins are already open
    score += 0.05 * (open_bins_count as f64) * pr_norm;

    // Encourage matching against bins with lower-than-mean residual (tighter packing)
    score += 0.3 * (mean_residual - pr as f64);

    score
}

