        if pr < nxt {
            let shortfall = (nxt - pr) / cap;
            score += shortfall * shortfall * 120.0 * (0.5 + progress);
        } else {
            // Reward residual that can still host the next item
            score -= 15.0 * (1.0 - (pr - nxt).abs() / cap);
        }
    } else {
        // Last item: strongly prefer minimal residual
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Last-chance bin bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mildly discourage fragmenting when many bins are already open
    score += 0.05 * (open_bins_count as f64) * pr_norm;

    // Encourage matching against bins with lower-than-mean residual (tighter packing)
    score += 0.3 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / cap; // 0..1
    let quarter = (post_residual / (bin_capacity / 4)) as f64; // integer-division class 0..4

    // Penalize dead space non-linearly; tiny residuals (<10) are nearly useless.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 6.0;
    } else if post_residual < 30 {
        score += 2.0;
    } else {
        score += frac * frac * 4.0;
    }

    // Modulo arithmetic on post_residual: residual divisible by small sizes is reusable.
    let mut reusable = false;
    for d in [10u32, 20, 25, 50] {
        if post_residual >= d && post_residual % d == 0 {
            reusable = true;
            break;
        }
    }
    if reusable {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
            // bonus if next_item_size divides post_residual (harmonic fit)
            if post_residual % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            // next item can't use leftover: penalize large leftover more late in stream
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += frac * 6.0 * (0.5 + t);
        }
    }

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New empty bin candidate: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / cap) + 0.5 * (open_bins_count as f64) / (open_bins_count as f64 + 4.0);
        score = cap - score * 0.1 + (1.0 - pressure) * 20.0;
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 3.0;
        }
    }

    // Quarter-class tiebreak: prefer residual classes 0 (perfect) then 1 (fits small items).
    score -= (4.0 - quarter) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can use are heavily penalized.
    // Minimum plausible item size is 1, but tiny gaps (<10) are near-unusable in practice.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Perfect fit: zero waste is the ideal outcome.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize if the post-residual cannot accommodate the lookahead item,
    // forcing the next item into another bin or a new bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward if the leftover still fits the next item (keeps chain placement alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: with many open bins, prefer consolidating
    // into existing bins; new-bin candidate (empty bin) gets penalized more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: bias against opening unless the fit elsewhere is terrible.
        score += 12.0 + open_pressure;
    } else {
        // Slight reward for placing into existing bins, scaled by how full the bin is.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 2.0 + 8.0 * fill_ratio;
    }

    // Prefer bins below mean residual (relatively emptier bins absorb items,
    // keeping tight bins available for small future items).
    let residual_dev = mean_residual - bin_residual as f64;
    score += 0.05 * residual_dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins where the next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits: good, but prefer leaving little slack after that too.
            let second_post = post_residual - next_item_size;
            score -= 150.0;
            if second_post == 0 {
                score -= 400.0;
            } else if second_post <= 10 {
                score -= 100.0;
            } else {
                score += second_post as f64 * 0.3;
            }
        } else {
            // Next item does not fit in this bin's post residual: penalize dead space
            // relative to how much the next item would waste.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score += post_residual as f64 * 1.5;
    }

    // Compare post residual against mean residual across open bins:
    // prefer bins whose residual is already small (tight packing).
    score += (mean_residual - post_residual as f64) * -0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when existing bins can absorb the item reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced late in the stream or when few bins fit.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 + 60.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            // A fresh bin guarantees the next item fits too; soften penalty.
            score -= 90.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference to spread load when many bins are open (avoid over-concentration).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small and unusable
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: if post_residual can't even hold the smallest item (1), it's waste
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 20.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after placement; slight penalty if waste is large
        score += 0.05 * (post_residual as f64);
    }

    // Penalize opening new bins when many open bins exist with slack
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 30.0;
        // cheaper to open new bins early in stream, expensive late
        score += 20.0 * progress;
        // if few fitting bins exist, opening a new bin is more acceptable
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // if mean residual is high, existing bins have room; discourage new bin
        score += 0.3 * mean_residual;
    }

    // Prefer bins with below-average residual (concentrate filling)
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for using fewer bins overall as stream progresses
    if open_bins_count > 10 {
        score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p = progress;
    // Polynomial basis mixing progress and residual
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * p * (1.0 - p)) + pr_norm * (1.0 - p) * 3.0;
    score += coupling * 10.0;

    // Reward tight fits more strongly as stream progresses (smooth polynomial in progress)
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (1.0 + p) * 15.0;

    // Penalize dead space: residual too small for typical future items
    let dead = (pr / 100.0).powi(3);
    score += dead * 25.0;

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - p * 0.5);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let room = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= (room / 100.0) * (1.0 + p) * 8.0;
        // Penalize if this placement blocks the next item entirely
        if post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    // New-bin candidate: make it moderately attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr_norm * 100.0).max(0.0);
        score = 60.0 + mean_gap - p * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes matter more when small.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: post_residual in {0} or tiny residue.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo harmonic classes: residues that pair well with common item sizes
    // (items 10..80, many multiples of 5/10). Residue mod 10 == 0 is reusable.
    let m10 = post_residual % 10;
    match m10 {
        0 => score -= 12.0,
        5 => score -= 6.0,
        _ => score += 4.0, // awkward residue
    }

    // Integer division thresholds on post_residual: which item classes can still fit.
    // Items >= 10, so post_residual >= 10 keeps the bin alive.
    if post_residual < 10 {
        score += 30.0; // dead space: bin effectively closed
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0; // only tiny items fit
    } else if post_residual >= 50 {
        score -= 8.0; // roomy bin, still very usable
    }

    // Capacity fraction coupling: waste fraction penalized superlinearly.
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 20.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward smooth continuation, penalize leaving awkward remainder
            if slack % 10 == 0 {
                score -= 15.0;
            } else {
                score -= slack / 10.0;
            }
        } else {
            // next item won't fit here; if this is the last fitting bin, prefer it anyway
            if fitting_bins_count == 1 {
                score -= 20.0;
            } else {
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Stream progression: late in the stream, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 1.5;

    // Prefer bins with residuals near mean (balanced packing).
    score += (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: penalize moderately so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + waste_frac * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are pure waste.
    // Anything below a practical threshold is heavily penalized proportionally to its uselessness.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny dead space: penalize as if the whole gap were lost.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward bins whose residual was large (using big bins for big chunks).
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Open-bins pressure: with many open bins, prefer consolidation into existing bins
    // and penalize spreading (which would favor opening new bins).
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += open_pressure * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0 - slack * 2.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: mildly penalize leaving a gap that blocks lookahead.
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to keep
    // large-residual bins available for future large items.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if many open bins exist and this item is large, opening fresh is less bad.
        score -= (item_size as f64 / 100.0) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: mild reward proportional to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space, worse when wasted space is small
            // (fragmentation) relative to mean residual.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5 + (dead / mean_residual.max(1.0)) * 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // would leave a well-shaped residual; new bin residual = 100 - item_size.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Large items (little post residual) are good triggers for a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Prefer placing into bins whose residual is below the mean (tighter bins first),
    // keeping larger residuals available for larger future items.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    // Early in the stream, be slightly more willing to open bins (build a good pool);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (item_size as f64) * 0.8;

    // Penalize dead space: very small post_residual that can't fit typical items is fine,
    // but mid-range waste is bad. Reward post_residual near 0.
    if post_residual == 0 {
        score -= 50.0; // perfect fit bonus
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit
    } else if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.6; // large leftover waste penalty
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.3;
    }

    // Lookahead: reward bins whose post_residual can accommodate the next item,
    // penalize if the next item would be stranded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + next_item_size as f64 * 0.1;
        } else {
            score += 5.0; // this placement strands the next item here
        }
    }

    // New-bin candidate handling: opening a new bin is attractive when the item
    // fits poorly everywhere else, or when open bins have large residuals being wasted.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin grows with number of open bins and stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = 20.0 + open_bins_count as f64 * 2.0 + progress * 15.0;
        score = open_cost;
        // If item fits badly in all bins (large item, few fitting bins), new bin is better.
        if fitting_bins_count <= 1 && item_size > 40 {
            score -= 25.0;
        }
        // If mean residual is large, prefer using existing bins instead of a new one.
        score += mean_residual * 0.4;
        // Lookahead synergy: a fresh bin can always take the next item.
        if next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Global state: when many bins are open with high mean residual, discourage
    // leaving more waste in any bin.
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // Mild time-horizon shaping: early in the stream, be more conservative with bins.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - horizon);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let poly = norm_post * norm_post * (1.0 + 3.0 * progress);
    score += 40.0 * poly;

    // Perfect fit reward, amplified late in stream
    let fit_bonus = (norm_post - 0.05).abs() * (1.0 - progress);
    score -= 60.0 * (1.0 - fit_bonus).max(0.0) * (1.0 - norm_post);

    // Penalize last-chance bin waste
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 15.0 * norm_post * (1.0 + progress);
    }

    // New bin candidate: prefer it early, penalize late
    if bin_residual == bin_capacity {
        score -= 25.0 * (1.0 - 2.0 * progress).max(-0.5);
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress);
    }

    // Mean residual deviation coupling
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "resonant" class (multiples of 10, or very small) are more reusable.
    let pr = post_residual;
    let class = pr / 10; // integer division harmonic class (0..10)

    // Reward residuals that are exactly divisible into useful chunks (mod 10 == 0)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Penalize "dead" residuals that no typical item can use
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Non-linear dead-space penalty: quadratic growth of waste for small leftovers
    score += (class as f64).powi(2) * 0.4;

    // Perfect fit is ideal
    if pr == 0 {
        score -= 50.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly in the
    // post residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
            if next_post < 10 {
                score += 12.0; // would create dead space for the next item
            }
        } else {
            // next item cannot fit here; slight penalty for tight bins
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins early, reward when open bins are fragmented
        score += 30.0 + 40.0 * (1.0 - progress) - 0.8 * open_bins_count as f64;
        if tightness < 0.2 {
            score -= 20.0; // large item in fresh bin is acceptable
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor)
    let avg = mean_residual;
    if (bin_residual as f64) < avg {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Modulo-3 harmonic jitter on item class to break ties deterministically
    let item_class = item_size % 3;
    score -= item_class as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose leftover can still host typical small items (>=10).
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Exact match with lookahead item: excellent two-item chaining.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If leftover can host the next item, mildly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that neither fits next item nor is useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a poor-fit bin; closing it out is good.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.4;
    } else {
        score += (resid_f - mean_residual) * 0.2;
    }

    // New-bin candidate: default mild penalty so it's chosen only when
    // open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // If next item is large and this item is small, opening fresh may pay off.
        if next_item_size > 50 && item_size < 30 {
            score -= 18.0;
        }
        // Early stream with few bins: opening is cheap.
        if progress < 0.3 && open_bins_count < 5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near match between
    // post_residual and the next item's size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        if diff == 0.0 {
            // Perfect two-item completion of this bin -> strongly favored.
            score -= 60.0;
        } else if nxt <= post {
            // Next item fits: favor leaving just enough room (tight fit).
            score -= 25.0 * (1.0 - diff / 100.0);
        } else {
            // Next item won't fit here: penalize small dead space left behind,
            // since it's likely unusable for the next item.
            score += 10.0 + diff * 0.3;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are "emptier";
    // placing here keeps fuller bins (small residuals) available.
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving extremely small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    // Perfect closure (zero residual) is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Mild pressure toward consolidating when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item size is worthless.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 15.0 * (dead_threshold - post_residual as f64);
    }

    // Squared waste penalty: strongly discourage leaving awkward mid-size gaps.
    score += 0.05 * (post_residual as f64).powi(2);

    // Last-chance bonus: if this is the only bin that fits, use it to avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Congestion: many open bins -> prefer consolidating into existing bins.
    let congestion = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.5 * congestion;

    // New-bin candidate handling: an empty bin gets a baseline penalty that
    // shrinks as the stream progresses (less room to be picky late).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0 - 10.0 * progress;
        // Justify opening a new bin if the next item pairs well with the
        // leftover space this item creates (post_residual >= next_item_size).
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            new_bin_penalty += 20.0; // bad idea: waste a fresh bin pairing
        } else if next_item_size > 0 && (bin_residual as u32) >= item_size + next_item_size {
            new_bin_penalty -= 15.0; // fresh bin can host both items
        }
        // If current bin would leave a huge unfillable gap, new bin is fine.
        if post_residual > 40 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / 100.0).max(0.0);
        // Penalize placements that strand the next item's size class.
        if (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 6.0;
        }
    }

    // Mild preference for bins already below average residual (fill emptier
    // bins first keeps more flexibility elsewhere).
    if (bin_residual as f64) > mean_residual {
        score += 1.5;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let poly = pr * (1.0 + 0.35 * progress * progress + 0.15 * (1.0 - progress) * progress);
    let mut score = poly;

    // Reward tight fits: quadratic penalty on normalized post residual
    score += 40.0 * pr_norm * pr_norm;

    // Penalize waste relative to mean residual (smooth cubic coupling)
    let mean_n = mean_residual / cap;
    score += 12.0 * (pr_norm - mean_n).abs() * (1.0 + mean_n * mean_n);

    // Lookahead: reward bins whose post residual fits the next item (smooth gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 18.0 * (1.0 - (nxt / cap)) * (1.0 - 0.5 * progress);
        } else {
            score += 10.0 * (nxt - pr as f64) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Congestion: many open bins -> prefer filling existing ones
    let congestion = open_bins_count as f64 / (1.0 + (total_items as f64).sqrt());
    score += 8.0 * congestion * pr_norm * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin, but relax late in stream
    if bin_residual == bin_capacity {
        score += 30.0 + 45.0 * (1.0 - progress) - 20.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a
    // "reusable band" are rewarded; dead-space bands are penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        // Integer-division thresholds: classify leftover into quanta of 10
        let quantum = pr / 10;
        match quantum {
            0 => score += 25.0,                 // 1..9 : near-dead space
            1 => score += 10.0,                 // 10..19
            2 => score -= 5.0,                  // 20..29
            3 => score -= 12.0,                 // 30..39
            4 => score -= 15.0,                 // 40..49
            5 => score -= 10.0,                 // 50..59
            6 => score -= 4.0,                  // 60..69
            7 => score += 3.0,                  // 70..79
            _ => score += 8.0,                  // 80..100 (near-empty)
        }
        // Modulo-10 harmonic bonus: leftovers that are multiples of 10
        // pair well with a wide range of item sizes (1..100 grid alignment).
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Exact modular match is golden
            if pr % next_item_size == 0 {
                score -= 18.0;
            } else {
                let ratio = next_item_size as f64 / pr as f64;
                // reward high fill of the leftover by next item
                score -= 14.0 * ratio;
                if ratio > 0.9 {
                    score -= 6.0;
                }
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            let waste = (next_item_size - pr) as f64;
            score += 4.0 + waste * 0.15;
        }
    } else {
        // Last item: prefer zero residual strongly
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, tighten discrimination on residual
        score += (fitting_bins_count as f64) * 0.3;
    }

    // New-bin candidate handling: only attractive when all open residuals
    // are small (mean residual low) and item is large.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        // opening new bin is good if existing bins are too full for future use
        score += 30.0 * mean_frac;
        // discourage opening for small items when open bins exist
        if open_bins_count > 0 {
            score += 22.0 * (1.0 - item_frac);
        } else {
            score -= 50.0; // must open first bin
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mean-residual coupling: if this bin is much fuller than average,
    // favor filling it (pack tight bins first).
    let residual_frac = bin_residual as f64 / cap;
    if residual_frac < mean_residual / cap {
        score -= 6.0 * (mean_residual / cap - residual_frac);
    }

    // Mild preference for tight fits overall
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are likely unusable forever.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 25 {
        // moderate dead space: mild penalty tapering off
        score += 0.5 * (25.0 - post_residual as f64);
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead coupling (k=2): shape the gap for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < f64::EPSILON {
            score -= 15.0; // perfect slot reserved for next item
        } else if post_residual > 0 && (post_residual as f64) < nxt {
            score += 8.0; // gap too small for the known next item -> dead space
        }
    }

    // Last-chance pressure: if this is the only open bin that fits, use it
    // rather than fragmenting by opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling (brand-new empty bin: residual == capacity)
    if bin_residual == bin_capacity {
        // Consolidation pressure: many open bins -> penalize opening another.
        score += 10.0 + 3.0 * open_bins_count as f64;
        // If open bins are nearly full (low mean residual), a fresh bin is justified.
        score -= 0.5 * (bin_capacity as f64 - mean_residual);
        // Large items are less penalized in a fresh bin (they need room anyway).
        score -= 0.2 * item_size as f64;
        // Late in the stream, slightly favor closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
    } else {
        // Mild reward for reusing existing bins when many are open.
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let match_gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize dead space created
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: minimize waste directly
        score = post_residual as f64 * 1.5;
    }

    // Prefer tighter bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can host next item too
        }
    }

    // Early in stream: allow more bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 12.0;
        } else {
            // Penalize wasting residual that the next item almost fits into.
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep bins clean);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 15.0 * (1.0 - progress);
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 0 {
        let avg_util = 1.0 - (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score -= 8.0 * avg_util * (open_bins_count as f64).ln().max(1.0);
    }

    // Mild penalty for very large waste relative to item size.
    if item_size > 0 {
        score += 0.1 * (post_residual as f64 / item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - pr / cap; // 0 = loose, 1 = tight
    let coupling = tightness * tightness * (1.0 + progress * 2.0);
    score -= 15.0 * coupling;

    // Penalize very small dead space only if it likely wastes the bin
    let dead = (pr / cap).powi(3);
    score += 10.0 * dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (larger residuals) slightly
    score -= 0.05 * (mean_residual - pr);

    // Lookahead: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 5.0 * (nx / cap);
        } else {
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // New-bin candidate: penalize mildly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item size (1)
    // are pure waste. Penalize small leftover gaps super-linearly.
    if post_residual > 0 {
        // Usability: gap usable if it can hold a reasonably sized future item.
        let usable_threshold = 20u32;
        if post_residual < usable_threshold {
            // Dead space: heavily penalize, worse the smaller it is.
            let dead = (usable_threshold - post_residual) as f64;
            score += dead * dead * 0.8;
        } else {
            // Usable leftover: mild reward scaled by how much room remains.
            score -= (post_residual as f64) * 0.15;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= (fill_ratio - 0.8) * 80.0;
    } else if fill_ratio < 0.3 {
        // Wasting a large bin on a tiny item: penalize.
        score += (0.3 - fill_ratio) * 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another one;
    // favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: apply pressure so it only wins when open bins are bad.
        score += 25.0 + pressure * 12.0;
        // But if next item is small, a fresh bin has future value.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score -= 10.0;
        }
    } else {
        score -= pressure * 3.0;
    }

    // Prefer bins with residual below the running mean (consolidate toward fuller bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: reward, more so the tighter the two-item fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack * 0.3;
            if slack == 0.0 {
                score -= 200.0; // exact 2-item chain fit
            }
        } else {
            // Post residual is dead space for the next item: penalize small leftovers.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 30.0; // tiny unusable gap
            } else {
                score += (waste - 10.0).min(60.0) * 0.2;
            }
        }
    }

    // Prefer bins whose residual is below the mean (compact bins), i.e. filling fuller bins first.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it expensive, but cheaper when it is the last chance
    // and the current item leaves a large residual (poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to item size)
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space that no future item (min size 1) could plausibly use well:
    // small residuals below typical item sizes are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty if this leaves a useless gap
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidating into fuller bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * fullness;

    // Global residual pressure: if mean residual is high, prefer filling existing bins
    // rather than spreading; if low, allow opening new bins for better fits.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when mean residual is low or item is large
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * item_ratio * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 14.0; // existing bins have room; don't open a new one
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    } else {
        // Existing bin: reward when its residual is below mean (it's one of the fuller ones)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, prioritize closing out bins (avoid many tiny residuals)
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on leftover space (waste), scaled by progress
    let mut score = pr * (1.0 + 1.5 * progress) + 60.0 * norm_pr * norm_pr;

    // Smooth coupling: leftover squared times progress decay — early stream tolerates slack
    score += 40.0 * norm_pr * norm_pr * progress * (1.0 - progress);

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 20.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: penalize bins far above the mean residual (fragmentation)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins early
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space buckets (mod 10)
    let class = post_residual % 10;
    // Residuals in "awkward" classes are penalized more (dead space)
    if class != 0 {
        score += (10 - class) as f64 * 0.6;
    }
    // Perfectly tight fit gets strong reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Integer-division threshold: post_residual / 20 zone
    let zone = post_residual / 20;
    score += zone as f64 * 3.0;

    // Lookahead: can next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward if next item nearly fills remainder
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap <= 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // residual too small for lookahead: penalize proportionally
        score += 4.0 + (post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but allow if current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual > 50 {
            score += 15.0; // opening fresh bin for small items wastes capacity
        }
    }

    // Favor fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Progress: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    // Modulo coupling between item and post_residual classes
    if (item_size % 10) + (post_residual % 10) == 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10 - post_residual) as f64; // dead space zone
        } else if post_residual <= 15 {
            score += 12.0; // risky gap: only tiny items fit
        } else if post_residual >= 50 {
            score -= 8.0; // large residual keeps bin reusable
        }
    } else {
        score -= 25.0; // perfect closure of the bin
    }

    // Tight fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: avoid bins far below average utility late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.5;

    // New-bin candidate: neutral-ish baseline; only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover slack after both placements
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin: penalize dead space more
            score += post_residual as f64 * 0.3;
        }
    } else {
        // last item: just prefer tightest fit
        score += 0.0;
    }

    // Reward tight fits relative to current item.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Compare post_residual against mean residual: avoid creating outliers.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.2;

    // Last-chance bin bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Slight preference to keep new bins closed when stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: small post_residual relative to capacity.
    score -= (1.0 - post / cap) * 8.0;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post - next_item_size as f64;
        score -= 10.0 + 0.05 * slack_after_next;
    }
    // If next item cannot fit, penalize wasted usable space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.1 * post.min(next_item_size.saturating_sub(1) as u32) as f64;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin unless current bins are poor fits:
    // new-bin candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, softened when many bins are open
        // and mean residual is high (fragmented state) or late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 10.0 * fragmentation - 8.0 * progress;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 0.05 * item_size as f64;
    }

    // Slight preference to fill bins with larger residuals when many bins open.
    score -= 0.01 * (bin_residual as f64).min(50.0);

    // Mild time-dependent tightening: early on, be conservative; later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (2.0 - x);
    let base = post - 40.0 * poly * (1.0 - progress);

    // Penalize dead space more as stream progresses (less time to recover)
    let dead_penalty = 0.35 * progress * x * x * cap;

    // Reward tight fits: low post_residual relative to item
    let tight_bonus = -8.0 * (1.0 - x).powi(3);

    // Last-chance bonus: only fitting bin, avoid opening new bin
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Crowd penalty when many bins open
    let crowd = 0.02 * open_bins_count as f64 * x;

    // Lookahead: reward if next item fits in post residual
    let lookahead = if next_item_size > 0 {
        if (next_item_size as f64) <= post { -5.0 } else { 2.0 * (post - next_item_size as f64).abs() / cap }
    } else { 0.0 };

    // Mild pull toward mean residual state
    let mean_pull = 0.1 * (post - mean_residual).abs() / cap;

    base + dead_penalty + tight_bonus + last_chance + crowd + lookahead + mean_pull
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // harmonics (10, 20, 25, 50) are more reusable for future items.
    let pr = post_residual as i64;
    let mut bonus = 0.0;
    for h in [10i64, 20, 25, 50].iter() {
        let r = pr % h;
        let dist = r.min(h - r);
        bonus += (dist as f64) / (*h as f64);
    }
    score -= bonus * 4.0;

    // Dead-space penalty: tiny post_residual that fits almost nothing useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward exact fit for the next item's harmonic class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 12.0;
            }
            if slack < 5 {
                score += 8.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual).min(40) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else (large item, few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
        let penalty = 55.0 + 40.0 * (1.0 - progress) - 25.0 * fit_ratio;
        // large items pack better in a fresh bin
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        score += penalty;
    }

    // Mild pressure to consolidate when many bins are open.
    score += mean_residual * 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste; penalize them super-linearly.
    let dead_threshold = 10.0f64;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 6.0;
    }
    // Also punish "awkward" residuals that can't fit the lookahead item.
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 8.0;
    } else if next_item_size > 0 {
        // Reward residuals that exactly or nearly fit the next item.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 / (1.0 + gap);
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 40.0 / (1.0 + (item_size as f64).max(1.0));

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few bins -> allow opening new ones.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = (open_bins_count as f64 / (8.0 + 6.0 * progress)).min(2.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; attractive only when
        // pressure is low or all fits are poor.
        score = cap - item_size as f64;
        score += 30.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    } else {
        score -= 12.0 * pressure.min(1.0);
        // Slight preference for bins whose residual deviates from the mean
        // in the "useful" direction (large residual absorbs big items).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residuals that are too small for any plausible next item (< 10).
        if post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual already in base score).
        score += 5.0;
    }

    // Penalize dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0
            && (bin_residual as i64 - item_size as i64 - next_item_size as i64).abs() > 20;
        if fitting_bins_count > 1 && !poor_fit {
            score += 60.0; // discourage opening new bin when fits exist
        } else if poor_fit {
            score -= 15.0; // opening a fresh bin may enable a perfect next fit
        }
    }

    // Slight preference for fuller bins early on (best-fit flavor).
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space that no future item can use.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - t);
    }

    // Reward tight fits: post_residual near zero.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score += (post_residual as f64).sqrt() * 3.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 50.0;
            } else {
                score += slack as f64 * 0.5;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Prefer filling bins with large residuals when many bins are open.
    if open_bins_count > 3 {
        score -= (bin_residual as f64 - mean_residual) * 0.4;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Base new-bin score: moderate, so only chosen when open-bin fits are bad.
        score = 55.0 + poor_fit * 0.6;
        // Late in stream, discourage opening new bins slightly.
        score += t * 15.0;
        // If many bins already fit the item, discourage new bin.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Mild penalty for very small items consuming large residuals late.
    if item_size < 25 && post_residual > 50 {
        score += 12.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize post_residual (wasted space), with non-linear scaling
    let mut score = pr + (pr / cap).powf(2.0) * cap * 0.5;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = (pr / cap) * (1.0 - t) * (1.0 - t) - (pr / cap) * t * t * 0.5;
    score += coupling * cap * 0.3;

    // Tightness reward: near-perfect fits get smoothly amplified
    let tight = (pr / cap).powf(3.0);
    score -= tight * cap * 0.4;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - tight);
    }

    // Penalize bins with residual far above mean (fragmentation)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs() * (1.0 + t);

    // Lookahead: if next item could fill this bin's post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // New-bin candidate: keep it slightly unattractive unless residuals are scarce
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - t);
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual: residues mod 10 ---
    // Residuals in {0} are perfect; small residues (1..=9) are "dead classes"
    // that almost nothing can reuse (items are >=1, but small leftovers rarely match).
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 6.0,                    // perfectly harmonic residual
        1..=4 => score += 3.0 + (4 - class) as f64, // tiny unusable slivers
        5..=9 => score -= 1.0,                // mid-range leftovers are reusable
        _ => {}
    }

    // Integer-division threshold bands on post_residual (capacity fractions).
    let cap_f = bin_capacity as f64;
    let pr_frac = pr as f64 / cap_f;
    if pr_frac == 0.0 {
        score -= 10.0; // exact fill: ideal
    } else if pr_frac <= 0.05 {
        score += 8.0;  // nearly-full but wasteful sliver
    } else if pr_frac <= 0.20 {
        score += 2.0;  // small leftover zone
    } else if pr_frac <= 0.50 {
        score -= 2.0;  // half-bin leftovers stay useful
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic pair: next item's class matches leftover band
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 7.0; // chains into another exact class
            } else if gap <= 4 {
                score += 4.0; // leaves a sliver after the lookahead too
            } else {
                score -= 3.0;
            }
        } else {
            score += 3.0; // next item cannot reuse this leftover
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the item fits nowhere harmonically. Penalize opening new bins when
    // decent open-bin space exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_frac = mean_residual / cap_f;
        score = 55.0
            - 25.0 * (1.0 - progress)              // cheaper to open early
            - 20.0 * (1.0 - mean_frac).max(0.0);   // open if open bins are cramped
        // If a perfect fit exists elsewhere, new bin loses.
        if pr == 0 && bin_residual != bin_capacity {
            score += 100.0;
        }
    } else {
        // Mild preference for tighter existing bins as stream matures.
        score += 0.02 * (open_bins_count as f64) * (1.0 - pr_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // practically < 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score -= 60.0; // perfect-ish fill, strongly favored
    } else if post_residual < 20 {
        score -= 25.0;
    } else if post_residual < 30 {
        score -= 8.0;
    } else {
        // large leftover: penalize proportionally to unusable bulk
        score += (post_residual as f64) * 0.15;
    }

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit in the gap -> gap becomes dead space
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when tight fits exist
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // opening a new bin is fine if current bin's fit is terrible
        if post_residual > 40 {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big reward; near-match: proportional reward.
        score -= 40.0 * (1.0 - match_gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving a residual the next item can never fit into usefully
        // (dead space smaller than the smallest conceivable item band).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure waste minimization.
        score += 0.3 * post_residual as f64;
    }

    // Compare against mean residual across open bins: placing in a bin that is
    // already below-average residual tightens packing; above-average residual
    // bins should absorb items to consolidate slack.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it to avoid
    // opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity (poor fit elsewhere) or few bins fit it.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * size_ratio; // large items prefer fresh bins
        if fitting_bins_count <= 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins that will end mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (1.0 - size_ratio);
    }

    // Mild preference for tighter fits overall (small post_residual).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits — quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.08 * (next_item_size as f64);
        } else {
            // Dead space relative to the next item: mild penalty scaled by gap.
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin when this is the sole candidate.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // More competing bins -> prefer the tightest; slight crowding penalty
    // for bins that are already very full (small post_residual) to keep
    // flexible bins available.
    if post_residual <= 10 {
        score += 2.0; // near-perfect fit is fine, but keep tiny bins from hoarding
    }

    // New-bin candidate (empty bin): penalize opening unless the item is
    // large or the stream is early and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut nb = 15.0;
        // Large items fit better in fresh bins; early stream with high mean
        // residual suggests open bins are fragmented anyway.
        nb -= 10.0 * item_frac;
        nb -= 8.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // If many bins already open, discourage proliferating further.
        nb += 0.4 * open_bins_count as f64;
        // If no open bin can fit (fitting_bins_count counts only open bins here,
        // and the new bin is the candidate), the penalty should vanish.
        if fitting_bins_count == 0 {
            nb = -100.0;
        }
        score += nb;
    }

    // Global state: when mean residual across open bins is low, tighten
    // preference for exact packing; when high, allow looser placements.
    let mr = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 3.0 * (1.0 - mr) * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Time horizon: late in the stream, be more conservative (avoid new bins),
    // favor squeezing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Penalize large dead space more as stream progresses (waste compounds late).
    score += cap * progress * norm_pr * norm_pr * 2.0;

    // Reward tight fits: subtract when post_residual is small, amplified by progress.
    let tightness = 1.0 - norm_pr;
    score -= cap * tightness * tightness * (0.4 + 0.8 * progress);

    // Last-chance bonus: only fitting bin -> strong reward, smoothed.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins to keep alternatives.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            // Next item won't fit -> penalize leaving a stranded residual.
            score += 6.0 * norm_pr * (0.5 + 0.5 * progress);
        }
    }

    // Context coupling with mean residual: prefer bins deviating from mean
    // (fill fuller-than-average bins, keep emptier bins flexible).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 - progress * 0.5);

    // New-bin candidate handling: empty bin gets baseline cost that grows
    // with number of open bins and shrinks with progress.
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.4 * progress) + 5.0 * (open_bins_count as f64).ln();
    }

    // Mild penalty for too many open bins.
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual in low harmonic classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else {
        // dead-space penalty grows for unusable slivers
        if pr < item_size.min(next_item_size.max(1)) && pr < 10 {
            score += 20.0; // sliver nobody can use
        }
        // modulo-10 harmonic class penalty on dead space
        let class = pr % 10;
        score += class as f64 * 0.8;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        // baseline: opening a new bin costs roughly the mean waste it avoids
        score = (bin_capacity as f64) * 0.5 + mean_residual * 0.3;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0; // new bin also accommodates lookahead comfortably
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    // Lookahead pairing: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 12.0;
            } else {
                score -= 5.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3; // next item won't fit here
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Slight preference for fuller bins when many bins are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.02 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (waste relative to item size).
    score -= 0.8 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when it enables a good
    // pairing with the next item, otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.4 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= 100 - item_size {
            score -= 18.0;
        }
    }

    // Lookahead coupling: reward residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 12.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Mild stream-progression tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if average residual is small, conserve tight fits.
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match (this item + next item exactly fill the bin)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits after this placement: mild reward scaled by tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow into this bin: penalize proportionally to wasted potential
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 + gap * 0.25;
    }

    // Penalize dead space relative to mean residual across open bins
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small unusable residuals (dead space), non-linearly
    if pr > 0 && pr < 10 {
        score += (10.0 - pr) * 2.0;
    }

    // Perfect closure bonus
    if pr == 0 {
        score -= 15.0;
    }

    // Early in the stream: allow opening new bins more freely; late: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive when many bins are open or late
        score -= 12.0 * (1.0 - progress) - 2.0 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space only if it's truly unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // partially usable
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 / (1.0 + slack);
        } else {
            // next item can't follow here; mild penalty scaled by how close we are
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * gap / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item is
    // large or existing bins would leave big waste.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual < item_size as f64) as f64;
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        // Opening a new bin is attractive when existing residuals are small,
        // item is large, or many bins are already open (consolidation pressure).
        let attractiveness = 60.0
            - 0.5 * waste_elsewhere
            - (item_size as f64 - 50.0).max(0.0) * 0.6
            - 20.0 * pressure
            - 10.0 * (1.0 - progress);
        score = 60.0 + attractiveness.max(-50.0);
    }

    // Mild global regularization: prefer bins whose residual is far from the mean
    // (reduces fragmentation of typical-sized gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for more-filled bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins deep (low post_residual); later, tolerate
    // larger residuals since future items may fill them.
    let p = progress;
    let poly = 1.0 + 0.9 * p - 1.7 * p * p + 1.3 * p * p * p;
    score *= poly.max(0.2);

    // Smooth reward for tight fits: quadratic decay of the wasted-space term.
    let tight = 1.0 - norm_post;
    score -= 18.0 * tight * tight * (1.0 - 0.5 * p);

    // Penalize residuals that cannot fit the lookahead item (dead space),
    // with a smooth cubic ramp based on the size of the miss.
    if next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 12.0 + 40.0 * miss * miss * miss;
    } else if next_item_size > 0 {
        // Small smooth bonus if the next item fits exactly in the post residual.
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (-6.0 * gap).exp();
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * p;
    }

    // Mild penalty when this bin's residual deviates from the mean residual,
    // encouraging residual homogenization across open bins.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score = cap * (0.9 + 0.1 * p) + 6.0 * crowd.sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes get strong bonuses.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Integer-division thresholds: residual buckets of size 10
        let bucket = pr / 10;
        // Penalize residuals that are "dead": too small for the smallest plausible item
        if pr < 10 {
            score += 500.0;
        } else {
            // Harmonic compatibility: can next_item_size fit into the residual?
            if next_item_size > 0 && next_item_size <= pr {
                // Reward proportional closeness of fit for the lookahead item
                let tight = (pr as f64 - next_item_size as f64) / cap;
                score -= 60.0 * (1.0 - tight);
            } else if next_item_size > 0 {
                score += 15.0; // next item cannot use this residual
            }
            // Modulo arithmetic on residual: residuals congruent to common size classes
            let m = pr % 10;
            if m == 0 {
                score -= 20.0; // round residuals are more reusable
            } else if m >= 7 {
                score += 8.0;
            }
            // Reward small residual buckets mildly (tight packing)
            score -= (10 - bucket.min(10)) as f64 * 5.0;
        }
    }

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / cap;
    score -= 40.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins generally, less as pressure grows
        score += 250.0 - 15.0 * pressure - 50.0 * progress;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 60.0; // existing residuals too small for next item
        }
    }

    // Discourage scattering across many bins when mean residual is large
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.3 * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A post_residual that is too small to hold even the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residual that cannot fit the next item (when known) is likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins that can also accommodate the lookahead item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless the item simply does not fit well anywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // (late in the stream, waste matters more; early, consolidation matters more).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 20.0 * progress;
        // If the item is large and mean residual across bins is low, opening a new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 35.0;
        }
        // Large items fit better in a fresh bin than leaving fragmented gaps.
        if item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Slight preference for bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        // Gentle reward for near matches, scaled by proximity.
        if gap <= 15 {
            score -= 20.0 * (1.0 - gap as f64 / 15.0);
        }
        // Penalize leaving a residual too small for typical future items (dead space).
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < next_item_size {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave large unusable residue
    // or the lookahead fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual > 0 && (post_residual as i64 - next_item_size as i64).unsigned_abs() > 30;
        let dead = post_residual < 10 && post_residual > 0;
        if bad_fit || dead {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // Prefer tighter (smaller-residual) bins relative to the mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream, allow more aggressive bin spreading; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward chain fits: if the next item also fits in the leftover space,
    // this bin is doing double duty -> strongly favor it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.3 * (bin_capacity as f64 - chain_tightness);
    }

    // Penalize dead space that nothing typical can use.
    // Space below the smallest plausible item (10) is pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward: leaving exactly zero or a tiny sliver.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let dead = post_residual as f64;
        if dead >= 10.0 {
            score -= 20.0 + 0.2 * dead;
        }
    }

    // New-bin candidate (untouched bin): score it as a fallback.
    // Prefer reusing open bins when the fit is decent; prefer a fresh
    // bin when every open bin would leave large unusable fragments.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows as stream matures and
        // as many bins are already open (fragmentation risk).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity - item_size) as f64 + 12.0 + 15.0 * progress + 0.5 * open_bins_count as f64;

        // A fresh bin is attractive if the item is large relative to
        // capacity (open bins likely to become fragmented anyway).
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 18.0 * (large_item - 0.6) / 0.4;
        }
        // If mean residual across open bins is low, reuse is scarce;
        // a new bin is relatively more sensible.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    } else {
        // Reusing an open bin: mild bonus scaled by how full it gets.
        let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;

        // Discourage leaving residuals just above small-item sizes that
        // future items are unlikely to slot into precisely.
        let r = post_residual;
        if r >= 10 && r <= 15 {
            score += 6.0;
        }
    }

    // Late-stream consolidation: near the end, prefer tightening
    // existing bins over spreading items out.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    if horizon > 0.8 {
        score -= 5.0 * (horizon - 0.8) / 0.2 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress * 0.5;
    score += 30.0 * coupling;

    // Penalize large dead space quadratically, smoothed by progress
    score += 0.5 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: penalize if next item cannot use the resulting post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 8.0 * (ns - pr) / bin_capacity as f64;
        } else {
            score -= 6.0 * (1.0 - (ns / pr.max(1.0)));
        }
    }

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 5.0 * dev * dev;

    // Prefer consolidating into fewer bins when many are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "usable" residue
    // classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr % 10 == 0 { class_bonus += 6.0; }
    if pr % 20 == 0 { class_bonus += 4.0; }
    if pr % 25 == 0 { class_bonus += 3.0; }
    if pr % 50 == 0 { class_bonus += 4.0; }
    score -= class_bonus;

    // Dead-space penalty: leftovers in awkward ranges (1..10, 11..19 excluding 15, etc.)
    if pr > 0 && pr < 10 { score += 12.0; }
    if pr >= 10 && pr < 20 && pr != 10 { score += 4.0; }
    if pr > 80 { score += 2.0; } // huge leftover: wasteful placement

    // Perfect fit reward
    if pr == 0 { score -= 25.0; }

    // Tight fit: item fills most of the bin
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 8.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic class of the two-item chain leftover
            let chain = post_residual - next_item_size;
            if chain % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot fit here; penalize leaving residue that wastes class
            score += 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets a mild default preference,
    // scaled down when good open-bin options exist (many fitting bins, low mean residual).
    if bin_residual == bin_capacity {
        let base = 18.0;
        let pressure = (open_bins_count as f64).ln().max(0.0) * 1.5
            + (mean_residual / bin_capacity as f64) * 10.0;
        score += base - pressure;
        // early in stream, opening new bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    } else {
        // prefer fuller bins among open ones (best-fit-like pressure)
        let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= used_frac * 5.0;
    }

    // Integer division threshold: post_residual in [capacity/4, capacity/2] is a
    // "sweet spot" for typical mid-size items (10..80 range).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr >= quarter && pr <= half && pr % 5 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded.
        score += open_bins_count as f64 * 5.0 + mean_residual * 0.3 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else {
        score -= open_bins_count as f64 * 2.0;
    }

    // Slight preference for fuller bins relative to fleet mean.
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect fits (post residual near zero).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize large dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Compare post residual against mean residual across open bins:
    // prefer bins whose residual stays close to the mean (balanced packing),
    // but avoid leaving huge residuals in nearly-empty bins.
    let pr = post_residual as f64;
    let diff = pr - mean_residual;
    score += 0.15 * diff.abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only allow opening a new bin when the item is large
    // relative to remaining residuals or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score += 90.0
            - 70.0 * scarcity
            - 60.0 * large_item
            - 25.0 * progress
            + 5.0 * open_bonus;
    }

    // Mild preference for tighter bins early in the stream.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (post_residual as f64 + 1.0).ln();

    // Penalize dead space: post-residual that no future item (min size 1) can plausibly use.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 20.0).powi(2);
        score += dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post-residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.05 * pressure;

    // Time horizon: early in the stream, be more willing to open new bins (exploration);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    // New-bin candidate handling: empty bin is attractive early or when this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early and when many bins are already open.
        let new_bin_cost = 25.0 - 8.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
        score = new_bin_cost + post_residual as f64;
        // If next item is large and won't pair well, opening fresh space is fine.
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 5.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 51..70 zone (hard to fill later).
    if post_residual >= 51 && post_residual <= 70 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted residual, but with non-linear (quadratic) coupling to progress.
    let mut score = pr + 0.9 * pr * pr / cap;

    // Smooth interaction: tight fits (small post_residual) are more valuable late in stream.
    let tightness = 1.0 - pr / cap; // 0..1, higher = tighter fit
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual diverges from mean residual (fragmentation penalty),
    // scaled by a smooth cubic in progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + progress * progress);

    // Lookahead: reward bins that can also fit the next item smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 6.0 * (1.0 - (fit_frac - 0.5) * (fit_frac - 0.5) * 4.0) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only fitting bin, smoothly ramped by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.3 + 0.7 * progress);
    }

    // Mild pressure to consolidate into fewer bins as stream advances.
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
