pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 40.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 12.0; // small gap, nearly unusable -> strongly reward filling to near-dead space
    } else if post_residual <= 25 {
        score += 6.0; // moderately small gap: mild penalty to prefer tighter fits elsewhere
    }

    // Reward bins whose residual after placement is still usable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(25) {
        score += 10.0; // creates gap the next item cannot use
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but allow new bin when existing residuals are large and fragmented
        if mean_residual > 60.0 && open_bins_count > 3 {
            score -= 25.0;
