        // reward using bins with residual close to the item (tight fit)
        score -= 5.0 * (1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64).min(1.0);
    }

    // Late in stream: consolidate, prefer existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core lookahead: strongly reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8; // penalize mismatch between leftover and next item

        // Perfect chain: item fits exactly, next item fills the remainder exactly.
        if post_residual == 0 || post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits here later; mild bonus scaled by tightness
            let tightness = 1.0 - gap / bin_capacity as f64;
            score -= 10.0 * tightness;
        } else {
            // next item cannot use the leftover: dead space penalty
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: just minimize leftover
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, prefer closing bins tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate: make it attractive only when current bins are quite full/fragmented.
    if bin_residual == bin_capacity {
        let avg_full = 1.0 - mean_residual / bin_capacity as f64;
        if avg_full > 0.75 {
            score -= 12.0 * (avg_full - 0.75) * 4.0; // open fresh bin when existing ones are packed
        } else {
            score += 10.0; // discourage opening new bins early
        }
    }

    // Slight preference for using already-open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin by the item.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits strongly.
    score -= 2.0 * fill * fill * (bin_residual as f64);

    // Penalize large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect closure bonus
    } else if post_residual < 20 {
        score -= 4.0;
    } else if post_residual > 60 {
        score += (post_residual as f64 - 60.0) * 0.15; // wasteful big hole
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover: mild penalty, worse early (plenty of bins ahead)
            score += 2.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin, but allow it
    // when no existing bin fits well (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 + 10.0 * (1.0 - progress);
        let scarcity_bonus = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += base_penalty - scarcity_bonus;
        // Prefer new bin for huge items that would leave awkward leftovers elsewhere.
        if item_size > 50 && (item_size % 10 != 0) {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate larger residuals (keep bins flexible);
    // late, penalize residual more sharply (polynomial ramp).
    let ramp = 0.5 + 2.0 * progress * progress;
    score += norm_pr * cap * ramp * 0.3;

    // Lookahead coupling: reward if next item fits in post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // penalize residuals that waste the next item's fit chance
        score += (next_item_size as f64 - pr).min(cap) * 0.15;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to keep tightest fit dominant
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean residual interaction: prefer bins below mean residual (tighter bin)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening unless open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.6 + 0.5 * fragmentation) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket into capacity fractions (eighths).
    let class = (post_residual * 8) / bin_capacity.max(1);
    let class_mid = (class as f64 + 0.5) * cap / 8.0;

    // Reward residuals in "useful" harmonic classes (can hold mid-size items).
    let usable = if post_residual >= 50 { 1.0 } else if post_residual >= 25 { 0.5 } else { 0.0 };
    score -= 12.0 * usable;

    // Penalize dead space: residual too small for the smallest plausible item (1).
    if post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // prefer residual classes that keep next item's post-residual usable
            let next_post = post_residual - next_item_size;
            let next_class = (next_post * 8) / bin_capacity.max(1);
            score -= 6.0 * (next_class as f64);
            score -= 8.0 * (next_post as f64 / cap);
        } else {
            // next item won't fit here: mild penalty proportional to mismatch
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Exact fit reward (item fills bin completely).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Modulo logic: reward residuals that are "harmonic" multiples of common sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Prefer bins with residual below mean (consolidate waste), penalize above-mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Progress-aware: late in stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus progress-scaled penalty
        score += 30.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps
    // (gaps that likely cannot host future items of size >= 10).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0 + (10 - pr) as f64 * 8.0;
    } else if pr < 20 {
        // Moderate penalty for gaps in the 10..20 range (limited usability).
        score += (20 - pr) as f64 * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + pr as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: penalize opening/using bins when many are open,
    // encouraging consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Dead space relative to mean residual: penalize bins whose leftover
    // deviates badly from the fleet average (fragmentation indicator).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement; if post residual is just barely too small
    // for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate adjustment: an empty bin has large post_residual,
    // so its raw score is already high; add a fixed offset so it only wins
    // when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact matching of
    // post_residual with the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Exact match -> near-perfect chain placement.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits, but leaves leftover: penalize the
            // double-leftover (post_residual - next_item_size) extra.
            let leftover_after_next = post - nxt;
            score += 0.8 * leftover_after_next;
            score -= 15.0; // still better than blocking the next item
        } else {
            // Next item cannot fit in this bin's leftover: penalize
            // proportionally to how badly the chain is broken.
            score += 1.5 * (nxt - post);
        }

        // If the next item fits exactly now (bin_residual == next),
        // placing current item ruins that; small penalty to discourage.
        if bin_residual == next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: just minimize leftover, already captured by base score.
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (tighter bins get filled first, preserving slack bins for hard items).
    score += 0.35 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight late-stream tightening: as the stream progresses, be more
    // aggressive about filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress;

    // Discard tiny unusable dead space more harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64) * 0.2;
    }

