    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening a new bin when a
    // reasonable fit exists, but encourage it when residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Open a new bin when open bins are nearly full / fragmented.
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            0.0
        };
        if fragmentation < 0.15 {
            score -= 35.0; // open bins nearly full -> new bin is fine
        }
        // Late in stream, new bins are cheaper than overstuffing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild preference for bins below mean residual (balancing).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Slight bias toward filling larger residual bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

