    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 0.5;
    score += 30.0 * poly;

    // Penalize dead space that next item cannot use (smooth interaction)
    let usable = if (next_item_size as f64) <= pr { pr - next_item_size as f64 } else { pr };
    score += 0.15 * (pr - usable) * (1.0 + progress);

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress) + 4.0;
    }

    // Mild penalty when this bin is far above mean residual (fragmentation pressure)
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // Slight bias toward keeping many bins consolidated
    score += 0.01 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls into.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
