    }

    // Modulo-class coupling: does post_residual align with the next item size?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 10.0; // perfect harmonic match for lookahead item
        } else if next_item_size < post_residual {
            // next item fits: reward tighter resulting residual
            let after2 = pr - nxt;
            score -= 4.0 * (1.0 - after2 / cap);
            if after2 < 10.0 {
                score -= 3.0; // chain of near-fits
            }
        } else {
            // next item won't fit here: penalize proportionally to how close we were
            score += 2.0 + 4.0 * (1.0 - (pr / nxt).min(1.0));
        }

        // Modulo resonance: post_residual shares remainder class with next item
        let m = next_item_size.max(1);
        if (post_residual % m) < 3 {
            score -= 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual as f64 as u32 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin gives a good fit (high post_residual there).
    if bin_residual == bin_capacity {
        // neutral baseline: score equals capacity; slightly worse than a
        // decent fit (post_residual < ~40) but better than wasting space.
        score = cap + 5.0;
        if item_size >= 50 && open_bins_count > 0 {
            score -= 10.0; // big items prefer fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // guaranteed pairable with lookahead
        }
    }

    // Fraction-band bonus: reward residuals that are exact capacity fractions
    // (50, 25, 75...) since they form reusable harmonic classes.
    let frac100 = post_residual % 25;
    if frac100 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (frac - 0.3).max(0.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in awkward gap zone).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space matters more when many bins are already open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is fine if no open bin fits well.
        if post_residual == 0 { score -= 35.0; }
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins tighter than the mean residual (better fit).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins where the item fills the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 600.0;
    }
    // Next item fits with small slack: mild reward proportional to tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= (30.0 * (1.0 - slack as f64 / bin_capacity as f64)).max(0.0);
    }
    // Next item does NOT fit in post_residual: penalize dead space creation,
    // scaled by how much of the residual would be wasted.
    else if next_item_size > 0 && next_item_size > post_residual {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 80.0 * waste_frac;
    }

    // Relative-to-mean coupling: bins tighter than average are more precious,
    // reward placing into them; looser-than-average bins penalized slightly.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev;
    } else {
        score += 0.25 * (-dev);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item {
            score += 40.0; // big items are fine in fresh bins
        } else {
            score += 200.0 + 100.0 * (1.0 - progress); // early stream: prefer open bins
        }
    }

    // Mild pressure on item size: prefer placing larger items into fuller bins.
    score += 0.1 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    // (items are >= 1, but small slivers waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 0.35 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual accommodates next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with slack -> favor filling existing ones.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual.max(1.0);
        score += 2.0 * rel;
    }
    score += 0.05 * open_bins_count as f64;

    // Prefer bins with residual close to item size (perfect fill).
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Coupling with stream progress: later in stream, penalize large residuals more
    score += pr * progress * (0.5 + 1.5 * norm_pr);

    // Reward tight fits: subtract a smooth function of item fill ratio
    let fill = item_size as f64 / cap;
    score -= 40.0 * fill * fill * (1.0 - progress * 0.5);

    // Penalize dead space that is too small to be useful (below min item size ~1..100 unknown, use smooth term)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 20.0 * dead * (1.0 - dead) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        score -= 15.0 * fits_next * (1.0 - progress);
        score += 10.0 * (1.0 - fits_next) * progress;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (avoid fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        score += 50.0 + 40.0 * (1.0 - progress) + 5.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into harmonic zones.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals in "dead" zones that few item sizes (1..=100) can still fill.
    // Residuals <= 10 are perfect (dead space zero-ish); 11..=33 hard to fill; 34..=50 fillable by mid items; >50 easy.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual <= 33 {
        score += 25.0; // awkward dead zone
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score -= 15.0; // large residual still useful
    }

    // Modulo-class coupling: residual in the same residue class as next item packs next step cleanly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            score -= 10.0; // lookahead still fits here
        } else {
            score += 12.0; // next item would not fit here -> deprioritize
        }
        // Harmonic class match: floor(post/25) == floor(next/25)
        if (post_residual / 25) == (next_item_size / 25) && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish, slightly favored early, penalized when many bins already fit.
    if bin_residual == bin_capacity {
        score = 45.0 + frac * 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
        if fitting_bins_count > 2 {
            score += 20.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Prefer tightest relative fill among ordinary bins.
    score -= (item_size as f64 / bin_residual as f64) * 20.0;

    // Mild tie-break toward bins below mean residual (consolidate fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Stream progression: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score -= 15.0; // tight fit is great
    }

    // Reward exact or near-exact fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // bonus if it fits snugly
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to lookahead
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize proliferation of bins slightly
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins below mean residual (consolidate into emptier bins)
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Slight preference for keeping large residuals available early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64) * (0.1 + 0.15 * progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 45.0; // discourage opening new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Strong reward decaying with gap; perfect match gives big bonus.
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)) - 0.5 * gap;
        // Extra bonus for exact match.
        if gap == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: dead space penalty.
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize wasting a large residual on a small item (poor fit).
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * waste * waste;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless nothing sensible fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening new bin; relax if many bins are badly fragmented
        // (mean residual low) or few fitting bins exist.
        let mut penalty = 20.0;
        if mean_residual < 25.0 {
            penalty -= 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 25.0;
        }
        // As stream progresses, be slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= 5.0 * progress;
        score += penalty;
    }

    // Mild preference for tighter bins relative to mean residual.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fragmentation pressure: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 && (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else if open_bins_count > 2 && (bin_residual as f64) < mean_residual * 0.5 {
        score += 4.0;
    }

    // Time horizon: early in the stream, opening bins is cheap (favor tight fits
    // elsewhere); late in the stream, avoid opening new bins at all costs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, heavily penalized late.
        score += 12.0 * progress + 5.0;
        if fitting_bins_count > 0 && progress > 0.6 {
            score += 20.0;
        }
    } else if progress > 0.8 && fitting_bins_count <= 2 {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling: penalize large post_residual, more so later in stream
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score -= 40.0 * poly * (0.5 + progress);

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Penalize dead space below next item's needs
    if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 {
            score += 0.6 * gap * (1.0 + progress);
        } else {
            score -= 0.3 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty for opening new bins when many open and mean residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 0.4 * open_bins_count as f64 + 0.1 * mean_residual;
        if progress > 0.5 {
            score += 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        return -10000.0;
    }

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Residuals that are "dead" (too small for typical min item 10) are penalized heavily.
    let dead = post_residual < 10;
    if dead {
        score += 500.0; // unusable sliver
    } else {
        // Reward residuals that are harmonic with likely future items (multiples of 10).
        let harmonic = post_residual % 10 == 0;
        if harmonic {
            score -= 15.0 + 0.1 * post_residual as f64;
        }
        // Class of post_residual via integer division: large leftovers are flexible.
        let class = post_residual / 25; // 0..4
        score -= class as f64 * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a new residual: judge its quality.
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score += 30.0; // creates future dead space
            } else if next_post % 10 == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; slight penalty unless this is the last-chance bin.
            score += 5.0;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest (post_residual already does).
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when existing bins are very full/fragmented
        // or this bin would leave a poor residual.
        let poor_fit = post_residual < 15;
        let crowded = mean_residual < 25.0;
        if poor_fit || (crowded && progress > 0.3) {
            score -= 60.0;
        } else {
            score += 200.0; // prefer existing bins when they fit reasonably
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;
    // Slight preference toward bins tighter than the mean (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are dead, but residuals below ~20 are practically unusable for typical items.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0; // heavy penalty for near-dead gaps
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit post-residual, the gap is likely dead — penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave bad gaps
    if bin_residual == bin_capacity {
        // neutral base; slightly penalized so existing decent bins win
        score = 25.0 + open_bins_count as f64 * 0.3;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // room for lookahead pairing in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: mildly penalize opening fresh bins so we only do so
    // when the fit into open bins would be truly poor.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Perfect fit is ideal: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement is a chain of perfect fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more dead space: partial reward.
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small to be useful (dead space).
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * waste;
            if post_residual < 10 {
                score += 20.0; // tiny unusable sliver
            }
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average keeps bins balanced and usable.
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, tighten packing: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Bonus if next item is large and still fits: excellent chain.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap;
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, adjusted by global state.
        score += 20.0;
        // If mean residual is high (open bins are roomy), opening new bins is wasteful.
        score += 0.4 * mean_residual;
        // Early in stream, opening bins is fine (building a portfolio); late, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins already open, discourage another.
        score += 1.2 * open_bins_count as f64;
    }

    // Time-horizon modulation: as stream progresses, prefer tighter packing (reward tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Mild preference for bins below mean residual (balance load, keep roomy bins for big items).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    // Prefer placing large items into fuller bins to preserve large residuals.
    if item_size >= 60 {
        score -= 6.0 * (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap); // how well item fills the bin

    // Base: penalize leftover space, with a non-linear (quadratic) dead-space cost
    let mut score = pr + (pr * pr) / cap;

    // Reward tight fits more strongly as the stream progresses
    score -= tightness * tightness * 20.0 * (0.5 + progress);

    // Smooth coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize very small residuals less);
    // late, prefer squeezing items into existing bins
    let flex = (pr / cap) * (1.0 - progress);
    score -= flex * 10.0;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - gap / cap);
    }

    // Penalize opening a new bin when plenty of bins are open and mean residual is large
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (5.0 + mean_residual * 0.05 * open_bins_count as f64 * (1.0 - progress));

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln() * fit_ratio * 2.0 * (1.0 - progress);

    // Small smooth jitter-free regularizer coupling fit ratio and progress
    score += fit_ratio * fit_ratio * 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets.
    let pr = post_residual;
    let class = match pr {
        0 => 0,                     // perfect fit
        1..=5 => 1,                 // nearly full, tiny waste
        6..=15 => 2,
        16..=25 => 3,
        26..=40 => 4,
        41..=60 => 5,               // half-full-ish, reusable
        _ => 6,                     // large residual, bin was small-fill
    };

    // Reward classes 0 and 1 heavily (tight packing), penalize mid classes.
    let class_adjust: f64 = match class {
        0 => -60.0,
        1 => -35.0,
        2 => -10.0,
        3 => 5.0,
        4 => 12.0,
        5 => -5.0,
        _ => 0.0,
    };
    score += class_adjust;

    // Modulo arithmetic on post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let rem = pr % quarter.max(1);
    if rem == 0 && pr > 0 {
        score -= 8.0; // residual aligns with quarter boundaries -> likely future fit
    }

    // Lookahead: does the next item fit the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 20.0 + 0.3 * slack;
        // Harmonic bonus if next item leaves another tiny residual
        if (pr - next_item_size) <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 10.0; // this bin can't host the lookahead either way
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // placement would create big dead space while many bins are open.
    if bin_residual == bin_capacity {
        // fresh bin: score = capacity, adjust by stream progress and congestion
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress); // early on, fresh bins are cheap
        if open_bins_count > 4 {
            score += 0.5 * open_bins_count as f64; // congestion penalty
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for large lookahead
        }
    } else if pr > 60 && fitting_bins_count > 2 {
        // placing a small item leaving a huge residual when alternatives exist
        score += 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is already "used up"; prefer filling it.
    if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 6.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score += 4.0;
    }

    // Integer-division harmonic threshold: post_residual / item_size ratio.
    if item_size > 0 {
        let ratio = pr / item_size;
        if ratio >= 2 {
            score += 3.0 * ratio as f64; // item too small for this bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual is "dead" if it is too small to hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 2 {
        score += 1000.0; // unusable sliver -> strongly penalize
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 50.0 + 0.5 * next_item_size as f64;
    }

    // Reward very tight fits (post_residual near zero but still usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are large/wasteful elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        // Late in the stream, opening new bins is less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild attraction toward bins whose residual is close to the mean (balanced packing).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match strongly rewarded; near matches partially rewarded.
        if gap == 0.0 {
            score -= 40.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 15.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot follow in this bin: penalize proportional to leftover waste.
            score += 8.0 * gap / (bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness fit, reward minimal post_residual.
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter (less residual) than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse; make new bin unattractive).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 + 5.0 * fitting_bins_count as f64 };
        score += pressure;
        // Early in stream, opening bins is cheap-ish; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for leaving large residuals that invite fragmentation.
    score += 0.05 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let pr = post_residual as f64;
        score -= 25.0 * (1.0 - pr / bin_capacity as f64).powi(3);
        // Penalize dead space that is too small for typical future items.
        if pr < 10.0 {
            score += 12.0;
        } else if pr < 20.0 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to overshoot
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
        // If next item is large, prefer conserving space in roomy bins.
        if nxt > bin_capacity as f64 * 0.5 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into bins below mean residual (balancing).
    let cap = bin_capacity as f64;
    let mr = mean_residual / cap;
    let this = bin_residual as f64 / cap;
    if this > mr {
        score -= 10.0 * (this - mr);
    } else {
        score += 6.0 * (mr - this);
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits) to keep
    // flexibility; late in stream, just fill whatever fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 0.6 + 0.8 * progress;

    // New-bin candidate handling: opening a fresh bin is attractive early or when
    // the fit into existing bins is poor; otherwise discourage it.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let base = 20.0 + 0.5 * waste;
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score = base * (1.0 - openness) * (1.0 - 0.5 * progress);
        // If the next item is huge and would need a fresh bin anyway, opening now is fine.
        if next_item_size >= bin_capacity * 2 / 3 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let fit_frac = fitting_bins_count as f64 / open_bins_count.max(1) as f64;

    let mut score = pr as f64;

    // Non-linear coupling: quadratic waste penalty growing with stream progress
    let waste_curve = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += 60.0 * waste_curve;

    // Reward tight fits (small post_residual) increasingly over time
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 40.0 * progress;
    }

    // Penalize bins that leave space unusable for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // post_residual can host next item: reward smoothly by closeness of fit
            score -= 15.0 * (1.0 - ((pr - nx) / cap)).powi(2);
        } else {
            // dead space relative to lookahead: penalty coupling with progress
            score += 20.0 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: baseline cost of opening a bin, reduced late in stream
    if is_new_bin {
        score += 35.0 * (1.0 - 0.5 * progress);
        // attractive only if the item would otherwise leave a very poor fit
        score -= 20.0 * (1.0 - fit_frac) * progress;
    } else {
        // Slight preference toward bins whose residual deviates from mean (balance)
        score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let band = post_residual / eighth; // 0..=8 harmonic class

    // Penalize residuals in "dead zones": too small for the smallest plausible item (1..10)
    if post_residual < 10 {
        score -= 30.0 * (10 - post_residual) as f64; // near-perfect fill is excellent
    } else {
        // Wasted-space penalty grows superlinearly inside mid bands
        score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Harmonic pairing: reward residuals that exactly complement common item classes
    // (multiples of 25 and 50 are natural "harmonics" of C=100)
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 - 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 0.15 * (next_item_size.min(post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheaper late
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress - 10.0 * (open_bins_count as f64).ln().max(0.0);
        // opening a bin is attractive if item is large and nothing fits well
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild diversity pressure: many open bins with high mean residual -> prefer tight fills
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate penalty for gaps that are hard to fill by typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual > 60 {
            score -= 5.0;
        }
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
