    }
    // Penalize if next item almost fits but not quite (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Post-residual could still host the next item: mild reward,
        // stronger the closer post_residual is to next_item_size.
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot fit here afterwards: penalize if we leave
        // unusable dead space (small post_residual).
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += 20.0 * (10.0 - waste);
        }
    }

    // Penalize leaving dead space relative to the mean residual of open bins:
    // a post_residual well below mean_residual means this bin becomes an outlier
    // of trapped space.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when all open
    // bins would leave very small unusable residuals. Give it a mild penalty
    // so existing bins with decent fits win, but not so large that a
    // near-perfect existing fit can't be beaten by a fresh bin when needed.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening bins is cheap-ish; late, avoid sprawl.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If many bins are open, discourage opening even more.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer tighter fits generally: reward small post_residual slightly,
    // but not so much that it overrides the lookahead logic.
    score -= 0.05 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, but dead space that
    // no future item (min size ~1) can use is pure waste. Penalize residuals
    // that are "unusable" relative to typical item granularity.
    if post_residual > 0 && post_residual < 10 {
        // tiny sliver: nearly perfect packing, strong reward
        score -= 6.0;
    } else if post_residual == 0 {
        score -= 10.0; // exact fill
    } else {
        // mid-range leftover: scale penalty by how "wasted" it is
        score += 0.05 * (post_residual as f64 - 10.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and current bins are crowded. Penalize the empty-bin
    // candidate (bin_residual == bin_capacity) generally.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - crowding);
        // high pressure (big item, low mean residual) lowers the penalty
        score += 25.0 * (1.0 - pressure);
        // early in the stream, new bins are cheap; later, avoid bin sprawl
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * t;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // big reward; if next item is close to post residual, mild reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            score -= 5.0 / (1.0 + diff);
        } else {
            // next item won't fit here anyway; slight reward for small residual
            score -= 1.0 / (1.0 + diff);
        }
    }

    // Prefer bins whose residual is below the mean (consolidate waste into
    // fewer bins rather than spreading it).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 0.5 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Many open bins: encourage filling existing ones harder.
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize very small dead space that likely becomes unusable (smooth term)
    let dead = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 30.0 * dead;

    // Reward tight fits: post_residual near zero
    score -= 20.0 * (-pr * pr / 200.0).exp();

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (pr / (next_item_size as f64).max(1.0)).min(1.0));
    }

    // Slight preference for filling bins with larger residuals relative to mean
    score -= 2.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Mild penalty for proliferating open bins early in the stream
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal wasted space after placement.
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in the same residue class
    // mod 10 are "compatible" with common item sizes; reward tiny residuals hard.
    let post_class = post_residual % 10;
    if post_class == 0 {
        score -= 18.0; // perfectly harmonic residual (10,20,...)
    } else if post_residual <= 10 {
        score -= 25.0; // dead space below the smallest item size is harmless
    } else {
        // penalize residuals that fall in "dead zones" (too small for many sizes)
        score += post_class as f64 * 0.8;
    }

    // Integer-division thresholds on post_residual relative to item size classes.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual < quarter && post_residual > 10 {
        score += 12.0; // creates near-unusable sliver
    } else if post_residual >= half {
        score -= 6.0; // leaves a half-bin: still very usable
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit anywhere else, avoid ruining it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_slack = post_residual - next_item_size;
            if next_slack <= 10 {
                score -= 20.0; // chain a perfect pair
            } else {
                score -= (next_item_size as f64) * 0.15;
            }
        } else {
            // next item won't fit here regardless; mild bonus for closing this bin tight
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when placement in
    // existing bins would create bad dead space, or many bins are open with
    // fragmented residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (scaled mildly since bins are counted anyway).
        score += (bin_capacity as f64) * 0.9;
        // Cheaper to open a bin early in the stream (more future items to fill it).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
        // If existing bins are fragmented (high mean residual spread), new bin ok.
        if mean_residual < (bin_capacity as f64) * 0.25 && open_bins_count > 2 {
            score -= 15.0;
        }
        // Large items (harmonic class 50+) pair well in fresh bins.
        if item_size > half {
            score -= 10.0;
        }
        // If next item is large too, a fresh bin can host both.
        if next_item_size > half && (item_size + next_item_size) <= bin_capacity {
            score -= 22.0;
        }
    } else {
        // Reward packing into bins whose residual is in a harmonic class with the item.
        let item_class = item_size % 10;
        if bin_residual % 10 == item_class {
            score -= 8.0;
        }
        // Prefer filling bins with low residual (tighten them up) to reduce fragmentation.
        score += (mean_residual - post_residual as f64).max(0.0) * 0.2;
        // Slight penalty for spreading across many open bins.
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps smaller than the smallest
    // plausible upcoming demand are "dead space". Penalize them super-linearly.
    let min_demand = if next_item_size > 0 { next_item_size.min(20).max(1) } else { 10 };
    if post_residual > 0 && post_residual < min_demand {
        score += (min_demand - post_residual) as f64 * 8.0;
    }

    // Perfect fit bonus: strongly reward leaving nothing behind.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-fit reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many are already open,
    // and encourage consolidating into existing bins.
    if bin_residual == bin_capacity {
        // Candidate new bin: only attractive if nothing else fits or it's early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 40.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open a bin
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    // relative to the mean residual of open bins.
    let slack = (bin_residual as f64 - item_size as f64).abs();
    if slack < mean_residual {
        score -= (mean_residual - slack) * 0.3;
    } else {
        score += (slack - mean_residual) * 0.3;
    }

    // Lookahead: if the next item would fit exactly into the post residual,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= chain_tightness * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Perfect fits are extremely valuable
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin (only one fitting bin): strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mildly discourage opening new bins when reasonable fits exist
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item is large and post_residual is large, new bin is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * (1.0 - tightness) * (1.0 - tightness) * (bin_capacity as f64);

    // Penalize post-residuals that are unusable dead space (< next item or < 10).
    let min_future = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && (post_residual as u64) < (min_future as u64) {
        score += 12.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= 0.4 * (open_bins_count as f64) * (1.0 - tightness);

    // Prefer bins with below-mean residual (leave large residuals for future items).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: favor keeping flexibility (mild penalty on very full usage),
    // late in stream: favor tight packing aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: discourage unless current bin fits are poor.
    if bin_residual == bin_capacity {
        // Baseline new-bin score; adjusted by stream state.
        score = bin_capacity as f64 * 0.75
            + 3.0 * (open_bins_count as f64)
            - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            score -= 5.0; // perfect fill followed by a big item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but penalize very small residuals increasingly (non-linearly)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, push toward tight packing.
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap * 0.5;

    // Penalize dead space relative to mean residual across open bins (smooth coupling)
    let mean_norm = mean_residual / cap;
    score += 0.3 * (norm_pr - mean_norm).abs() * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into the post-residual (smooth quadratic fit)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            let overflow = (nxt - pr) / cap;
            score += 5.0 * overflow * overflow * cap;
        }
    }

    // Mild penalty for proliferating bins relative to stream progress
    score += (open_bins_count as f64).ln().max(0.0) * 0.2;

    // New-bin candidate: make empty bins moderately attractive only when residual is tight
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions and integer division thresholds.
    let quarter = bin_capacity / 4;           // 25
    let half = bin_capacity / 2;              // 50
    let three_quarter = 3 * bin_capacity / 4; // 75

    // Dead-space penalty: leftover in (0, 10] is nearly unusable (min item is 1,
    // but small leftovers waste capacity) — penalize tiny-but-nonzero leftovers.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // Perfect fit: zero leftover is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic bucket penalty on post_residual via integer division thresholds.
    if post_residual < quarter {
        score += 35.0; // cramped bin, low future utility
    } else if post_residual < half {
        score += 12.0; // moderate leftover
    } else if post_residual < three_quarter {
        score -= 10.0; // roomy leftover, good bin
    } else {
        score -= 18.0; // very roomy, keep flexible
    }

    // Modulo-arithmetic class: leftover congruent to common item sizes is reusable.
    // Leftovers in {0, 10, 20, 25, 30, 40, 50, 60, 75, 80} are "harmonic" residuals.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0;
    if harmonic {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        score += 8.0; // odd leftover, harder to fill exactly
    }

    // Lookahead coupling: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain a perfect fit
        } else if next_item_size <= post_residual {
            // next item fits; reward proportional to how "harmonic" the chain is
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
            if chain_left <= 10 && chain_left > 0 {
                score += 25.0; // chain creates dead space
            }
        } else {
            score += 20.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless leftover would be tiny dead space).
    if fitting_bins_count == 1 {
        score -= 45.0;
        if post_residual > 0 && post_residual < 10 {
            score += 55.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer it
    // when existing bins would produce bad leftovers; otherwise penalize opening.
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful when a good fit exists elsewhere.
        if item_size <= half {
            score += 55.0; // small/medium items should fill existing space
        } else {
            score += 10.0; // large items may warrant a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0; // new bin can pair this item with the next one
        }
        // Late in the stream, avoid opening bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mean-residual coupling: when average leftover is already large, prefer
    // consolidating into bins below the mean (tightening them).
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.4 * open_bins_count as f64;

    // Mild preference for placing larger items into tighter bins.
    score -= 0.2 * item_size as f64 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Assume typical useful item sizes start
    // around 10-15% of capacity; a gap below that is near-dead space.
    let dead_threshold = bin_capacity as f64 * 0.12;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits relative to bin capacity (waste fraction penalty).
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // but allow it when many are open (fragmentation control).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure;

    // New-bin candidate handling: an empty bin gets a baseline cost that
    // shrinks as the mean residual across open bins grows (open bins are
    // fragmented, so a fresh bin is more attractive).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 - fragmentation * 30.0 + pressure;
        // Late in the stream, opening a new bin is less costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mild penalty scaled to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += shortfall * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (post_residual close to 0) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the NEXT item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item can also fit here -> strong reward proportional to how exact.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit -> penalize wasted space relative to next item size.
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals in line with fleet average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev.signum() * dev.abs().sqrt();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless residual would be tiny.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 20.0 + 0.5 * waste;
        if fitting_bins_count > 0 && (bin_residual as i64 - item_size as i64) > 30 {
            score += 15.0; // discourage new bin when fit leaves lots of usable space
        }
    }

    // Mild pressure early in the stream to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item can fit into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0 * (1.0 - nxt / cap);
        } else {
            score += 4.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // later, accept more to consolidate
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * (post_residual as f64) * 0.3;
    score -= t * 2.0 * tightness;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean (balance workload)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate: only open a new bin when current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > cap * 0.5;
        if poor_fit && (fitting_bins_count <= 2 || (post_residual as f64) > mean_residual) {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual
    let r = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger residuals (bins can be filled later);
    // late in the stream, penalize residual quadratically (dead space is final).
    let progress_weight = 1.0 + 3.0 * progress * progress;

    let mut score = post * progress_weight;

    // Non-linear interaction: residual^2 scaled by progress — amplifies penalty
    // for wasted space as the stream matures.
    score += (r * r) * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream.
    let tightness = (cap - post) / cap;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= cap as f64 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fill_next = nx / post.max(1.0);
            score -= fill_next * nx * (0.4 + 0.6 * progress);
        } else {
            // Next item won't fit here; penalize leaving a residual close to nx (blocked space).
            let gap = (nx - post) / cap;
            score += gap * cap * 0.25 * progress;
        }
    }

    // Mild penalty when this bin's residual is far from the mean residual
    // (prefer balancing residual distribution across open bins).
    let dev = (post - mean_residual).abs();
    score += dev * (0.05 + 0.15 * progress);

    // Slight preference for already-open bins over opening new ones,
    // decaying as the stream progresses (late stream: consolidation matters less).
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space severity classes).
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor() as i32; // 0..8 harmonic class

    // Penalize awkward leftovers: residuals that are small but not tiny
    // (e.g., 1..20) are nearly unusable for typical items.
    match class {
        0 => score -= 30.0,            // perfect fit, reward heavily
        1 => score += 10.0,            // 0-12.5%: dead space, penalize
        2 => score += 4.0,             // 12.5-25%
        3 => score -= 2.0,             // 25-37.5%: moderately usable
        4 => score -= 6.0,             // 37.5-50%: good target zone
        5 => score -= 3.0,
        _ => score -= 1.0,             // large residual: easy to fill later
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item-size increments (10s grid) are more likely reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact/near-exact harmonic match with next item.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap <= 10 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to waste.
            score += 3.0;
        }
    } else {
        // Last item: just minimize post residual.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which already scores high; add a fixed penalty so we only open a
    // new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
    } else {
        // Slight preference for tighter existing bins via mean residual.
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Stream progression: late in the stream, consolidate more eagerly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual can still fit the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // stranded gap that next item cannot use
        }
    }

    // Pressure from number of open bins: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: make it unattractive unless open bins are scarce
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * -2.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    // Slight preference for tighter existing fits relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // partial reward proportional to how close post_residual is to next item
            let closeness = 1.0 - (post_residual as f64 - next) / (bin_capacity as f64);
            score -= 25.0 * closeness * closeness;
        } else {
            // next item cannot fit here; penalize dead space it would leave
            score += 15.0 * (next - post_residual as f64) / next.max(1.0);
        }
    }

    // Penalize post_residual far above mean residual (wasteful large leftover)
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits (small post_residual)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins with decent fit exist
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // but allow new bin if lookahead suggests poor fits everywhere
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight progression-aware bias: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong reward to use it, avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: prefer the fullest (smallest residual already in score),
    // add mild penalty to spread usage evenly.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post-residual becomes dead space relative to next item: penalize waste.
            score += 0.15 * (post_residual as f64 - (next_item_size as f64).min(post_residual as f64));
        }
    }

    // Dead-space penalty: residuals too small for typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Default penalty for opening a new bin.
        score += 20.0;
        // Late in stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If current bin fit is terrible (large leftover), new bin becomes attractive.
        if post_residual > 40 {
            score -= 25.0;
        }
        // If next item is large and won't fit anywhere after placement, new bin helps.
        if next_item_size > post_residual && next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Global fragmentation pressure: when mean residual is low and bins are many,
    // prefer placements that keep residual usable.
    if mean_residual > 0.0 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * deviation;
    }

    // Slight preference for filling bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly coupled with progress.
    let mut score = post * (1.0 + 0.6 * progress * x);

    // Penalize large dead space more aggressively as the stream advances.
    score += 40.0 * progress * x * x;

    // Smooth interaction: waste relative to mean residual across open bins.
    let waste = (post as f64 - mean_residual) / cap;
    score += 25.0 * waste * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item could exactly fill post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 20.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += 0.5 * (open_bins_count as f64) * x * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: small post_residual that no item (min size ~1..10) can use.
    // Class boundaries at multiples of 25 (capacity quarters).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny unusable sliver
    } else if pr < quarter {
        score += 15.0;
    } else if pr == quarter {
        score -= 20.0; // quarter-exact residual is a harmonic sweet spot
    } else if pr == half {
        score -= 15.0; // half-exact residual also reusable
    }

    // Modulo-10 harmony: residuals divisible by 10 pair well with typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0; // chain placement possible
            // extra reward for exact chaining (post_residual == next_item_size)
            if next_item_size == pr {
                score -= 40.0;
            }
        } else {
            score += 20.0; // next item can't follow here; dead-end risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize slightly so it's only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin fits, new bin must win (fitting_bins_count would be 0 for others)
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
    }

    // Congestion: many open bins with large mean residual -> prefer tightening existing bins.
    if open_bins_count > 4 && mean_residual > cap * 0.4 {
        score += 5.0 * (open_bins_count as f64).ln();
    }

    // Late-stream conservatism: keep residuals round as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized. A gap is "dead" if it cannot hold a typical item.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Dead space: waste, but at least the bin was packed tightly.
        // Slight reward for near-perfect packing.
        score -= 20.0 * (1.0 - (post_residual as f64) / dead_threshold);
    } else {
        // Usable residual: penalize proportionally to how much of the bin remains
        // (larger leftover = worse fit), with a non-linear squaring to punish loose fits.
        let frac_left = (post_residual as f64) / (bin_capacity as f64);
        score += 30.0 * frac_left * frac_left;
    }

    // Reward filling the bin well (high fill ratio of current placement).
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= 25.0 * fill;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 15.0 * next_fit_quality;
    } else if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
        // Post residual cannot host next item: mild penalty unless it's near-dead anyway.
        if post_residual as f64 >= dead_threshold {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize candidates in bins when many bins are open,
    // pushing toward consolidation into fewer bins (tighter fits win anyway).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean residual coupling: prefer bins with residual below the mean
    // (tighter than average bins get priority).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a decent fit
        // or when open bins would leave large dead space.
        let best_possible_leftover = if bin_capacity >= item_size { bin_capacity - item_size } else { 0 };
        let new_bin_waste = best_possible_leftover as f64;
        // Base cost of opening a new bin grows with number of open bins.
        score = 100.0 + new_bin_waste + 2.0 * (open_bins_count as f64);
        // If the current bin would be the last chance, discourage new bin strongly.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // Late in the stream, slightly discourage new bins (cleanup effect).
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
