    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Reward leaving exactly the space the next item needs
        if post_residual as u32 == next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: early in stream, be more conservative (favor new bins for large items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate scoring: baseline slightly above good fits
        score = bin_capacity as f64 * 0.5 + 10.0 - 6.0 * progress;
        if item_size > 60 {
            score -= 5.0; // large items fine in fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0; // new bin can host current + next
        }
        if fitting_bins_count <= 1 {
            score -= 12.0; // no good alternative, opening new bin is fine
        }
    }

    // Global state: many open bins -> prefer consolidation into existing bins
    score += 0.3 * open_bins_count as f64;

    // Mean residual coupling: if this bin is below-average residual (tighter than average), favor it
    score -= 2.0 * (mean_residual - post_residual as f64).max(0.0).min(50.0) / 10.0;

    // Mild penalty for very loose fits late in the stream
    if tightness < 0.5 && progress > 0.5 {
        score += 5.0 * (0.5 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let sz = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * pr * (1.0 - progress) - pr * progress * (1.0 - pr);
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tight = 1.0 - pr;
    score -= tight * tight * (0.5 + progress) * 10.0;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next = next_item_size as f64 / cap;
    let waste = if next > 0.0 { (pr - next).max(0.0) } else { 0.0 };
    score += waste * waste * (1.0 + progress) * 20.0;

    // Last-chance bin: smooth polynomial bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress * (1.0 - pr);
    }

    // Mild pressure toward consolidating into existing bins over time
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Prefer bins below mean residual early, above later (smooth quadratic term)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * (progress - 0.5) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does it fall in?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space classes: residuals in (0,10] are nearly unusable -> reward heavily.
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 40 {
        score -= 4.0;
    } else if post_residual <= 70 {
        score += 6.0; // mid-band: moderately wasteful
    } else {
        score += 14.0; // large leftover: poor fit for this item
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (10, 20, 25, 50) are "harmonic" and reusable.
    let h = post_residual % 10 == 0 || post_residual % 25 == 0;
    if h && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to tightness of that future fit.
            let future_left = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - future_left / cap);
            // Harmonic exactness: next item closes the bin exactly.
            if post_residual == next_item_size {
                score -= 20.0;
            } else if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit: this bin risks becoming dead space.
            score += 8.0 + 10.0 * (ni / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.05 * (bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are scarce or the current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty so new bins lose against decent fits.
        score += 30.0;
        // Relax penalty early in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        score -= 3.0 * open_bins_count as f64;
        // If mean residual of open bins is small, a new bin is more attractive.
        score -= (mean_residual / cap).max(0.0) * 10.0;
        // If next item is large, having a fresh bin helps.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with residual below mean.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..=100 unknown,
    // assume small gap threshold) are dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64 / 20.0).min(1.5);
    score += pressure * (bin_residual as f64 - post_residual as f64) * 0.3;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins open or mean residual is low
        // (existing bins nearly full), and lookahead item is large.
        score -= 10.0 * (1.0 - (open_bins_count as f64 / 15.0).min(1.0));
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
        if next_item_size > item_size {
            score -= 6.0;
        }
    } else {
        // Placing into an open bin is slightly favored when it leaves room for the lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize leaving a gap just below the next item (near-miss dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover space.
        score += 15.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect fit bonus relative to mean residual: tighter than average is good.
    let mean_gap = post_residual as f64 - mean_residual;
    score -= 8.0 * mean_gap / bin_capacity as f64;

    // Last-chance bin: strongly prefer filling the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and fit is acceptable.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // If next item is large and would need a fresh bin anyway, soften the penalty.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space: residuals that are too small for typical items are wasted.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else { 0.0 };
        score += dead * (1.0 - post_residual as f64 / 10.0);
    } else {
        // Perfect fit reward
        score -= 25.0;
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits in post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // next item won't chain here; penalize leaving awkward space
            if post_residual > 0 && post_residual < next_item_size {
                score += 0.3 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Tightness: prefer bins that become very full relative to capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Time horizon: early in the stream, be more conservative (favor new bins for large items);
    // later, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // Global state: many open bins -> prefer filling existing ones; few open bins -> new bin ok.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier bin;
    // consolidating into low-residual bins keeps others available for large items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New bin candidate: give it a moderate default so it loses to good fits but wins over bad fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 - 20.0 * progress + (item_size as f64) * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // next item pairs well with this one in a fresh bin
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: reward tight fits (low post residual), with non-linear polynomial coupling
    let mut score = pr as f64;
    score += 40.0 * x * (1.0 - x) * (1.0 - x); // penalize mid-range waste more than extremes
    score -= 25.0 * (1.0 - x).powi(3) * (1.0 + 0.5 * progress); // extra reward for very tight fits later in stream

    // Lookahead coupling: smooth interaction between post residual and next item fit
    if nx > 0.0 {
        let gap = (pr - nx).abs();
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 18.0 * fit_quality.powi(2) * (1.0 - 0.3 * progress);
        // penalize post residual that cannot fit next item
        if pr < nx {
            score += 12.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: only fitting bin -> encourage using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Slight preference for bins below mean residual (spread waste evenly) with smooth coupling
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // New-bin candidate: make empty bins moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score = cap * (1.0 - it / cap).powi(2) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small item sizes (10, 20, 25, 50)
    // are reusable; odd remainders are dead space.
    let harmonic_bonus: f64 = {
        let pr = post_residual;
        let mut h = 0.0;
        if pr == 0 {
            h += 12.0; // perfect fit is best
        } else if pr % 50 == 0 {
            h += 8.0;
        } else if pr % 25 == 0 {
            h += 6.0;
        } else if pr % 20 == 0 {
            h += 5.0;
        } else if pr % 10 == 0 {
            h += 3.0;
        } else if pr < 10 {
            h += 4.0; // tiny dead space, nearly negligible
        } else {
            // penalize non-harmonic leftovers by their remainder mod 10
            h -= (pr % 10) as f64 * 0.4;
        }
        h
    };
    score -= harmonic_bonus;

    // Integer-division threshold: residual bucket by quarter-capacity
    let quarter = bin_capacity / 4;
    let bucket = post_residual / quarter;
    score -= bucket as f64 * 1.5; // prefer bins leaving larger structured space? no:
    // actually prefer tight fits, so undo partially: keep small post_residual favored
    score += bucket as f64 * 1.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 7.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score -= 3.0; // dead space anyway, fine
        } else if next_item_size > post_residual {
            score += 4.0; // next item won't fit here; bin will die
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // opening a new bin is penalized unless mean residual is small (bins nearly full)
        score += 25.0 + 20.0 * fragmentation - 10.0 * progress;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 12.0; // lookahead suggests fresh capacity is needed
        }
    }

    // Mild preference to fill emptier bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0; // would leave near-zero after next item too
        }
    } else if next_item_size > 0 {
        // Post-residual can't hold next item: mild penalty if gap is small.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open
    // bins, opening a new bin is relatively cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure so it loses against
        // good fits in existing bins, but wins when pressure is low.
        score += 20.0 + pressure * 2.0;
    } else {
        // Slight reward for filling existing bins densely.
        score -= pressure * 0.3;
    }

    // Prefer bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward near-exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item fits into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 120.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use the leftover space.
        // Penalize proportionally to wasted capacity, scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (post_residual as f64) * (0.5 + 0.5 * progress) * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare residual against mean residual: prefer bins with below-average
    // residual (tighter bins get filled first), mildly.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate (bin_residual == bin_capacity): penalize opening a
    // new bin unless the item is large relative to capacity or no good fit
    // exists. The base post_residual already penalizes it; add a bit more
    // unless the item is big (large items justify fresh bins).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.5 {
            score += 60.0 * (0.5 - item_frac) * 2.0;
        } else {
            score -= 20.0 * (item_frac - 0.5) * 2.0;
        }
    }

    // Slight preference for filling bins earlier in the stream (keeps many
    // partially-filled bins available for later awkward items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 60.0;

    // Penalize large post_residual that cannot fit the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64));
        } else {
            // Dead space penalty: wasted residual relative to next item.
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // Extra bonus if post-residual leaves a plausibly reusable gap.
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize slightly so decent existing fits win.
        score += 35.0;
        // But early in the stream with few open bins, opening fresh is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If the current item is large, a fresh bin gives max flexibility.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is below average (consolidating small gaps),
    // and mildly prefer using bins when many are open (avoid bin sprawl).
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    } else {
        score += (-residual_gap) * 0.15;
    }
    score += open_bins_count as f64 * 0.5;

    // Time-horizon modulation: as stream progresses, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically, amplified late in stream
    score += 2.5 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 6.0 * (-norm_pr * 8.0).exp() * (1.0 + progress);

    // Penalize leaving residual that fails to fit next item (smooth term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 3.0 * gap * gap * cap;
        // Reward when post_residual still accommodates next item
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 1.5 * fits_next * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += 0.05 * (open_bins_count as f64) * norm_pr * norm_pr * cap;

    // Deviation from mean residual: prefer bins whose residual is typical
    let dev = (pr - mean_residual) / cap;
    score += 1.2 * dev * dev * cap;

    // New-bin candidate: penalize opening a new bin unless it is early or item is huge
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score = cap * (1.0 + openness) - 2.0 * item_size as f64 + 3.0 * progress * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how it decomposes in capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let denom_class = (post_residual % 25) as f64;

    // Reward residuals that fall into "usable" harmonic classes (multiples of 25, 20, 10).
    if post_residual % 25 == 0 {
        score -= 6.0;
    } else if post_residual % 20 == 0 {
        score -= 4.0;
    } else if post_residual % 10 == 0 {
        score -= 2.0;
    } else {
        // Penalize awkward dead space, worse for tiny leftovers.
        if post_residual < 10 {
            score += 25.0;
        } else {
            score += denom_class * 0.15;
        }
    }

    // Very small post_residual is great if it's near zero (tight fit).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: does the leftover harmonic class fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward, especially if it lands on a good class.
            let next_post = post_residual - next_item_size;
            if next_post % 25 == 0 || next_post == 0 {
                score -= 8.0;
            } else if next_post % 10 == 0 {
                score -= 4.0;
            } else if next_post < 10 {
                score += 5.0;
            }
            score -= 3.0;
        } else {
            // Leftover too small for next item: penalize proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits more aggressively.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin when open bins are roomy.
        score += 20.0 + 15.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Stream progression: late in the stream, avoid leaving fragmented space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 % 7.0) * 0.4;

    // Mean residual coupling: when open bins are already fragmented, tighten selection.
    score += (mean_residual - frac * bin_capacity as f64).abs() * 0.05;

    // Integer-division threshold on post_residual.
    let div_class = post_residual / 15;
    score += match div_class {
        0 => 8.0,   // 0..14: nearly dead space unless it was a perfect fit
        1 => 0.0,
        2 => -1.0,
        3 => -2.0,
        4 => -3.0,
        5 => -3.5,
        _ => -4.0,  // large leftover: roomy bin, fine to use
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a typical item (min size 1, but practically small slivers) are waste.
    // Penalize unusable slivers heavily; small-but-usable gaps mildly.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: gap below minimum item size -> pure waste.
            score += 60.0 + 8.0 * (10 - post_residual) as f64;
        } else {
            // Usable gap: mild preference for tighter fits.
            score += 0.05 * post_residual as f64;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chaining perfect fits).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here: keep this bin attractive.
        score -= 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover: leftover likely becomes dead space.
        score += 0.4 * post_residual as f64;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is truly bad.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 25.0; // tolerate small dead space to avoid opening a bin
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, opening a new one is cheaper.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when current item is large and fits are poor elsewhere;
    // otherwise bias against it so existing bins are used.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so new bins are used only when justified.
        score += 30.0;
        // Large items benefit from a fresh bin (avoid splitting tight bins).
        if item_size >= 50 {
            score -= 0.2 * item_size as f64;
        }
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
        // If many bins are already open, discourage yet another.
        score += 0.4 * open_bins_count as f64;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight tie-break toward bins tighter than average (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = post - nxt;
        if diff == 0.0 {
            // Perfect 2-chain: heavily reward
            score -= 60.0;
        } else if diff >= 0.0 {
            // Next item fits: reward proportionally to tightness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            score += 0.15 * diff;
        } else {
            // Next item won't fit: penalize dead space relative to next item
            score += 0.35 * (-diff);
        }
    } else {
        // Last item: prefer tightest fill
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize unless current open bins have poor residuals
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.5 * mean_residual;
        score += base;
        // If next item is large and would leave this bin's post residual unusable, new bin looks better
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) < 0 && post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Prefer bins tighter than the mean residual (good fits)
        score += 0.25 * (bin_residual as f64 - mean_residual);
        // Strongly reward near-perfect fits
        if post_residual < 10 {
            score -= 35.0;
        }
    }

    // Late in the stream: consolidate, favor filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; prefer tight fills
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Reward filling a bin to near-full.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 30.0;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward but penalize leaving awkward slivers
            let leftover = post_residual - next_item_size;
            score -= 25.0 - (leftover as f64) * 0.5;
        } else {
            // next item can't follow here; slight penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer bins with residual already below mean (consolidate large holes).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Penalize opening new bins early in the stream; allow more freely later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that shrinks as stream progresses
        // and grows with how many bins are already open.
        score += 55.0 - progress * 20.0 + (open_bins_count as f64) * 1.5;
        // Opening a fresh bin is good if item is large (hard to place later)
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference for using open bins when many are open (avoid sprawl).
    score += (open_bins_count as f64) * 0.05;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is wasted space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += norm_pr * norm_pr * (40.0 + 60.0 * prog2) - norm_pr * (10.0 + 30.0 * prog3);

    // Reward tight fits (small post_residual), stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + 1.5 * progress);
        } else {
            score -= 2.0 * progress;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty when bin diverges from mean residual (balance open bins)
    score += ((pr - mean_residual) / cap).abs() * 8.0 * (1.0 - progress);

    // Slight preference for keeping bin count low early
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes is reusable
    let pr = post_residual;
    if pr > 0 {
        for &h in &[10u32, 20, 25, 50] {
            if pr % h == 0 {
                score -= 30.0 + 10.0 * (pr / h) as f64;
                break;
            }
        }
    }

    // Dead space penalty: small unusable remainders
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Tight fit reward (fraction of capacity filled)
    let fill = item_size as f64 / cap;
    score -= 50.0 * fill * fill;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if next item fits in post_residual, bonus
    if next_item_size > 0 && next_item_size <= pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > pr {
        score += 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual - score.abs()).abs(); // dummy coupling guard
        let _ = frag;
        score += 120.0
            + 5.0 * open_bins_count as f64
            - 100.0 * (mean_residual / cap).min(1.0);
        // early stream: opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to mean (balance)
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny positive gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward when leftover can still fit the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // likely stranded space
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist or the fit is bad.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += new_bin * (10.0 + pressure);

    // Mild preference for filling bins tighter than the average.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Late in stream: prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // After placing the next item too, leftover should be small
        let second_leftover = post_residual - next_item_size;
        if second_leftover < 10 {
            score -= 30.0;
        } else {
            score -= 15.0 / (1.0 + second_leftover as f64 / 20.0);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize proportionally to wasted gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.4;
    }

    // Penalize unusable dead space (post residual too small for anything)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward leaving post_residual close to mean residual (keeps bins uniform)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, prefer tighter packing (smaller post residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact residual is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Penalize dead space scaled by how unusable the leftover is for typical items.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Lookahead coupling: if the next item fits perfectly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: slight penalty if we leave large unusable gap.
            let gap = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 8.0 * gap / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64).ln() + 1.0;
    score += 5.0 * crowd * (1.0 - progress);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 70.0 * desperation - 30.0 * big_item;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping
    let mut score = 2.0 * pr + 40.0 * norm_pr * norm_pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more
    let prog_coupling = 60.0 * norm_pr * progress * (1.0 - progress + 0.25);
    score += prog_coupling;

    // Reward tight fits relative to mean residual state (smooth interaction)
    let tightness = (mean_residual - pr) / cap;
    score -= 30.0 * tightness * (1.0 + progress);

    // Penalize dead space that next item could use: smooth quadratic interaction
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        let usable = (1.0 - gap.abs()).max(0.0);
        score -= 25.0 * usable * (1.0 - (gap * gap * 4.0).min(1.0));
    } else {
        // last item: strongly prefer filling bins as much as possible
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus (avoid opening a new bin when only one fits)
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open (smooth in open_bins_count)
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 10.0));
    score -= 15.0 * open_norm * (1.0 - norm_pr);

    // New-bin candidate: smooth penalty unless residual is very large relative to capacity
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * (1.0 - norm_pr) * progress;
        // opening a new bin is attractive if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward post_residuals that are multiples of small harmonic steps (10, 20, 25, 50)
    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20, 25, 50] {
        if pr % m == 0 && pr > 0 {
            harmonic_bonus += (m as f64) * 0.6;
        }
    }
    score -= harmonic_bonus;

    // Penalize "dead space": tiny unusable leftovers (1..=9) unless zero (perfect fit)
    if pr == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    } else if pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // reward proportional closeness, harmonic class of (pr - next)
            score -= 25.0 / (1.0 + slack as f64);
            if slack % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here; slight penalty scaled by overflow
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Fraction-of-capacity class of residual before placement
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    // Favor placing into fuller bins (best-fit style) via residual already in score,
    // add extra pressure as bin approaches capacity classes
    if fill_frac > 0.5 {
        score -= 5.0 * fill_frac;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost so we prefer
    // reusing open bins unless their post_residual is bad (dead space / huge waste)
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if current open bins would leave large waste, opening fresh is fine
        if prf > 0.5 * cap {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: near the end, prefer packing tight into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Mean residual context: if this bin is much tighter than average, prefer it
    score -= (mean_residual - prf).max(0.0) * 0.1;

    // Modulo threshold on post_residual vs capacity: leftovers in (50, 60) or (75, 90)
    // are awkward zones; penalize slightly
    if (pr > 50 && pr < 60) || (pr > 75 && pr < 90) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Dead space relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by the resulting dead space, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 8.0;
    }

    // New-bin candidate: neutral anchor with mild open-bin pressure,
    // so it wins only when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = 12.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strongly favor this bin.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 + 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to how wasted the space is.
            score += 10.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space penalty: tiny leftovers are nearly unusable (items >= 1, but waste).
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., item barely fits anywhere). Penalize mildly so open bins are preferred,
    // but relax the penalty late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += fit_pressure + 20.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_residual.saturating_sub(item_size)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual as fraction of capacity
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += post_frac * post_frac * 30.0;

    // Strong reward for exact fill
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.25;

    // Penalize opening new bins when many bins are open and fragmented
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But late in the stream, a fresh bin may be fine
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= t * 10.0;
    }

    // Small penalty for very small item into a huge residual (wasteful pairing)
    if item_size < bin_capacity / 4 && bin_residual > bin_capacity / 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping.
    let mut score = pr + 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals become more acceptable (pack tighter),
    // penalize mid-range residuals more strongly as progress advances.
    let cubic = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 40.0 * cubic * (1.0 - progress);

    // Penalize residuals that cannot fit the lookahead item (smooth gate).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        let gap = ((next_item_size as f64) - pr).abs();
        let gate = 1.0 / (1.0 + (gap / 20.0) * (gap / 20.0));
        if fits_next {
            score -= 15.0 * gate;
        } else {
            score += 15.0 * (1.0 - gate);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins; smooth in open_bins_count.
    let obn = open_bins_count as f64;
    score += 2.0 * (obn / (obn + 10.0)) * (1.0 - norm_pr);

    // Coupling with mean residual: prefer bins deviating from the mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make it less attractive unless the item fits very well
    // in no open bin (post_residual near capacity means bad fit in empty bin too,
    // but an empty bin has full residual so this mainly punishes opening new bins).
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (1.0 - progress) * (norm_pr * norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill is always excellent
    } else if pr % 10 == 0 {
        -8.0 // divisible by the common granularity
    } else if pr % 5 == 0 {
        -3.0
    } else if pr >= 10 {
        0.0
    } else {
        25.0 + (10 - pr) as f64 * 3.0 // dead space below the minimum item size
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual: leftover that can host
    // next_item_size is valuable; leftover just below it is waste.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 6.0 + (pr / next_item_size.max(1)) as f64 * 2.0;
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.5;
        }
        // If next item cannot fit ANY other bin, prefer keeping room for it here.
        if pr >= next_item_size && next_item_size <= pr {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tight fit reward: small post residual relative to capacity.
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Penalize creating a residual that sits in a "gap" class: too small for
    // typical mid-size items (11..=19) but not near-zero.
    if (11..=19).contains(&pr) {
        score += 8.0;
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (reduces bin count pressure), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64 / bin_capacity as f64) * (4.0 + 6.0 * progress);

    // Mild penalty when this bin's residual is far from the mean (balance).
    score += ((pr as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    // New-bin candidate (empty bin) should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing lookahead makes a fresh bin attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space relative to lookahead
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // poor fits (high mean residual dispersion or many open bins pressure).
    if bin_residual == bin_capacity {
        score += 20.0;
        score += open_bins_count as f64 * 1.5;
        // If mean residual is large, open bins still have room: discourage new bin.
        score += mean_residual * 0.3;
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Open-bins pressure: mild penalty scaled by number of open bins to
    // encourage consolidation into existing bins.
    if bin_residual < bin_capacity {
        score -= 2.0;
        score += open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // Next item does NOT fit: penalize leaving dead space the next item wastes.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead.min(next_item_size as f64);
        }
    }

    // Compare residual to the mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless open bins are hopelessly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Only attractive when existing residuals are small (fragmented) and next item is large.
        score += 25.0;
        if fragmentation < 0.25 && next_item_size > post_residual + 30 {
            score -= 20.0;
        }
    }

    // Late in the stream: prefer using existing bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Penalize creating dead space that nothing can use (smallest item = 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large unusable gaps.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open with high mean residual,
    // discourage opening new bins; encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are many open bins
        // or late in the stream with slack available.
        let mut new_bin_penalty = 15.0 + 8.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        // Early in the stream, new bins are cheaper.
        new_bin_penalty *= 0.5 + 0.5 * progress;
        score += new_bin_penalty;
    } else {
        // Existing bin: reward filling bins that are already mostly used.
        let used_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * used_ratio;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score -= 3.0 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = post / cap;

    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    score += 18.0 * x * x * (0.5 + progress);
    score -= 12.0 * x * (1.0 - x) * (1.0 - progress);

    // Penalize near-full bins only early in the stream (wasted tight fits)
    score -= 8.0 * x.powi(4) * (1.0 - progress);

    // Dead-space penalty: residuals too small for typical future items
    score += 10.0 * (x * (1.0 - x)).sin().abs() * progress;

    // Last-chance bin reward
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Coupling with mean residual across open bins
    score += 3.0 * (post - mean_residual) / cap * (0.5 + progress);

    // Mild penalty for proliferating open bins
    score += (open_bins_count as f64).ln() * 1.5;

    // New-bin candidate: prefer it only when item is small relative to open space
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
        score += 4.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that commonly recombine with
    // typical item sizes (multiples of 5/10) are more reusable than odd debris.
    let r = post_residual % 10;
    let debris = match r {
        0 => 0.0,
        5 => 2.0,
        _ => 6.0,
    };
    score += debris;

    // Small post_residual = tight, efficient packing.
    if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // Dead space: post_residual too small for the smallest plausible item (>=1)
    // is fine, but residual in (0, next_item_size) wastes space for lookahead.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
        // Reward leaving room exactly for the next item (chain fit).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Reward leaving room for next item plus a harmonic chunk (10/20).
        if post_residual >= next_item_size {
            let room = post_residual - next_item_size;
            if room % 10 == 0 && room > 0 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave
    // large unusable debris or the bin is genuinely full-ish.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 25.0; // keep pair-ability in existing bins instead
        }
        if bin_residual >= item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Prefer fullest bins (small residual) mildly; tie-break by open-bin count
    // to encourage consolidation when many bins are open.
    score += (bin_residual as f64) * 0.05;
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Penalize diverging from mean residual (keeps bins balanced).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits, especially exact fills.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness;
    }

    // Penalize leaving gaps too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 4.0;
    }

    // Open-bins pressure: prefer reusing existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (6.0 + 6.0 * progress);

    // New-bin candidate: make empty bins less attractive unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual as f64 > bin_capacity as f64 * 0.45 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Slight preference toward bins with lower mean residual (already committed space).
    score -= (mean_residual / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: next item seals this bin perfectly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize dead space relative to capacity
            let dead = next_item_size - post_residual;
            score += 30.0 * (dead as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable.
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a fresh empty bin on small items unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
    }

    // Late-stream tightness: as stream progresses, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: tight fit reward — low post_residual is good.
    let mut score = post_residual as f64;

    // Strong penalty for large dead space: quadratic in post_residual.
    score += 0.02 * (post_residual as f64).powi(2);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.3 * (next_item_size as f64);
        } else {
            // Dead space relative to next item: penalize wasted capacity.
            let waste = post_residual as f64;
            score += 0.25 * waste * (1.0 - (step_index as f64 / total_items.max(1) as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large (would leave little residual anyway) or existing residuals
    // are all poor fits. Penalize new bins mildly by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Large items pack well in fresh bins; small items should use leftovers.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let new_bin_score = (bin_capacity - item_size) as f64;

        // If mean residual across open bins is small, opening a new bin is fine.
        let residual_pressure = (mean_residual / bin_capacity as f64).max(0.0);

        // Penalize new bins when open bins have plenty of room and item is small.
        score = new_bin_score
            + 40.0 * (1.0 - item_frac)
            + 30.0 * residual_pressure
            - 25.0 * progress; // later in stream, opening fresh bins is safer
    }

    // Mild bonus for consolidating into bins with small residual (shrink-to-fit).
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Slight preference for bins with fewer alternatives when many bins open.
    if open_bins_count > 3 && fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear tightening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Quadratic dead-space penalty: tiny residuals are wasted space
    score += 6.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);

    // Reward tight fits (post_residual near zero)
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Mild penalty when many bins compete (encourage spreading load wisely)
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // penalize placements that leave a residual unusable by next item
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual coupling: bins far from mean residual get slight normalization
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Open-bin pressure: many open bins -> discourage opening more, favor filling
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fills are gold.
    let post = post_residual;
    if post == 0 {
        score -= 1000.0; // perfect fill
    } else if post <= 5 {
        score -= 60.0; // near-perfect
    } else if post % 10 == 0 {
        score -= 25.0; // class-10 residual: highly reusable
    } else if post % 5 == 0 {
        score -= 12.0;
    } else {
        // odd/dead-ish residuals penalized proportionally to distance from a multiple of 10
        let r = (post % 10) as f64;
        score += r * r * 0.4;
    }

    // Dead-space penalty: small unusable residual
    if post > 0 && post < 10 {
        score += 30.0;
    }

    // Reward leaving room for the lookahead item (harmonic pairing)
    if next_item_size > 0 {
        if post >= next_item_size {
            let gap = post - next_item_size;
            if gap == 0 {
                score -= 500.0; // chain perfect fill
            } else {
                score -= (gap.min(20)) as f64 * 1.5;
            }
        } else {
            // lookahead won't fit here: slight penalty scaled by waste
            score += (next_item_size - post).min(30) as f64 * 0.8;
        }
    } else {
        // last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a new bin
        score = cap * 0.85;
        // if no existing bin fits, new bin is mandatory-ish
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // early stream: fresh bins are fine (reserve capacity for big items)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 20.0 * (0.3 - progress) * 10.0;
        }
        // many open bins with slack: discourage more bins
        if mean_residual > cap * 0.4 {
            score += 25.0;
        }
    } else {
        // prefer bins with residual close to item (tight fit reward)
        let tight = (bin_residual - item_size) as f64;
        score += tight * 0.1;
        // prefer bins whose residual class matches item class (mod 10 harmony)
        if bin_residual % 10 == item_size % 10 {
            score -= 8.0;
        }
    }

    // congestion shaping: many open bins -> tighten selection
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold another item (likely range 1..=10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many
    // bins are open and the item fits reasonably well somewhere.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 20.0 + open_pressure * 3.0 + fit_pressure * 2.0;

        // If the next item is small, a fresh bin may still be valuable
        // to preserve flexibility: soften the penalty slightly.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    } else {
        // If placing here leaves a gap that exactly fits the next item,
        // reward the placement (lookahead synergy).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
        // Penalize leaving a gap slightly larger than the next item but
        // wasteful relative to it.
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += (post_residual - next_item_size) as f64 * 10.0;
        }
    }

    // Mild pressure from many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual below the mean (consolidate emptier space usage).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Slight early-stream bias toward tight packing (build good bins early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus for perfect or near-perfect match with the next item.
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).powi(6);

        // Penalize post_residual that is small but cannot fit the next item (dead space).
        if post_residual < next_item_size {
            score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure tightness preference.
        score -= 10.0;
    }

    // Relative residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when it would leave a large unusable chunk,
    // but allow it when open bins have poor fits (large post_residual there).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty unless open bins are wasteful.
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 0.2 * mean_residual;
        }
        // Late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Small reward for very tight fits (post_residual near zero but nonzero waste is bad).
    if post_residual > 0 && post_residual <= 5 {
        score += 8.0; // tiny dead space is nearly unusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of the bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    // Reward high fill ratio (less dead space) — subtract proportional to fill
    score -= 60.0 * fill * fill;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space below the minimum plausible item size is wasted)
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        if post_residual < 10 {
            score += 80.0 * (1.0 - dead); // nearly-full bin: great, reward
        } else {
            score += 25.0 * dead * dead; // penalize unusable leftover
        }
    } else {
        score -= 40.0; // perfect fit bonus
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 30.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if we leave large awkward gaps
            score += 15.0 * ((post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 55.0;
    } else if fitting_bins_count > 1 {
        // competition exists: prefer bins where this item fits snugly
        score += 10.0 * (fitting_bins_count as f64).ln().max(0.0) * (1.0 - fill);
    }

    // Global state coupling: prefer filling bins when mean residual is high (fragmentation risk)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early on, be more willing to open bins / spread load;
    // late in the stream, be aggressive about closing bins tightly.
    let late_bias = 40.0 * progress;
    score -= late_bias * fill;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Only attractive when the item is large (poor fit elsewhere) or no alternatives exist.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0 + 50.0 * (1.0 - fill) + 20.0 * (1.0 - progress);
        score += new_bin_penalty;
        // If item is big, opening a fresh bin is more reasonable
        score -= 30.0 * fill * fill;
    }

    // Slight preference for bins with less residual before placement (tighter bins first)
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    // Mild open-bins pressure: many open bins -> consolidate
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 30.0 * coupling;
    // reward tight fits (small post residual) more as stream progresses
    score -= 20.0 * (1.0 - prn) * progress;
    // penalize near-empty fills that waste capacity quadratically
    score += 5.0 * prn * prn;
    // lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }
    // last chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    }
    // discourage opening new bins when many open bins have room
    let mean_r = mean_residual / cap;
    score += 4.0 * mean_r * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    // new-bin candidate: keep it unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions.
    let pr = post_residual;
    let class = pr % 10;
    let small = (pr <= 10) as f64;
    let tiny = (pr <= 5) as f64;

    // Reward perfect/near-perfect fits (dead space elimination).
    score -= 30.0 * tiny;
    score -= 12.0 * small;

    // Penalize residuals in "unfillable" harmonic classes: gaps that few item
    // sizes (1..100) can exploit. A residual r is fillable if some future item
    // equals r; small odd/prime-ish gaps are dead space.
    let dead = ((pr > 5) && (pr < 15) && (class % 2 == 1)) as f64
        + ((pr > 20) && (pr < 30) && (pr % 7 == 3)) as f64;
    score += 8.0 * dead;

    // Capacity-fraction coupling: reward filling toward clean fractions of C.
    let fill = (bin_residual as f64) / cap; // fraction used before placement
    let frac_align = ((fill * 4.0).round() - fill * 4.0).abs(); // closeness to quarter marks
    score += 6.0 * frac_align;

    // Integer-division threshold on next_item_size: if the lookahead item can
    // exactly consume the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && (pr - next_item_size) <= 5 {
            score -= 15.0;
        } else if next_item_size > pr {
            // Lookahead cannot fit here; slight penalty if this bin is last chance anyway.
            score += 2.0;
        }
    }

    // Last-chance bonus: only one bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin would leave a large,
    // awkward gap and the stream is early (room to consolidate later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; penalize opening new bins when open
        // bins already exist and mean residual is large.
        score += 25.0 + 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        if progress < 0.2 && item_size > 60 {
            score -= 15.0; // big item early: fresh bin can be efficient
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: favor reusing existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0; // base penalty for opening a new bin
        if post_residual as f64 > 0.35 * bin_capacity as f64 {
            score += 20.0; // large leftover after placing a big item
        }
    }

    // Lookahead: if next item could fill this bin's post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to upcoming item
    }

    // Late in the stream, tighten up: prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild super-linear penalty
    // on wasted space to discourage dead zones.
    let wasted = post_residual as f64;
    score += 0.35 * (wasted * wasted) / bin_capacity as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();

        // Perfect match: next item exactly fills this bin -> huge reward.
        if gap < 0.5 {
            score -= 60.0;
        } else if gap <= 10.0 {
            // Near match: reward proportionally to closeness.
            score -= 40.0 * (1.0 - gap / 10.0);
        } else {
            // Mismatch: penalize leaving a residual that is neither usable nor tiny.
            // Dead space = post_residual that can't hold the next item but is large.
            if post < nxt && post > 0.0 {
                score += 0.5 * (post / nxt) * 20.0;
            }
        }

        // If the next item could fit here after placement, small extra reward
        // (keeps chains of placements in the same bin).
        if nxt <= post {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize waste (post_residual already does this).
        score -= 10.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual is below the mean (i.e., we are tightening a
    // relatively full bin) rather than spreading waste across empty-ish bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev;

    // --- Last-chance bonus ---
    // If this is the only bin that can fit the item, strongly favor using it
    // over opening a new bin (avoid wasting an existing viable bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    // Opening a new bin is only attractive when no open bin offers a decent fit:
    // make the empty bin expensive unless the item is large relative to capacity
    // or the stream is early (bins are cheap early on).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins more as the stream progresses and for small items.
        score += 8.0 + 30.0 * progress + 20.0 * (1.0 - item_frac);
        // But if next item is huge and nothing fits well, a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild penalty for accumulating too many open bins (encourages consolidation).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> prefer tight packing into existing bins;
    // late stream -> less penalty for residual (fewer future items to fill gaps).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight_fit * tight_fit;

    // Penalize dead space relative to the mean residual of open bins:
    // a post_residual far below what other bins hold wastes capacity.
    let dead = (post_residual as f64 - mean_residual).max(0.0);
    score += 0.35 * dead;

    // Lookahead: if the next item could fill this bin's post_residual exactly,
    // strongly reward; if post_residual < next_item_size, the gap is dead for lookahead.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 25.0;
        } else if (post_residual as u64) < next_item_size as u64 && post_residual > 0 {
            score += 8.0 * (1.0 - progress) * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item leaves a large awkward gap
        // in existing bins, or when few bins are open (early stream).
        let gap_penalty = if post_residual > 0 && post_residual < 20 { -6.0 } else { 0.0 };
        let base = 0.55 * bin_capacity as f64;
        score += base + gap_penalty - 20.0 * (1.0 - progress) * (1.0 - open_bins_count.min(12) as f64 / 12.0);
        // Discourage opening new bins when the fit in the new bin is itself poor
        // (item much smaller than capacity).
        score += 0.25 * post_residual as f64 * (1.0 - progress);
    } else {
        // Mild reward for consolidating into bins that are already partially full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 6.0 * fullness * (0.5 + 0.5 * progress);
    }

    // Global balance: prefer bins whose residual is near the mean (keeps spread even),
    // slightly stronger early in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev * (1.0 - 0.5 * progress);

    // Small dynamic noise-free tie-breaker based on stream position.
    score += 0.01 * (progress * 100.0).sin() * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with smooth non-linear coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear polynomial coupling: post_residual^2 term weighted by progress.
    score += 0.35 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward last-chance bins (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize leaving residual close to next item's size mismatch (dead space),
    // smooth via distance to next_item_size.
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        score += 0.15 * d * (1.0 - progress * 0.5);
    }

    // Smooth preference toward bins with residual below mean (compact bins),
    // scaled non-linearly with number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0)) * (0.3 + progress);

    // Discourage opening new bins early when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        let fit_frac = item_size as f64 / cap;
        score += 12.0 * (1.0 - fit_frac) * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (capacity fractions) ---
    // Leftovers that form "harmonic" sizes (1/2, 1/3, 1/4, 1/5 of capacity)
    // are the most reusable by future items. Penalize non-harmonic dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut harmony = 0.0;
    for k in 2..=6 {
        let target = cap / k as f64;
        let diff = (post - target).abs();
        if diff <= 2.0 {
            harmony += 12.0 / k as f64; // tight harmonic fit => big reward
        } else if diff <= 5.0 {
            harmony += 4.0 / k as f64;
        }
    }
    score -= harmony;

    // --- Integer-division dead-space classes ---
    // Residuals in (0,10) are almost unusable (min item is small but stream
    // is unknown; assume small items exist but are rare): heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Modulo arithmetic on post_residual: classify by residue mod 10 ---
    // Residues near 0 (multiples of 10) align with common item-size grids.
    let r = (post_residual % 10) as f64;
    let r_alt = (10 - r) as f64;
    score -= 3.0 * (10.0 - r.min(r_alt)) / 10.0; // reward grid-aligned leftovers

    // --- Next-item lookahead coupling ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here too: strong reward, scaled by snugness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit; penalize more the bigger the overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // Harmonic pairing: post_residual == next_item_size exactly => chain fit
        if next_item_size == post_residual {
            score -= 20.0;
        }
        // Modulo harmony between next item and leftover class
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this bin fits; avoid opening a new bin unless it's terrible.
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: base cost plus waste penalty; attractive only if the
        // item is large or existing bins are fragmented.
        score = item_size as f64 * 0.5 + 30.0;
        if item_size >= 60 {
            score -= 15.0; // big items deserve fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.3 * mean_residual;
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 && item_size <= 40 {
            score += 25.0; // small items should go into open bins
        }
    }

    // --- Fragmentation penalty relative to mean residual ---
    // Choosing a bin whose residual deviates strongly from the mean
    // concentrates waste; mildly prefer near-mean bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- Progress-adaptive tightness ---
    // Early: keep bins flexible (prefer moderate leftovers).
    // Late: maximize packing density (prefer minimal leftover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post * 0.1;
    score -= (1.0 - progress) * 5.0 * (1.0 - (post / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits proportionally.
        score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Penalize leaving gaps that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // gap remains useful for next item
        } else if post_residual > 0 {
            score += 12.0; // gap likely dead for the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins over opening new ones; with few bins, new bins are cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive when the item fits badly
    // everywhere else (large item on small residuals is bad).
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count >= 1 && item_size <= mean_residual as u32 {
            score += 25.0; // an open bin can host it decently; discourage new bin
        }
    }

    // Mild penalty if this bin's residual is far below the mean (it is already
    // tight; prefer spreading into looser bins when residuals are similar).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tightness = (post_residual - next_item_size) as f64;
            // Perfect chaining: post residual matches next item -> strong reward
            score -= 25.0 * (1.0 - next_tightness / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: keep residuals balanced
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current open bins are all poor fits
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && fitting_bins_count > 0 {
            fitting_bins_count == 1 && (bin_residual - item_size) < next_item_size && item_size < 50
        } else {
            false
        };
        if poor_fits {
            score -= 10.0; // allow opening a fresh bin for a big item with bad residual chain
        } else {
            score += 60.0; // default: strongly prefer existing bins
        }
    }

    // Slight preference for filling bins early in the stream (keeps open bin count low)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (items >= 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow here: penalize proportional to wasted opportunity.
        score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio * (open_bins_count as f64).ln();

    // Global state: penalize bins whose residual deviates above mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in stream, allow opening new bins for large items;
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or for large items, costly late.
        score += 6.0 + 40.0 * progress - 10.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large items together in a fresh bin
        }
    } else {
        score -= 4.0 * progress;
    }

    // Mild penalty for very large items going into nearly-full bins (risky split).
    if item_size as f64 > 0.6 * bin_capacity as f64 && fill_ratio > 0.3 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap; // 0..1
    let poly = norm_post * norm_post * (1.0 - progress) - norm_post * progress * (1.0 - norm_post);
    score += 12.0 * poly;

    // Penalize large residual waste more than linearly (quadratic dead-space term)
    score += 0.35 * norm_post * norm_post * cap;

    // Reward tight fits (small post_residual) with a saturating bonus
    score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_post);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - (next_item_size as f64) / post.max(1.0));
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving a residual that is close-but-unusable
        let gap = (next_item_size as f64) - post;
        score += 0.5 * gap * (1.0 - progress);
    }

    // Slight preference for bins with residual below mean (consolidate waste)
    score += 0.05 * (mean_residual - post);

    // New-bin candidate: mild penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 / 20 define "dead space" classes.
    let r = post_residual;
    let class = r / 20; // 0..=5 harmonic band
    score += match class {
        0 => -6.0,          // very tight leftover: excellent packing
        1 => -2.0,
        2 => 0.0,
        3 => 2.0,
        4 => 4.0,
        _ => 5.0,           // wide-open leftover: weak fit
    };

    // Exact residue penalty: post_residual that is a small nonzero odd remainder is dead space.
    if r > 0 && r < 10 {
        score += 8.0;
    }
    if r == 0 {
        score -= 10.0; // perfect closure
    }

    // Lookahead compatibility: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // harmonic alignment: next item divides into leftover comfortably
            let slack = (r - next_item_size) as f64;
            score -= 5.0 - slack * 0.05;
            // ideal: leftover after next item is small
            if (r - next_item_size) < 10 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by gap
            score += ((next_item_size - r) as f64) * 0.08;
        }
    } else {
        // last item: just close bins tightly
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is large
    // relative to capacity or many bins are already open with low mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 * 0.3 + mean_residual * 0.05;
        score += 20.0 - big_item * 25.0 - pressure - progress * 5.0;
        // never open a new bin for a tiny item
        if item_size < 30 {
            score += 15.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Reward bins that can also fit the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Nudge toward bins below mean residual (fill the emptier side later).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 2.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        } else {
            // dead space penalty relative to next item
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: prefer leaving near-mean slack
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 100.0 * (1.0 - progress);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 80.0;
        }
    }

    // Slight preference for tighter bins overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / bin_capacity as f64;

    // If the leftover after placement can exactly host the next item, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 10.0; // chain fit: leaves near-zero dead space for next item
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: penalize dead space relative to next item
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.5;          // base cost of opening a bin
        score -= pressure * 200.0;     // if nothing else fits, new bin is essential
        score += open_bins_count as f64 * 3.0; // mild consolidation pressure
    }

    // Time-horizon modulation: early on, keep bins flexible (favor mid residuals);
    // late in stream, greedily minimize residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.2;

    // Penalize bins far from the mean residual (keeps bin population homogeneous).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual

    // Base: prefer small post residual, smoothly scaled
    let mut score = prn;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate larger leftovers (score flatter); late, penalize hard.
    let w = 0.5 + 1.5 * progress;
    score += w * prn * prn;

    // Smooth interaction: leftover usefulness depends on next item fit
    if next_item_size > 0 {
        let nn = next_item_size as f64 / cap;
        // reward if next item fits snugly into post residual (smooth kernel)
        let fit = 1.0 - ((prn - nn) / 0.25).powi(2);
        let fit_kernel = fit.max(-1.0);
        score -= 0.6 * fit_kernel * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count <= 1 {
        score -= 2.0;
    } else {
        // mild penalty for spreading across many bins when alternatives exist
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual near mean (balanced packing), smooth term
    let mean_n = mean_residual / cap;
    score += 0.3 * (prn - mean_n).abs();

    // Mild preference to fill existing bins as bin count grows
    score += 0.02 * (open_bins_count as f64).sqrt() * (1.0 - prn);

    // New-bin candidate: penalize opening a new bin unless item is huge
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 0.8 + 1.5 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize leftover classes that are hard to fill (small but nonzero gaps)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // dead space: too small for any item
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 30 {
            score += 6.0;
        } else if post_residual < 50 {
            score -= 4.0; // sweet spot: half-ish bin still usable
        } else {
            score -= 2.0;
        }
    } else {
        score -= 60.0; // perfect closure, strongly reward
    }

    // Modulo arithmetic on post_residual: classify by thirds/quartiles of capacity
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual % third == 0 && post_residual > 0 {
        score -= 3.0; // leftover matches a harmonic class, likely reusable
    }
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward tight co-fit
            let tightness = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * tightness;
        } else {
            // next item won't fit here: penalize proportionally to waste
            score += 0.10 * (next_item_size.saturating_sub(post_residual)) as f64;
        }
        // harmonic threshold on next_item_size classes
        if next_item_size > 2 * third {
            score += 2.0; // large next item: prefer conserving big residuals elsewhere
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // current item is large relative to capacity and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * progress - 0.2 * item_size as f64;
        if item_size > 2 * third {
            score -= 15.0; // big items are fine in fresh bins
        }
    }

    // Mean residual coupling: prefer bins far from the mean (balanced portfolio)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Small penalty for spreading across many open bins late in the stream
    score += 0.01 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual <= 10 { 40.0 } else if post_residual <= 20 { 15.0 } else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tightness reward: fraction of residual consumed by the item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: prefer spreading when many bins are open.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly,
    // penalize residual just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress and mean residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 25.0 * progress;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            // Existing bins are all too fragmented: opening a new bin is good.
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // keep fresh space for larger future items
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), with non-linear pressure
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).sqrt() * 10.0;

    // Aggressive 2-step lookahead: reward when next_item_size fits exactly into post_residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if n <= pr {
            // next item fits: reward closeness to a perfect 2-item fill
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64 * 0.5)).max(0.0);
            if (pr - n).abs() < 0.5 {
                score -= 25.0; // perfect two-item packing
            }
        } else {
            // next item won't fit here: penalize leftover dead space relative to next item
            score += 0.25 * (pr - n).min(pr);
        }
        // mild reward if post_residual is at least next item size (keeps chain alive)
        if n <= pr {
            score -= 3.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 20.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: avoid making this bin an outlier
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += 0.15 * (pr - mr).abs();

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score += 30.0;
        // allow new bin only if item leaves large unusable space elsewhere / stream early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // if next item is huge, a fresh bin with room helps
        if next_item_size > 0 && (next_item_size as f64) > pr.min(bin_residual as f64) {
            score -= 8.0;
        }
    } else {
        // reward using existing bins, more so late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Slight penalty for wasteful near-full-but-unusable residuals (dead space 1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Perfect closure bonus
    if post_residual == 0 {
        score -= 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, especially when it becomes dead space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Dead space penalty: post_residual that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: mild preference to fill tighter bins (post_residual already does this),
        // add slight penalty proportional to how many alternatives exist to encourage spreading.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let lookahead_fit = (post_residual as f64 - next_item_size as f64).abs();
            score -= 15.0 * (1.0 - lookahead_fit / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a large awkward residual.
            score += 5.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 0.0 {
        let relative_tightness = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 8.0 * relative_tightness * (0.5 + progress);
    }

    // Time horizon: early in stream, opening new bins is cheaper; late, consolidate.
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets baseline score; only attractive when
    // no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * (1.0 - progress) - 20.0 * (fitting_bins_count == 0) as i32 as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Early stream: value tight fits (low post_residual); late stream: tolerate slack
    let progress_weight = 1.0 - progress * progress;
    score -= (cap - pr) * 0.15 * progress_weight;

    // Smooth non-linear penalty on dead space: quartic in normalized post_residual
    score += norm_pr * norm_pr * norm_pr * norm_pr * 40.0;

    // Interaction: dead space penalized more when progress is low (long stream ahead)
    score += norm_pr * norm_pr * progress * 30.0;

    // Last-chance bonus (smooth, not piecewise)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer conserving bins when many are open and mean residual is high
    let mr = mean_residual / cap;
    score -= mr * mr * 5.0;

    // Lookahead: reward bins whose post_residual pairs with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= (1.0 - gap / cap) * 10.0;
    }

    // New-bin candidate: keep it neutral-ish, mildly penalized so real bins win on good fits
    if bin_residual == bin_capacity {
        score += 12.0 + norm_pr * 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead space in classes
    // 1..=9 (below 10) is nearly unusable since items >= 10 originally,
    // but with sizes 1..100 small residuals may still fit tiny items.
    let pr = post_residual;
    let cls = pr % 10;

    // Penalize residuals that are small but not zero (wasted slivers)
    if pr > 0 && pr <= 5 {
        score += 12.0;
    } else if pr > 5 && pr < 10 {
        score += 6.0;
    } else if pr == 0 {
        score -= 8.0; // perfect fill
    }

    // Reward residuals that are "harmonic": divisible by common item sizes
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 2.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 2.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size < pr {
        // next item fits but leaves residue: mild reward scaled by fit quality
        let nr = pr - next_item_size;
        if nr <= 5 {
            score -= 6.0;
        } else {
            score -= (10.0 - (nr as f64 / 10.0)).max(0.0);
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this residual: penalize leftover
        score += (pr as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using it rather than opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        // brand-new bin: neutral baseline, slight penalty so existing good
        // fits win, but low enough to win when all fits are poor
        score += 8.0;
        if item_size > bin_capacity / 2 {
            score -= 4.0; // big items are fine in fresh bins
        }
    }

    // Encourage tight fits overall
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 4.0;

    // Mean residual coupling: when mean residual is high, prefer filling
    // already-open bins harder
    score += (mean_residual - post_residual as f64) * 0.03;

    // Stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    // Harmonic threshold: quantize post_residual into bands; prefer bands
    // that leave room for a mid-size item (10..50)
    let band = pr / 10;
    match band {
        0 => { score += 4.0; }        // 0..9: mostly dead
        1 | 2 => { score += 1.0; }    // 10..29: fits small items
        3 | 4 | 5 => { score -= 2.0; } // 30..59: versatile
        _ => { score -= 1.0; }         // 60+: still very usable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "unusable" if it cannot fit even a small item (threshold ~15)
    // or if it is nonzero but below the next item's demand.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 40.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        } else {
            score -= 6.0; // gap still usable -> mild reward
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Reward tight fits: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: penalize placements that keep many bins open
    // with large residuals; encourage consolidation when bins are few.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's post_residual is far below the
    // mean, it is a good consolidation; otherwise penalize divergence.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and open bins are numerous.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (fitting_bins_count.max(1) as f64 + open_bins_count as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * big_item - 10.0 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item almost fills remaining space (small gap <= 5).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 25.0 - 4.0 * gap;
        } else {
            // Penalize leaving space larger than next item (dead space).
            score += gap * 0.35;
        }
    }

    // Reward tight packing: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 12.0 / (1.0 + tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins far from the mean residual (fragmenting the residual pool),
    // unless the bin is nearly full (low residual is always good).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight preference for opening new bins early in the stream when the
    // current bin would be left very empty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > 0.5 * bin_capacity as f64 && progress < 0.5 {
        score += 6.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it only if it would be worse to fragment an
    // existing bin; give it a mild baseline penalty so it loses close races.
    if bin_residual == bin_capacity {
        score += 3.0;
        // But if no good fit exists elsewhere (large post_residual would remain),
        // a fresh bin becomes attractive.
        if next_item_size > 0 && post_residual as f64 > 1.5 * next_item_size as f64 {
            score -= 15.0;
        }
        if next_item_size == 0 && post_residual as f64 > 0.4 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: fraction of bin used by this placement.
    let used_frac = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * used_frac;

    // Penalize dead space that is too small to hold even the smallest future item,
    // scaled by how "wasted" the bin becomes.
    let dead = post_residual as f64;
    if dead > 0.0 {
        let unusable = (dead < 10.0) as f64;
        score += 40.0 * unusable * (1.0 - dead / bin_capacity as f64);
        // General small-residual penalty (quadratic in leftover).
        score += 0.02 * dead * dead;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 {
        if (next_item_size as f64) <= dead {
            score -= 35.0;
            // Bonus if next item would exactly fill the bin afterwards.
            if dead - next_item_size as f64 == 0.0 {
                score -= 60.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            score += 0.3 * (next_item_size as f64 - dead).min(50.0);
        }
    } else {
        // Last item: just minimize leftover.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins; penalize the empty-bin candidate accordingly.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score += 25.0 + waste;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // But if this item is huge and mean residual is small, a new bin is fine.
        if used_frac > 0.7 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Prefer bins with below-average residual (denser bins) when several fit.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Time horizon: early on, be slightly more willing to spread items
    // (keep flexibility); late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress * 0.5);
    score -= 40.0 * poly;

    // Tight fits rewarded more as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 30.0 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (x * cap - mean_residual) / cap;
    score += 15.0 * dead * dead;

    // Last-chance bin bonus (smooth, gated by fitting bins)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        let ratio = next_item_size as f64 / cap;
        score -= 18.0 * fits_next * ratio * (1.0 - progress * 0.3);
    } else {
        score -= 10.0 * (1.0 - x);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - x);

    // New-bin candidate: penalize slightly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by divisibility
    // into useful chunk sizes (common item sizes like 10, 20, 25, 50).
    let post = post_residual;
    let useful_chunk = if post == 0 { 0u32 }
        else if post % 50 == 0 { 50 }
        else if post % 25 == 0 { 25 }
        else if post % 20 == 0 { 20 }
        else if post % 10 == 0 { 10 }
        else if post % 5 == 0 { 5 }
        else { 1 };
    // Reward leftovers that are cleanly divisible (likely reusable).
    score -= (useful_chunk as f64) * 0.4;

    // Penalize tiny dead space (< 10) strongly: it is unusable for any item.
    if post > 0 && post < 10 {
        score += 40.0;
    }

    // If next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post {
        // Next item fits: bonus proportional to how snugly.
        score -= (post - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // Next item won't fit here regardless; mild penalty for wasting this bin's future.
        score += (next_item_size - post) as f64 * 0.1;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current item leaves a large,
    // harmonically-useful residual or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // More attractive early in the stream (future flexibility worth more).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // Attractive if item is large (leaves small, well-defined residue class).
        if item_size >= 50 {
            score -= 30.0;
        }
        // Penalize opening new bins when many are open with slack.
        score += open_bins_count as f64 * 5.0;
        if mean_residual > 30.0 {
            score += 30.0;
        }
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for bins whose residual is in a "harmonic" band
    // matching the item size class (item_size mod 10 classes).
    let item_class = item_size / 10;
    let residual_class = bin_residual / 10;
    if residual_class == item_class + 1 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps ("dead space") after placement.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residual below mean (tighter bins get used first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use the leftover: penalize dead space more.
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (large item relative to residual) or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (bin_residual.saturating_sub(item_size) < 10);
        if poor_fit {
            score -= 35.0;
        } else {
            score += 20.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Early in stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // this bin is a perfect 2-item sequence -> strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover dead space after both placements
            let two_step_residual = post_residual - next_item_size;
            score += two_step_residual as f64 * 1.5;
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Reward tight fits relative to current item
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // late in stream, avoid opening new bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Many open bins: prefer consolidating into existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness * cap;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are wasted
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
        // Extra reward if post_residual - next_item leaves a small, still-usable gap.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap <= 20.0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Bin would be dead for the lookahead item; mild penalty.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins among many open bins (mild best-fit reinforcement).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more willing to spread out; later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / cap);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let poor_fits = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual >= item_size as f64 + next_item_size as f64);
        if poor_fits || fragmentation > 2.0 {
            score -= 10.0 + 5.0 * (next_item_size as f64 / cap);
        } else {
            score += 20.0; // discourage opening new bins when open ones fit decently
        }
    }

    // Mild penalty for very large waste relative to item size.
    if post_residual as f64 > 2.5 * item_size as f64 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit, ->0 = loose
    let progress_gain = tightness * tightness * (0.5 + progress) * cap * 0.6;
    score -= progress_gain;

    // Penalize residual that is small but useless (dead space): quadratic bump near low residuals
    let dead = (pr / cap).powi(2) * (1.0 - (pr / cap)) * cap * 0.8;
    score += dead;

    // Lookahead: reward if the next item fits into the post residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain = (next_item_size as f64 / cap) * (1.0 + progress) * cap * 0.5;
        score -= chain;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to wasted potential
        score += (next_item_size as f64 / cap) * cap * 0.15 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * 0.5 * (0.5 + progress);
    }

    // Encourage consolidation: prefer bins with residual below the mean when many bins are open
    let mean_gap = (bin_residual as f64 - mean_residual) / cap;
    score += mean_gap * open_bins_count as f64 * 2.0;

    // New-bin candidate: penalize opening a new bin unless the item is large relative to capacity
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += cap * (0.35 + 0.5 * (1.0 - size_ratio)) + open_pressure * 5.0;
        // late-stream: opening fresh bins is more acceptable for big items
        score -= progress * size_ratio * cap * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr % 10; // decile class of dead space
    // Penalize awkward dead-space classes (1,3,7,9 -> hard to fill with small items)
    match class {
        1 | 3 | 7 | 9 => score += 6.0,
        5 => score += 2.0, // half-class is somewhat usable
        0 => score -= 4.0, // perfectly aligned residual is reusable
        _ => {}
    }

    // Integer division thresholds: large post_residual means bin still very usable.
    if pr >= bin_capacity / 2 {
        score -= 8.0;
    } else if pr >= bin_capacity / 4 {
        score -= 2.0;
    } else if pr > 0 {
        score += 5.0; // tiny residual = near-wasted bin
    }

    // Perfect fit reward via modulo coupling between item and residual.
    if bin_residual % item_size == 0 && item_size > 1 {
        score -= 7.0;
    }
    if pr == 0 {
        score -= 25.0; // exact closure is ideal
    }

    // Lookahead coupling: prefer leaving post_residual that fits next item exactly.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - pr) as f64 * 0.05;
        }
        // Harmonic compatibility: next item divides remaining space cleanly
        if pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it neutral-ish, only attractive when
    // current bin would leave badly fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.9 + progress * 10.0;
        if post_residual as f64 > mean_residual + cap * 0.3 {
            score -= 15.0; // open fresh bin when existing ones are fragmented
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is highly desirable
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make opening a new bin unattractive unless
    // the current bin would leave a very poor residual relative to the next item.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 0.5;
        // Exception: if the next item is large and this placement would strand
        // a residual smaller than the next item, opening a fresh bin is fine.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score -= 45.0;
        }
    }

    // Lookahead: if the post residual exactly accommodates the next item,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space relative to lookahead: penalize stranded gaps.
        score += 8.0;
    }

    // Slight preference for bins with below-average residual (keeps large
    // residual bins available for large future items).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward proportional to how snugly it chains.
            score -= 200.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize dead space relative to next item.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residuals far below the mean (creating unusable pockets).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 50.0 + 20.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 100.0; // existing bins likely serve the next item
        }
    }

    // Late in the stream, consolidate: prefer bins that end fuller.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit ratio: how well the item fills this bin's remaining space
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits strongly (non-linearly)
    if fit_ratio > 0.75 {
        score -= 30.0 * (fit_ratio - 0.75) * 4.0;
    } else if fit_ratio > 0.5 {
        score -= 10.0 * (fit_ratio - 0.5);
    }

    // Penalize leaving awkward dead space that a typical item (>=10) can't use
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // perfect closure, excellent
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 4.0; // mildly awkward zone
    }

    // Lookahead coupling: if the next item fits the post-residual, reward it
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 3.0 * (1.0 - progress); // dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global residual pressure: if mean residual is high, prefer reusing bins
    if mean_residual > 30.0 {
        score -= 2.0;
    }

    // Many open bins: discourage fragmentation, favor consolidation
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for new bin
        let mut new_bin_score = 55.0 + post_residual as f64;
        // Early in stream, new bins are cheaper (more future to amortize)
        new_bin_score -= 20.0 * (1.0 - progress);
        // Large items deserve fresh space
        new_bin_score -= (item_size as f64 - 40.0).max(0.0) * 0.5;
        // If only one fitting bin exists, opening a new bin is less needed
        if fitting_bins_count <= 1 {
            new_bin_score += 15.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Smooth polynomial coupling: waste penalty grows non-linearly with progress
    let waste = post_norm * post_norm * (1.0 + 2.0 * progress);

    // Perfect-fit reward (smooth, non-piecewise)
    let perfect = -8.0 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 + 3.0 * progress);

    // Penalize tight fits that leave unusable slivers (< typical small item)
    let sliver = if post > 0.0 && post < 10.0 { 12.0 * (10.0 - post) / 10.0 } else { 0.0 };

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Lookahead: reward if next item fits the post-residual
    let lookahead = if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        -3.0 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        2.0 * (1.0 - post_norm)
    } else {
        0.0
    };

    // Mild preference for fuller bins relative to fleet mean residual
    let mean_coupling = -1.5 * (mean_residual - post) / cap;

    // New-bin candidate: neutral baseline, slightly favored early, penalized when many bins open
    let new_bin_bias = if bin_residual == bin_capacity {
        1.0 * (1.0 - progress) + 0.05 * open_bins_count as f64
    } else {
        0.0
    };

    let mut score = post + waste + perfect + sliver + last_chance + lookahead + mean_coupling + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead-space buckets via integer division ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill_frac = 1.0 - post / cap;

    // Reward high fill non-linearly (superlinear in fill fraction)
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class: post_residual mod 10 classes — small residues (<10) are near-unusable
    let residue_class = post_residual % 10;
    if post_residual > 0 && residue_class != 0 {
        // penalize awkward leftover that few future items (min size 1..100) can pair with
        score += 6.0 * (1.0 - residue_class as f64 / 10.0);
    }

    // Integer-division thresholds on post_residual: which standard item sizes still fit?
    // Items 1..100 unknown; estimate usable classes: [1,25], [26,50], [51,100]
    let class = post_residual / 25; // 0,1,2,3,4
    score -= 4.0 * class as f64; // more usable space = better

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= post_residual {
            // next item fits here: strong reward, scaled by how snugly it fits
            let snug = 1.0 - ((post_residual - nxt) as f64 / cap);
            score -= 18.0 + 12.0 * snug;
            // harmonic bonus: next item lands post_residual on a round class boundary
            if (post_residual - nxt) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize, worse if gap is small (wasted potential)
            let gap = (nxt - post_residual) as f64;
            score += 8.0 * (1.0 - gap / cap).max(0.0);
        }
    } else {
        // last item: just fill as much as possible
        score -= 15.0 * fill_frac;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // only this bin can take the item; avoid opening a new bin unless post_residual is terrible
        if post_residual <= bin_capacity / 10 {
            score -= 25.0; // near-perfect close-out, definitely use it
        } else {
            score -= 10.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early when few bins open; less so late / when many bins exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        // If mean residual is large, prefer reusing existing space instead
        score += 0.3 * mean_residual;
        // But if this is the last-chance scenario the -25 above won't apply here; keep new bin costly
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin may serve it later
        }
    }

    // --- Mean-residual coupling: penalize bins far above mean (fragmentation avoidance) ---
    score += 0.15 * ((post - mean_residual).abs());

    // --- Progress-scaled tie-break: prefer tighter bins as stream matures ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    let min_useful = 10u32.min(bin_capacity); // smallest plausible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 * (min_useful - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Fractional waste relative to capacity: tighter fit preferred.
        score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);
    }

    // Reward bins whose leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // dead space relative to the known future
        }
    }

    // Last-chance pressure: if this is the only bin that fits, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is penalized via the empty-bin branch.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Discourage picking a full-ish bin when mean residual is large
    // (spread load only if others are roomy).
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0 + 1.5 * open_bins_count as f64;
        // But if no open bin fits (or this is the last chance and fit is bad),
        // opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fits (smaller post_residual) score lower,
    // but avoid rewarding near-zero dead space too strongly.
    let pr = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // ideal packing chain
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits after this placement: mild reward scaled by snugness.
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 15.0 * snug;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize unusable dead space.
        score += 20.0 * (pr / bin_capacity as f64);
    }

    // Penalize very small residuals that are likely dead space (below min item size).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 10.0 * (25.0 - pr) / 15.0;
    }

    // Relative-to-mean coupling: bins with residual well below mean are "tight" resources;
    // filling them is good if it leaves a usable residual, bad if it fragments.
    if pr < mean_residual {
        score -= 5.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 5.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are hopeless.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.05 * open_bins_count as f64;
    }

    // Mild stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that no future item (min size 1, typical >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin becomes very attractive (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.3;
        if slack == 0.0 {
            score -= 25.0; // perfect chain
        }
    }
    // If next item does NOT fit in post_residual, mildly penalize creating
    // residuals that are close-but-insufficient (wasted potential).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(3) {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio; // reward using the last fitting bin
    }

    // New-bin candidate handling: empty bin gets residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer existing bins when any decent fit exists; scale penalty
        // with how many bins are already open (encourage consolidation early).
        let consolidation_pressure = (open_bins_count as f64).sqrt() * 3.0;
        score += 18.0 + consolidation_pressure;
        // But if the item is huge relative to typical residual, opening fresh
        // can be fine: relax penalty for large items.
        if item_size >= 70 {
            score -= 10.0;
        }
        // No lookahead chain possible in an empty bin beyond next item; if next
        // item is large too, opening is less attractive (keep penalty high).
        if next_item_size >= 60 {
            score += 8.0;
        }
    }

    // Global state: when mean residual is high, spread items; when low,
    // tighten packing preference.
    let mr = mean_residual / bin_capacity as f64;
    score += mr * (post_residual as f64) * 0.5;

    // Time horizon: early in the stream, be more exploratory (mild bonus for
    // balanced residuals); late in the stream, aggressively minimize waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.6;
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to the item (tightness term).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Small jitter-free tie-breaker: prefer lower-indexed-equivalent via
    // open_bins_count normalization (favor filling fewer bins).
    score += open_bins_count as f64 * 0.01 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = post;
    // smooth polynomial coupling of post_residual with stream progress
    let curve = 1.0 + 0.8 * progress - 1.2 * progress * progress + 0.6 * progress * progress * progress;
    score *= curve;
    // penalize large dead space more than linearly, modulated by progress
    score += 30.0 * norm_post * norm_post * (0.5 + progress);
    // reward tight fits
    score -= 20.0 * norm_item * (1.0 - norm_post);
    // lookahead: reward leaving space close to next item size
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0);
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // new-bin candidate: mild penalty so open bins preferred unless very tight fit
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }
    // mean residual coupling
    score += 5.0 * (post - mean_residual) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 4 and modulo 10.
    let r4 = post_residual % 4;
    let r10 = post_residual % 10;
    let half = bin_capacity / 2;

    // Dead-space penalty: residual classes that are hard to fill later.
    // Small odd residues (1,2,3 mod 10) are nearly unusable -> heavy penalty.
    if r10 > 0 && r10 <= 3 {
        score += (4 - r10) as f64 * 6.0;
    }
    // Residual exactly 0 is perfect closure -> strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Quarter classes: residual in [1..25] is a "low harmonic" (wasted), penalize;
    // residual in (25..=50] is mid-class; >50 leaves room for medium items.
    if post_residual > 0 && post_residual <= 25 {
        score += 8.0 + (25 - post_residual) as f64 * 0.2;
    } else if post_residual > 25 && post_residual <= half {
        score -= 3.0;
    } else if post_residual > half {
        score -= 5.0;
    }

    // Integer division threshold: floor(post_residual / 10) small bins are risky.
    let decile = post_residual / 10;
    if decile <= 1 && post_residual > 0 {
        score += 5.0;
    }

    // Coupling with lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward for tight harmonic match (next item nearly fills remainder)
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 8.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += 20.0;
        // But if all open bins would leave terrible residue, new bin becomes attractive.
        if post_residual > half {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;
    if progress > 0.8 && post_residual <= 10 {
        score -= 6.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.3;
        if bin_residual < bin_capacity {
            score -= 3.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good fit.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are worse than a perfect fit (0) or a roomy remainder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Post-residual that cannot fit the next item is dead weight unless tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Bonus if post-residual can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += 1.5 * open_bins_count as f64;

    // Slightly prefer bins tighter than the mean (keeps big gaps for big items).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // matches the next item size exactly (perfect follow-up fit).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Exact match: next item fills this bin completely -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits inside the post residual: reward by tightness.
            let tightness = 1.0 - (post - nxt) / post.max(1.0);
            score -= 25.0 * tightness;
        } else {
            // Next item would NOT fit in this bin's leftover: penalize
            // proportionally to how much dead space remains.
            let waste = (nxt - post) / bin_capacity as f64;
            score += 20.0 * waste;
        }

        // Coupling with mean residual: prefer bins whose post residual
        // deviates favorably from the mean (lower = tighter bin usage).
        score -= 0.5 * (mean_residual - post);
    }

    // Last-chance bin (only fitting bin): avoid opening a new bin unless
    // the fit is terrible; reward using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating very small unusable fragments (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight preference to fill existing bins rather than open new ones
    // when many bins are already open.
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but penalize near-waste.
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * cap * 0.35;

    // Penalize dead space: post residuals that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 25.0 + next_item_size as f64 * 0.4;
        } else {
            // Next item won't fit here; penalize leaving moderately-sized gaps.
            score += (post_residual as f64) * 0.25;
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: maximize fill of the stream's end.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 6.0;
    }

    // Global state: when many bins are open, consolidate rather than spread.
    let open_f = open_bins_count as f64;
    score += open_f * 1.5;

    // Mean residual coupling: if this bin's residual is below average, it's
    // already "dense" — finishing it is good; leaving it sparse is wasteful.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Time horizon: early in the stream, allow more exploratory new-bin opens;
    // late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0;
    score += (1.0 - progress) * 10.0;

    // New-bin candidate calibration: an empty bin gets the base post_residual
    // (= capacity - item_size). Make new bins attractive only for large items
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap;
        score -= 15.0 + avg_fullness * 40.0 + (item_size as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize large residuals more strongly
    let progress_coupling = 1.0 + 2.0 * progress * norm_pr;
    score *= progress_coupling;

    // Perfect fit reward (smooth exponential)
    score -= 10.0 * (-pr as f64 / 5.0).exp();

    // Dead-space penalty: residuals too small for typical items become waste
    if pr > 0.0 {
        let unusable = (-(pr - 15.0) * (pr - 15.0) / 50.0).exp();
        score += 8.0 * unusable * (1.0 + progress);
    }

    // Last-chance bonus: avoid opening new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * progress;
        // If next item is large, opening fresh bin is more attractive
        score -= 0.05 * next_item_size as f64;
    }

    // Lookahead: reward leaving residual that fits next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 - pr).abs() / cap;
    }

    // Mean-residual coupling: keep residuals balanced across bins
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Class bonus: residuals that are exact harmonic fractions of capacity
    // (multiples of capacity/8) are "reusable" classes -> reward them.
    if pr % eighth == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % (bin_capacity / 16) == 0 && pr > 0 {
        score -= 3.0;
    }

    // Penalize dead space: residual below the smallest plausible item class
    // (integer division threshold on post_residual).
    if pr / eighth == 0 && pr > 0 {
        score += 25.0; // tiny unusable sliver
    } else if pr < quarter {
        score += 8.0; // below quarter-capacity: hard to fill
    }

    // Modulo-class pairing: if next item exactly matches post_residual
    // (perfect fill) or post_residual % next_item_size == 0 (clean split), reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 10.0;
        } else if next_item_size > pr {
            score += 5.0; // next item cannot use this residual
        }
        // Harmonic class of next item vs residual class
        let next_class = next_item_size / eighth;
        let resid_class = pr / eighth;
        if next_class == resid_class && pr >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Penalize bins far from the mean residual (fragmentation avoidance),
    // scaled by how many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive when current fit is bad
    // (large post_residual waste or tiny dead space in the best existing option).
    if bin_residual == bin_capacity {
        let waste_penalty = if pr > 0 && pr < quarter { 30.0 } else { 0.0 };
        score = cap * 0.55 + waste_penalty - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are wasted; large gaps are useful.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // unusable sliver (min item size 10) -> heavy penalty
        } else if post_residual <= 20 {
            score += 18.0;
        } else if post_residual <= 30 {
            score += 6.0;
        } else {
            score -= 8.0; // roomy residual is valuable
        }
    } else {
        score -= 60.0; // perfect fill
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: with many open bins, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += 0.6 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // New empty bin candidate: only attractive when it beats a poor fit.
    if bin_residual == bin_capacity {
        // Opening fresh costs a bin; penalize moderately so only bad fits lose.
        score += 55.0 + 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference to use bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
