pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins whose post-residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize dead space quadratically: small leftovers are wasted space.
    if post_residual < item_size {
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this bin becomes more attractive (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize unusable slivers.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residual capacity flexible); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount later.
        score += 15.0 * (1.0 - progress);
        score -= 10.0 * progress;
        // Prefer a new bin if the item would leave a very awkward fit elsewhere.
        if post_residual < 10 {
            score -= 20.0;
        }
    } else if progress > 0.7 {
        // Late stream: discourage spreading across many open bins.
        score += open_bins_count as f64 * 0.5;
    }

    // Global residual state: if mean residual across bins is high, prefer
    // filling the emptiest bins (large residual) to reduce fragmentation.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild preference for bins whose residual is just above item size
    // (best-fit style sharpness).
    score += (bin_residual - item_size) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: minimize leftover, with quadratic dead-space penalty
    let mut score = post + 25.0 * norm_post * norm_post;

    // Smooth progress coupling: later in stream, tighter packing preferred
    score -= 12.0 * (1.0 - progress) * norm_post;
    score += 8.0 * progress * norm_post * norm_post;

    // Reward near-perfect fits smoothly
    score -= 15.0 * (1.0 - norm_post).powi(3);

    // Last-chance bonus (smooth via fitting count)
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Slight penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Lookahead: favor bins whose post-residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - post).max(0.0) / cap;
    }

    // Prefer bins below mean residual slightly (use tighter bins)
    score += 0.02 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste tiers via integer division
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize dead space that cannot fit a plausible next item (harmonic classes of 100)
    let dead_threshold = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < dead_threshold {
        score += 25.0;
    }

    // Reward near-perfect fills: post_residual in {0, small}
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 are more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Penalize awkward residuals (prime-ish / odd classes)
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 6.0; // small leftover, low utility
    } else if post_residual >= 2 * quarter {
        score -= 5.0; // large leftover, still flexible
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 10.0; // this placement kills the next item's fit here
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = mean_residual / cap;
        // Opening new bin penalized normally, relieved when mean residual is low
        score += 15.0 - 20.0 * (1.0 - crowd) - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for tightest existing fit relative to mean residual
    score -= (mean_residual - post).clamp(-30.0, 30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
