    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 8.0;

    // Perfect fit reward: leaving almost nothing behind is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    }

    // Open bins pressure: with many open bins, prefer reusing existing bins
    // (subtract more for placing into an existing bin relative to opening new).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln1p() * (1.0 + progress);
    score -= pressure * 3.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

