        score += 10.0 - scarcity * 14.0 - (open_bins_count == 0 as usize as u32 as usize as usize) as f64 * 0.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter-than-average bins get priority to consolidate).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        if dev < 0.0 {
            score += dev * 0.05; // tighter bin (smaller residual) slightly favored
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
