    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small leftovers are "dead space"
    // classes; reward residuals that fall into reusable harmonic buckets.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr <= 5 {
        score += 25.0; // unusable sliver
    } else if pr <= 15 {
        score += 10.0; // low-utility class
    } else if pr <= 30 {
        score -= 6.0; // good reusable class
    } else {
        score -= 12.0; // large residual, still flexible
    }

    // Modulo-10 harmonic: residuals divisible by 10 pair well with the
    // typical item granularity.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: can the next item exactly fit the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 20.0; // near-perfect chain
        } else if next_item_size > pr {
            score += 8.0; // next item cannot use this bin anyway
        }
        // Harmonic pair: next item leaves a multiple-of-10 remainder
        if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is poor or
    // the item would leave a nasty sliver in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain
        // (amortization) and when this bin would host a large item cleanly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 20.0 + 40.0 * progress;
        if item_size >= 50 {
            score -= 10.0;
        }
        if post_residual <= 5 && item_size < 50 {
            score -= 25.0; // big item almost filling a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else {
        // Prefer tighter existing bins relative to the mean residual.
        score += (bin_residual as f64 - mean_residual) * 0.3;
        // Penalize scattering across too many open bins.
        score += open_bins_count as f64 * 0.5;
    }

    // Early stream: be slightly greedy toward compact fits.
    if step_index < total_items / 4 {
        score += post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 10)
    // are nearly worthless; penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 7.0;
    }

    // Reward tight fits: post_residual close to zero is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 25.0 / (1.0 + post_residual as f64);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (within 10), mild reward.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(10) && post_residual < next_item_size {
        score -= 4.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 15.0; // use it even if it creates dead space
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin_bonus = (open_bins_count as f64).powf(1.3);
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize by open-bin count so it only wins when
        // existing bins fit poorly.
        score += 25.0 + new_bin_bonus;
        // But if this is the last item, a fresh bin is fine.
        if next_item_size == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for using bins with larger residuals among open bins
    // (consolidation), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize placements that leave residual far from mean residual extremes
    // (keeps a spread of usable gap sizes).
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item size -> perfect chain
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space trap)
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal waste
        score += 10.0;
    }

    // Prefer bins already below mean residual (consolidate fullness)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a needless new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early stream: be slightly conservative, favor new bins less aggressively later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // New empty bin candidate: penalize unless current bin would leave tiny waste
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual < 10 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize wasting a good residual.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bonus: only one open bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (consolidate fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Time horizon: early in stream, encourage opening new bins for large items;
    // late in stream, prefer filling existing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 - 25.0 * t) * (item_size as f64 / 100.0);

    // Slight preference to reuse existing bins when many are open.
    score += new_bin * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Penalize leaving residual that is large but awkward (> half capacity unused).
    if post_residual > bin_capacity / 2 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep-like
    score += 20.0 * pr_norm * pr_norm * prog_poly;

    // Penalize large post_residual more aggressively as stream progresses
    score += 8.0 * pr_norm * progress;

    // Reward tight fits (small post_residual) with a smooth cubic bonus
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Dead-space penalty: post_residual too small to plausibly fit future items
    let dead = (15.0f64 - pr).max(0.0) / 15.0;
    score += 10.0 * dead * dead;

    // Lookahead: reward if next item fits into post_residual, smooth coupling
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let gap = (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        score -= 6.0 * fits * (1.0 - gap) * (0.5 + progress);
        score += 4.0 * gap * (1.0 - fits);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Slight penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins near the mean residual (smooth)
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via modulo classes
    let pr = post_residual;
    let small = (pr <= 10) as f64;
    let tiny = (pr == 0) as f64;
    // Modulo-10 residue class: residuals divisible by 10 pair better with future items
    let mod10 = (pr % 10) as f64;
    score -= 12.0 * tiny;
    score -= 6.0 * small;
    score -= 1.5 * (10.0 - mod10) / 10.0 * (pr > 0 && pr <= 50) as i32 as f64;

    // Integer-division thresholds: quarter classes of capacity
    let q = pr / 25; // 0..4
    score -= match q {
        0 => 8.0,
        1 => 2.0,
        2 => 0.0,
        _ => -1.0,
    };

    // Lookahead coupling: harmonic match between post_residual and next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (slack <= 10) as i32 as f64;
            score += 0.05 * slack;
        } else {
            score += 4.0;
        }
        // modulo match: next item and residual share harmonic class
        if next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * open_bins_count as f64;
    }

    // Progress-scaled tightness preference
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * small;

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps below the minimum item size are pure waste; gaps that cannot
    // fit the next item are also likely dead space.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but allow new bin when this is the only fitting bin (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when open bins are crowded.
        score -= open_bins_count as f64 * 0.05;
        // But penalize opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 6.0;
        // Prefer new bin if next item is large (keeps big items together).
        if next_item_size >= 50 {
            score -= 4.0;
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= open_bins_count as f64 * 0.02;
    }

    // Coupling with mean residual: avoid leaving bins far below average fill.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Penalize residuals too small to ever be useful (dead space).
    if post_residual < 10 {
        score += 25.0;
    }

    // Prefer filling bins whose residual is below mean (tighter bins first).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Late in the stream, consolidate: favor bins that are already quite full.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.3;

    // Mild penalty for opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that can't fit the smallest plausible item (<= ~10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // If next item won't fit but nearly fits, mild penalty for stranding residual.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual close to item_size (best-fit coupling).
    score += 0.5 * (bin_residual as f64 - item_size as f64).abs();

    // Time horizon: early in stream, encourage keeping bins flexible (larger residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    // Global pressure: many open bins -> discourage spreading, favor filling existing.
    score -= 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins below mean residual are "dirtier", prefer filling them.
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        score += 20.0 + 0.1 * open_bins_count as f64 - 15.0 * desperation;
        // Late in stream, opening a new bin is more acceptable.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins with less leftover after placement.
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly -> weight grows quadratically.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    // Normalized dead-space fraction, shaped by a smooth convex penalty.
    let dead_frac = post / cap;
    score += progress_weight * 20.0 * dead_frac * dead_frac * cap;

    // Reward tight fits: smooth sigmoid-like bonus centered on high fill ratio.
    let fill_ratio = item / cap;
    let tightness = (fill_ratio * 4.0 - 1.0).tanh();
    score -= 8.0 * tightness;

    // Lookahead: penalize if the next item cannot use the post-residual (smooth falloff).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 {
            score += 6.0 * (gap / cap).tanh();
        } else {
            score -= 4.0 * ((-gap) / cap).tanh();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    let mean_frac = mean_residual / cap;
    score += 0.05 * (open_bins_count as f64).ln() * mean_frac * cap;

    // New-bin candidate: neutral baseline with slight progress-dependent cost.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and awkward small residuals
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure is ideal
    } else {
        // Dead-space penalty grows sharply for small unusable residuals
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        }
        // Modulo classes: residuals that are multiples of common item sizes (10,20,25,50)
        // are more likely to be filled by future items -> reward them
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Residuals in awkward prime-ish classes get penalized
        let awkward = pr % 7 == 1 || pr % 11 == 3 || pr % 13 == 5;
        if awkward { score += 5.0; }
    }

    // Coupling with lookahead: does next_item_size fit into post_residual exactly?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // chain a perfect fit
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 6.0; }
            if npr < 10 { score += 3.0; } // creates new dead space
        } else {
            // next item cannot use this residual; residual likely wasted
            score += (pr as f64).sqrt() * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Tightness reward: prefer bins where item occupies a large fraction
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 10.0;

    // Mild preference for bins already below mean residual (consolidate emptiness)
    score += ((post_residual as f64) - mean_residual) * 0.15;

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (i.e., when best residual would be very small / dead space heavy)
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.55;
        // if lookahead is large, a fresh bin is more attractive
        if next_item_size >= 50 { score -= 8.0; }
        // late in the stream, avoid opening bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // if many bins are open, prefer consolidation
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    let min_useful = 10u32; // smallest plausible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 2 * min_useful {
        score += 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Last-chance bonus: only one fitting bin left, use it rather than open new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + 0.5 * (1.0 - progress));

    // Prefer bins whose residual is close to the item (harmonic placement).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * gap;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use this residual: penalize leaving medium gaps
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.15 * waste;
            }
        }
    }

    // Mild preference toward bins below mean residual (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral base; last-chance / tight-fit bonuses elsewhere tip the scale.
        score += 5.0 - 20.0 * (fitting_bins_count as f64).recip().min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong subtraction for near-zero post residual.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or closely matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 150.0;
        } else if diff <= 5 {
            score -= 60.0;
        } else if diff <= 15 {
            score -= 15.0;
        } else {
            // Penalize post residuals that neither fit next item nor are small.
            score += diff as f64 * 0.3;
        }
        // If next item cannot fit in post residual, mild penalty proportional
        // to how far off we are.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin bonus: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: penalize moderately so it's only chosen when no
    // open bin offers a good fit, but keep it competitive vs. terrible fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * (bin_capacity - next_item_size) as f64;
            // Chain fit bonus when the pair nearly fills the bin.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Post residual cannot host next item: mild penalty scaled by wasted space.
            score += 0.05 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item relative to residuals) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Attractive if item is large and mean residual is small (poor fits elsewhere).
        let pressure = item_size as f64 - mean_residual;
        if pressure > 0.0 {
            score -= 0.6 * pressure;
        }
        // Discourage new bins early when few bins open (prefer consolidating).
        if open_bins_count <= 2 {
            score += 20.0;
        }
        // Late in the stream, opening bins for big items is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        score += 0.03 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // waste matters more as the stream advances.
    let progress_curve = progress * (1.0 - progress) * 4.0; // 0 at ends, 1 mid-stream
    score += post * post / cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= tightness * tightness * item * (0.3 + 0.7 * progress_curve);

    // Penalize dead space relative to mean residual across open bins (smooth).
    score += ((post - mean_residual).abs() / cap) * mean_residual * 0.25;

    // Lookahead: reward leaving room for the next item, smoothly scaled.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= (1.0 - (gap / cap)) * nxt * 0.35;
        } else {
            score += (-gap) * 0.2 * (0.5 + progress);
        }
    }

    // Last-chance bin: strong smooth incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress_curve;
    }

    // Mild preference to consolidate when many bins are open (smooth saturation).
    let open_norm = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score -= open_norm * post * 0.05;

    // Brand-new empty bin candidate: penalize opening new bins unless residual is large.
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 0.6 * progress) + post * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group dead space into buckets of 10 (capacity fractions).
    let class = post_residual / 10;
    let frac = (post_residual % 10) as f64;

    // Small classes (0-3) are near-perfect fits: strong reward.
    // Mid classes (4-7): moderate. Large classes (8-10): penalize wasted capacity.
    score -= match class {
        0 => 60.0,
        1 => 45.0,
        2 => 30.0,
        3 => 18.0,
        4 => 8.0,
        5 => 0.0,
        6 => -6.0,
        7 => -12.0,
        8 => -20.0,
        9 => -30.0,
        _ => -45.0,
    };

    // Fractional part within a class: prefer cleaner residuals (exact multiples of 10).
    score += frac * 0.4;

    // Lookahead: reward if next_item_size fits exactly into post_residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic when gap is small
            score -= (10 - gap.min(10)) as f64 * 1.2;
        } else {
            // next item cannot use this residual: slight penalty proportional to overflow
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: neutral baseline; only chosen if all open bins look bad.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in the stream: be slightly greedier with tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to ever be useful again are heavily penalized.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold as f64 - post_residual as f64) / dead_threshold as f64;
    }
    // Gaps that cannot fit the lookahead item (k=2) are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 45.0;
    } else {
        // Tightness reward: quadratic in fill fraction.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 25.0 * fill * fill;
    }

    // --- Open-bin pressure ---
    // Encourage closing out bins when many are open; discourage spreading.
    score += 0.35 * open_bins_count as f64;
    if post_residual > 0 {
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well.
        let poor_fit = post_residual > 0 && next_item_size > 0 && post_residual < next_item_size;
        if fitting_bins_count == 0 || (poor_fit && mean_residual < item_size as f64) {
            score -= 30.0;
        } else {
            score += 55.0; // prefer existing bins otherwise
        }
    }

    // --- Mild stream progression coupling ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (ideally exactly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: item + next item exactly fill the bin.
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one; prefer tight slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(50.0);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // Last item: just minimize leftover waste.
        score += post_residual as f64 * 0.2;
    }

    // Penalize creating unusable dead space (post_residual too small to
    // ever be useful for typical small items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize
    // bins far looser than average.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += mean_gap * 0.1;

    // Mild pressure to consolidate: fewer open bins -> favor filling
    // existing bins over opening new ones.
    score += (open_bins_count as f64) * 0.05;

    // Slight progression bias: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins
    // score poorly (their bonuses make them win on decent fits).
    if bin_residual == bin_capacity {
        score = 95.0 + (next_item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score toward 0 as the fill ratio approaches 1.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 45.0 * fill * fill;

    // Penalize small but unusable leftovers (dead space that few items can use).
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += 40.0; // tiny dead space is wasted capacity
        } else if r < 20.0 {
            score += 18.0 * (20.0 - r) / 10.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 6.0; // leftover too small for the next item
        }
        // If the next item fits exactly in the leftover, strong bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when a
    // reasonable fit exists elsewhere; encourage it only for large items or
    // when open bins are nearly full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // Large items pack better in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If open bins are congested (mean residual small), a new bin is fine.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * t;
        // Many open bins already: discourage another.
        score += 0.8 * open_bins_count as f64;
    } else {
        // Mild preference for filling bins that deviate from the mean residual
        // in the "low residual" direction (consolidation effect).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    // Penalty for dead space: squared normalized post residual, amplified late in stream
    let dead = 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth cubic term
    let tight = -30.0 * (1.0 - norm_pr).powi(3) * (1.0 + 0.5 * progress);

    // Lookahead: reward leaving space for the next item smoothly
    let nxt = next_item_size as f64;
    let lookahead = if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        -20.0 * (1.0 - gap / cap).max(0.0)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Mild penalty when many bins are open, smoothed by mean residual
    let crowd = 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    base + dead + tight + lookahead + last_chance + crowd
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into clean classes
    // are more reusable by typical item sizes. Penalize "dead" residues that
    // few item sizes can use.
    let post = post_residual;
    if post > 0 {
        // Residue class via integer division thresholds (harmonic bands)
        let band = post / 10; // 0..10 bands
        // Small residues (< 10) are nearly dead space -> heavy penalty
        if post < 10 {
            score += 25.0;
        } else if post < 20 {
            score += 8.0;
        }
        // Modulo arithmetic: residues that are multiples of common item sizes
        // (10, 20, 25, 50) are highly reusable -> reward.
        if post % 10 == 0 {
            score -= 6.0;
        }
        if post % 25 == 0 {
            score -= 4.0;
        }
        if post % 50 == 0 {
            score -= 5.0;
        }
        // Harmonic decay: reward grows like 1/band for mid bands
        if band >= 2 && band <= 8 {
            score -= 10.0 / band as f64;
        }
    } else {
        // Perfect fit: zero waste, strongest reward
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (creates a perfect two-item packing).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            let next_post = post - next_item_size;
            if next_post < 10 {
                score += 5.0; // would create new dead space
            } else {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current bin's
    // post-residual would be very small (dead space) or the fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 40.0;
        // But if placing here leaves a bad residue, new bin becomes attractive
        if post > 0 && post < 10 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 10.0;
        }
        // Many open bins with high mean residual: discourage new bins
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 15.0;
        }
    }

    // Slight preference for fuller bins (low residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Mild tie-breaker against bin proliferation
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space) that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 20.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / 25.0).max(0.0);
    }

    // Penalize leaving gaps just below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 30.0 * match_quality;
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportional to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.5 * shortfall;
    }

    // Relative-to-mean-residual coupling: bins tighter than average are precious.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f);
    } else {
        score += 0.2 * (residual_f - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving very small dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: only prefer opening a new bin when open bins are nearly full
    // and the current item is large relative to what remains.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fullness = 1.0 - mean_residual / (bin_capacity as f64);
        // Base new-bin score: high, but discounted as open bins get fuller.
        score = bin_capacity as f64 * 0.6 + 40.0 * (1.0 - avg_open_fullness) - 20.0 * progress;
        // If next item is large and no open bin could take both, new bin is attractive.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min size 1..~) can use later only if it is tiny;
    // instead penalize mid-range dead space which is the worst (neither tight nor reusable).
    let dead = post_residual as f64;
    if dead > 0.0 {
        let mid = (dead - 10.0).abs() as f64;
        score += 0.15 * mid;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space for the known next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance: only bin that fits the item -> strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in stream: favor consolidating into few bins; late: favor balance.
    if progress < 0.5 {
        score += 0.05 * open_bins_count as f64;
    } else {
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // New empty bin candidate: penalize mildly so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
        // But if no open bin fits (this is the only candidate), it wins naturally.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * x * x) + 8.0 * x * x * x;

    // Stream-progress coupling: later in the stream, waste matters more (convex).
    let prog_term = 1.0 + 2.0 * progress * progress;
    score *= prog_term;

    // Dead-space penalty: residual too small for any future item (items >= 1, but typical min ~10).
    let dead = (10.0f64).min(pr as f64);
    if pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual (smooth reward).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 6.0 * fit_quality * (1.0 + progress);
        } else {
            // Penalize when next item cannot fit, scaled by how far off it is.
            let gap = (ns - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    let dev = (mean_residual - pr).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: make empty bins attractive only when open bins are crowded.
    let crowded = mean_residual / cap;
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - 25.0 * crowded;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes of 10 units.
    let post_class = post_residual / 10;
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64).ln().max(0.0) * 0.5;

    // Penalize "awkward" residuals that no typical item (1..100) can pair with well.
    // Residuals in [1..9] are near-dead space; residuals divisible by 10 are reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // harmonic alignment: reusable by round-size items
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Reward if next item leaves a harmonic (multiple of 10) residual after itself.
        let rr = post_residual - next_item_size;
        if rr % 10 == 0 {
            score -= 8.0;
        }
        score += (rr as f64) * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize consuming this bin now.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit would be very wasteful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0
            - progress * 10.0
            + (mean_residual / bin_capacity as f64) * 20.0
            + (open_bins_count as f64) * 0.5;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // If next item is also large, prefer fresh bin to keep big space free.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing ones.
    if bin_residual != bin_capacity {
        score += mean_residual * 0.05;
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Class-match bonus: item class equals residual class implies near-half fill synergy.
    if post_class as i64 - item_class as i64 <= 1 && post_class as i64 - item_class as i64 >= 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 stream,
    // but small gaps below ~15 are rarely fillable efficiently).
    let dead_threshold = 15.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 3.0; // steep penalty for tiny dead gaps
    }

    // Reward tight fits: post_residual near zero (perfect fill) gets a bonus.
    if pr == 0.0 {
        score -= 25.0;
    } else {
        // graded tightness bonus: smaller post residual relative to capacity is better
        score -= (1.0 - pr / bin_capacity as f64) * 8.0;
    }

    // Penalize opening new bins when plenty of open bins exist (bin count pressure).
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost of opening a bin
        score += 18.0 + (open_bins_count as f64) * 1.5;
        // but if no open bin fits well, opening may be right: reduce cost when
        // current item is large (would leave big gap elsewhere)
        score -= (item_size as f64 / bin_capacity as f64) * 12.0;
    } else {
        // placing into an existing bin relieves pressure slightly
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0; // next item perfectly fills the leftover
        } else if (gap as f64) < dead_threshold {
            score += 4.0; // next item leaves a dead gap
        } else {
            score -= 3.0; // next item still fits reasonably
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    // (packing into below-average-residual bins consolidates space).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 6.0;

    // Slight stream-phase adjustment: late in the stream, be more conservative
    // about opening bins (amortization matters more).
    if total_items > 0 {
        let phase = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += phase * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (chained perfect fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 800.0;
        } else if post >= next {
            // Next item fits after this placement: reward closeness.
            score -= 300.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus if next item would then fill the bin perfectly.
            if (post - next) == 0 {
                score -= 200.0;
            }
        } else {
            // Next item cannot fit: penalize dead space proportionally.
            score += 50.0 + 2.0 * diff;
        }
    }

    // Compare post_residual against mean residual: leaving post_residual
    // far below mean creates unusable small pockets.
    let post = post_residual as f64;
    if post < mean_residual {
        score += 0.5 * (mean_residual - post);
    } else {
        score -= 0.2 * (post - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Late in the stream, prefer tighter packing (smaller post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Slight penalty for very small residual pockets (< 10) that likely
    // cannot fit future items (items >= 1, but small pockets are risky).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, extra penalty for medium waste
    let waste = post_residual as f64 / cap;
    score += 2.5 * (waste * (1.0 - waste)).max(0.0) * cap;

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            // dead space relative to next item
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current bin would leave big waste and many bins are open
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted late in the stream
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 - 20.0 * t;
        // if item is large, new bin is fine (keeps small residuals for small items)
        if item_size >= 50 {
            score -= 25.0;
        }
        // many open bins with high mean residual -> avoid opening yet another
        score += 0.4 * open_bins_count as f64 + 0.2 * mean_residual.max(0.0);
    } else {
        // prefer filling already-open bins; slight bias toward fuller bins
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Prefer bins whose residual stays "usable" (>= typical small item size 10)
    if post_residual >= 10 && post_residual < 30 {
        score -= 4.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space penalty
    }

    // Mild preference for keeping bin count low early
    if step_index < total_items / 4 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = post;
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks near half-full residual
    score -= 60.0 * poly * (0.5 + progress);
    score -= 25.0 * x * x * progress; // tighter packs favored later in stream
    score += 15.0 * (1.0 - progress) * x * x; // early stream: keep residuals flexible

    // Dead-space penalty: residual too small to matter relative to typical item
    let dead = ((30.0 - post).max(0.0)) / 30.0;
    score += 40.0 * dead * dead;

    // Lookahead: reward if next item fits post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 20.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Alignment with mean residual: prefer bins near mean to keep balance
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "usable" residue class (multiples of 10) are more likely to accept
    // future items, so reward them.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else {
        // penalize non-aligned dead space proportionally to how far from alignment
        score += class as f64 * 0.8;
    }

    // Integer-division threshold: residual buckets by capacity fraction.
    let frac = post_residual as f64 / cap_f;
    if frac < 0.1 {
        // nearly-full bin: excellent, strongly reward
        score -= 12.0;
    } else if frac < 0.25 {
        score -= 4.0;
    } else if frac > 0.8 {
        // leaving a huge mostly-empty bin while others exist is wasteful
        score += 5.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item leaves a multiple-of-10 residual too
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score -= 3.0;
        } else {
            // next item cannot use this residual: dead space penalty scaled
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than average (best-fit flavor, non-linear)
    let tightness = (bin_residual as f64 - mean_residual).max(0.0);
    score += tightness * 0.1;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let base = 8.0 + (open_bins_count as f64).sqrt() * 2.0;
        // penalize opening a new bin unless current item is large relative to capacity
        score = base + (item_size as f64 / cap_f) * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    let dead_threshold = 12u32; // below typical small item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    } else if post_residual < dead_threshold * 3 {
        // small-but-usable gaps get a mild penalty relative to their tightness
        score += (dead_threshold * 3 - post_residual) as f64 * 0.8;
    } else {
        // large leftover space: reward proportionally (bin remains flexible)
        score -= (post_residual as f64 - (dead_threshold * 3) as f64) * 0.15;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones;
    // with few open bins, allow consolidation into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow
        score += 10.0 + open_pressure * 4.0;
        // Exception: opening a new bin is good if the item is huge and no bin fits well
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Exception: if next item is large and this bin would be nearly full, fresh bin helps
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild reward for using open bins when many are open
        score -= open_pressure * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack < dead_threshold {
            score -= 10.0;
        }
    }

    // Stream progression: early on, keep bins flexible (mild penalty on tight fits);
    // later, accept tight fits aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Mean residual coupling: if mean residual across bins is low, avoid wasting this bin's space
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / mean_residual).min(1.5);
        score += tightness * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit relative to mean residual of open bins.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin closed after next item
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // good chain, less slack
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap; // next item won't fit here; dead space risk
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score += 0.5 * post_residual as f64;
    }

    // Penalize unusable dead space below the smallest plausible item (1..100 range: treat <10 as dead).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage when a good chain exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // fresh bin supports a perfect pair
        }
        // Late in the stream, prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild pressure against accumulating many open bins with large residuals.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer small post-residuals (tight fits).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Reward near-perfect fits.
    if post_residual <= 2 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize more if post_residual is wasted.
            score += (post_residual as f64) * 0.35;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many fitting bins: mild penalty for consuming a scarce-fit candidate.
    if fitting_bins_count > 2 {
        score += 1.5;
    }

    // Global state: if open bins are generally full (low mean residual),
    // prefer consolidating into tight bins rather than spreading.
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score += mean_res_norm * 3.0;

    // If this bin is much tighter than average, prefer it.
    let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= tightness * 5.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize using existing bins less); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 3.0;

    // New-bin candidate: opening a new bin is attractive when the item is large
    // and few bins fit it, or when open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 8.0;
        let scarcity_bonus = if fitting_bins_count <= 1 { 6.0 } else { 0.0 };
        // Late in the stream, avoid opening new bins.
        let late_penalty = progress * 10.0;
        score += 30.0 - large_item_bonus - scarcity_bonus + late_penalty;
    }

    // Mild penalty for opening many bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score -= (1.0 - norm_pr).powi(3) * (1.0 + progress) * 12.0;
    score += norm_pr * norm_pr * (1.0 - progress) * 10.0;
    // penalize small unusable leftovers, smoothly
    let dead = if post_residual > 0 { ((20.0 - pr).max(0.0)) / 20.0 } else { 0.0 };
    score += dead * dead * 8.0;
    // lookahead synergy: reward leaving space for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n).abs();
        score -= 10.0 * (-diff / 15.0).exp();
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // mild pressure from many open bins
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);
    // deviation from mean residual
    score += 0.1 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: dead-space quality via integer division thresholds
    // Residuals that are multiples of common small item classes (10/20/25/50) are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is best
    } else {
        let reusable = (pr % 10 == 0) as f64 + (pr % 20 == 0) as f64 + (pr % 25 == 0) as f64 + ((pr >= 50) as f64);
        score -= 8.0 * reusable;
        // dead space: tiny unusable leftover
        if pr < 10 {
            score += 45.0; // unusable for items >= 10; but sizes may be as small as 1
            score -= 20.0 * (pr as f64 / 10.0); // still, larger tiny residual slightly better
        }
        // quartile class of residual
        let q = (pr * 4) / bin_capacity; // 0..3 integer division class
        score -= match q {
            0 => 5.0,
            1 => 2.0,
            2 => 8.0,
            _ => 0.0,
        };
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - 0.4 * slack;
            if slack == 0.0 {
                score -= 30.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here: penalize wasting a big residual anyway
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline penalty grows with number of open bins that fit
        score = cap - 1.0; // worse than any decent existing fit (post_residual < cap-1)
        // but attractive if existing fits are all poor (big post_residuals / dead space)
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
        // early in stream, prefer consolidating; late, new bins are cheap-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild pressure to prefer tighter existing bins when many are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead-space threshold: gaps too small for the smallest plausible item.
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
        // Smooth quadratic penalty on wasted space relative to capacity.
        score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.5 * open_bins_count as f64;
        // Lookahead: if next item is small, a fresh bin is more acceptable.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 6.0;
        }
    } else {
        // Reward consolidating into existing bins, more when bins are numerous.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to mean (avoid fragmenting outliers).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead synergy: reward leaving space exactly fitting the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap unusable by the known next item: extra dead-space penalty.
        score += 8.0;
    }

    // Late-stream tightness: as stream progresses, be greedier about filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to tightness of the chain.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            // Extra bonus if the chain also ends tight.
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 10 {
                score -= 15.0;
            }
        } else {
            // Next item would NOT fit here: penalize leaving a gap that blocks the lookahead item.
            let gap = nxt - post;
            score += 10.0 + 0.5 * gap;
            // Small gap that is likely dead space anyway: soften penalty.
            if post <= 10 {
                score -= 8.0;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to keep tight.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.3 * (mean_residual - post_f);
    } else {
        score += 0.2 * (post_f - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins early in the stream; encourage consolidation later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that shrinks as stream progresses
        // and when few bins fit the item (a new bin may genuinely be best).
        score += 45.0 - 25.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
    } else {
        // Mild reward for reusing existing bins, stronger late in the stream.
        score -= 5.0 + 5.0 * progress;
    }

    // Slight preference for filling larger items into tighter bins.
    score += 0.05 * item_size as f64 * (post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
