    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Lookahead penalty: post_residual too small for next item but nonzero
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: penalize opening a new bin, more so for small items
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * item_size as f64;
