        }
    }

    // Mild preference for bins that are already well-filled (tight packing)
    score += (bin_capacity - bin_residual) as f64 * 0.02;

    // Late in the stream, tighten packing further (less room to recover)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Slight global pressure: many open bins with high mean residual -> pack tighter
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = rn * rn * (1.0 - progress) + rn * progress * progress;
    let mut score = r * (1.0 - 0.35 * progress) + 40.0 * poly;

    // Reward tight fits smoothly
    score -= (1.0 - rn).powi(3) * 15.0;

    // Last fitting bin: strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward residual that still fits the next item smoothly
    if next_item_size > 0 {
        let fits_next = if (r as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((next_item_size as f64) - r).abs() / cap;
        score -= fits_next * 12.0 * (1.0 - gap);
        score += 8.0 * gap * (1.0 - fits_next);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Deviation from mean residual: prefer bins near average to keep balance
    score += ((r - mean_residual) / cap).abs() * 5.0;

    // New bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let desperation = (fitting_bins_count == 0) as i32 as f64;
        score += 30.0 - desperation * 60.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "reusable" classes (multiples of common item sizes / quarter fractions)
    // are more valuable than bins with awkward dead space.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit: strongly favored
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr < 10 {
        15.0 // tiny dead space: nearly unusable
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: reward bins whose post residual can still host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            score -= 6.0 + 8.0 * (post - ni) / cap;
        } else {
            score += 5.0 + 10.0 * (ni - post) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
