        // If many bins are open with slack, opening another is wasteful.
        if mean_residual > item_size as f64 {
            score += 0.10 * (mean_residual - item_size as f64);
        }
        // Allow a new bin when the item is huge and no tight option exists
        // (large items pair poorly with small residuals).
        if item_size >= 70 && bin_residual - item_size < 30 {
            score -= 35.0;
        }
    } else {
        // Mild reward for using existing bins proportional to how much slack
        // they consume relative to the global mean residual.
        score -= 0.03 * (bin_residual as f64 - mean_residual);
    }

    // Discourage leaving residuals in the "awkward" 21..40 band that few items fit.
    if post_residual > 20 && post_residual < 40 {
        score += 4.0;
    }

    // Prefer bins with less residual overall (best-fit flavor) modulated by stream phase.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - phase) * 0.02 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 0.5 * progress) - norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 10.0;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * norm_next * (1.0 - norm_pr);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - norm_item);
    }

    // Slight preference against opening new bins early; more open bins late -> tighter packing
    score += (open_bins_count as f64).sqrt() * 0.5 * (1.0 - progress);

    // Mean residual deviation penalty (smooth)
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // residue classes modulo 10 and integer-division thresholds.
    let decile = post_residual / 10; // integer division threshold
    let residue = post_residual % 10;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if residue == 0 {
        score -= 40.0; // leftover is a clean harmonic multiple of 10
    } else {
        // Penalize awkward leftovers: non-multiples of 10 create dead space
        // since future items are >= 1 but typical classes align to 10s.
        score += (10 - residue) as f64 * 3.0;
    }

    // Big decile gaps are harder to fill later: superlinear penalty.
    score += (decile as f64) * (decile as f64) * 1.5;

    // Harmonic class of the item itself: large items (>= half capacity)
    // should be placed even in tight bins to avoid fragmentation.
    if item_size * 2 >= bin_capacity {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // this placement chains perfectly (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 {
                score -= 60.0;
            } else {
                score += (10 - chain_left % 10) as f64 * 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 25.0;
        }
    }

    // New-bin candidate handling: empty bin has no fragmentation yet,
    // but opening it wastes potential; prefer it only when the stream is
    // young or existing bins are highly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 120.0 + progress * 200.0 - fragmentation * 100.0 + pressure * 10.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // room for a harmonic pair in fresh bin
        }
    }

    // Slight preference for tighter existing bins when many fit.
    score += (fitting_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // worst dead space
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual > 50 {
            score -= 8.0; // large residual stays reusable
        }
    } else {
        score -= 40.0; // perfect fill is excellent
    }

    // Reward tight relative fit.
    score -= 25.0 * (1.0 - (item_size as f64) / cap);

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidate small gaps).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Lookahead: bonus if next item fits the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate baseline: neutral-ish but must beat only poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good, but only if the bin was actually used.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space more harshly when it can't fit the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // 2-step lookahead: this bin can host the next item too.
                score -= (post_residual - next_item_size) as f64 * 0.5;
                score -= 5.0;
            } else {
                // Dead space: post_residual < next_item_size.
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when existing bins have plenty of room.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if mean residual is small (open bins nearly full)
        // or the item is large relative to mean residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
        score += 15.0;
        score -= (mean_r - item_size as f64).abs() * 0.1;
        score += progress * 5.0;
        if item_size as f64 > mean_r {
            score -= 8.0;
        }
    } else {
        // Existing bin: mild preference for bins tighter than the mean (better packing).
        let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
        score += (bin_residual as f64 - mean_r) * 0.05;
    }

    // Slight preference to fill bins with more residual (larger holes get consumed first),
    // scaled by how crowded the bin set is.
    score -= (bin_residual as f64) * 0.02 * (open_bins_count as f64).sqrt().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively when many bins fit.
    let fit_bonus = (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    score += fit_bonus * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if the next item fits perfectly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0; // perfect chaining
            } else {
                score -= 20.0 / (gap as f64).sqrt();
            }
        } else {
            // Next item cannot use the leftover; penalize large dead space.
            score += 0.3 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.1 * post_residual as f64;
    }

    // Prefer bins with residual close to item_size (minimize fragmentation).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // Global state: if mean residual is high, encourage using existing bins to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= mean_residual * 0.05 * (1.0 - progress);

    // When many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But allow new bin early in the stream when it's cheap.
        score -= 30.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins overall.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    let mut score = x * x * (2.0 - x) * 100.0;

    let tightness = 1.0 - x;
    score -= tightness * tightness * (item_size as f64 / cap) * 30.0;

    let coupling = (progress * std::f64::consts::PI).sin();
    score += coupling * x * 15.0;

    if fitting_bins_count <= 1 {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    if next_item_size > 0 {
        let gap = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= gap * (next_item_size as f64 / cap) * 40.0;
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score += waste * waste * 20.0;
    }

    score += (mean_residual - pr) * 0.15;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class residuals into buckets of size 10 (capacity/10 harmonic grid).
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { (next_item_size + 9) / 10 } else { 0 };

    // Perfect harmonic match: next item's class exactly fills a large leftover class.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward if next item fits well: leftover after next placement is small.
        let post_after_next = post_residual - next_item_size;
        score -= 8.0 * (1.0 - post_after_next as f64 / bin_capacity as f64);
        // Extra reward when post_after_next lands on a "dead zone" boundary (tiny unusable)
        if post_after_next < 10 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot fit here: penalize mildly, worse if this bin would be stranded.
        score += 3.0;
    }

    // Dead-space penalty: residuals in (0,10) are almost unusable (min item 1..100 unknown,
    // but small residuals waste capacity fractionally).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Modulo coupling: post_residual mod 10 == 0 means alignment with the harmonic grid.
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    // Integer-division thresholds: big leftover classes are valuable, keep them flexible.
    match post_class {
        0 => score += 6.0,           // nearly full bin, but only if it's a real fill
        1..=2 => score += 2.0,       // small leftovers
        3..=5 => score -= 1.0,       // medium leftovers, decent
        _ => score -= 2.5,           // large leftovers, flexible
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and congestion.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 + 20.0 - 10.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is large and no bin is tight, new bin may be attractive.
        if next_item_size >= 60 {
            score -= 8.0;
        }
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 10.0 * fitting_bins_count as f64;
        }
    } else {
        // Favor tighter bins relative to mean residual (best-fit flavor with harmonic twist).
        score += 0.5 * (mean_residual - bin_residual as f64).abs();
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Early stream: be conservative, prefer packing existing bins to limit bin count.
    if progress_factor(step_index, total_items) < 0.2 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

fn progress_factor(step_index: usize, total_items: usize) -> f64 {
    if total_items == 0 { 1.0 } else { step_index as f64 / total_items as f64 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space below minimum item size is pure waste
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: ideal
    }

    // Mild preference for tight fits in general
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open-bins pressure: discourage spreading when many bins are open
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // residual too small for the next item: mild penalty
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so we prefer reusing bins; reduced when bins are crowded or mean residual is low
        score += 30.0 - 2.0 * open_bins_count as f64 - mean_residual.min(60.0) * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced to open a new bin
        }
    }

    // Late in the stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits here after current item: chain reward scaled by leftover
            let chain_left = post_residual - next_item_size;
            score -= 300.0 - (chain_left as f64).min(200.0);
        } else {
            // next item cannot use the post residual: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible = post_residual as f64;
        score += 50.0 + best_possible * 0.2;
    }

    // Late-stream consolidation: prefer filling existing bins toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= 2.5 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * (bin_capacity as f64);

    // Penalize dead space: post residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit; penalize wasted capacity relative to next item
            score += 0.3 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64).max(0.0)).min(post_residual as f64);
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing ones rather than opening new
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is below average residual, it's relatively full -> favor
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New bin candidate: penalize opening a new bin unless current bins are crowded/poor fits
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        score += 20.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open new bin
        }
        if progress > 0.8 {
            score += 10.0 * progress; // late stream: avoid spreading
        }
    }

    // Slight preference for larger items into larger residuals
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial base: reward small post_residual, penalized by progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling of post_residual with stream progress
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Dead-space penalty for residuals too small for any future item (min size 1..100 unknown, assume small)
    let dead = (1.0 - norm_post / 0.35).max(0.0);
    score += 8.0 * dead * dead;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Prefer bins with below-average residual (tighter packing)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 6.0 * (ns / cap) * (1.0 - norm_post);
        } else {
            score += 5.0 * ((ns - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_post;

    // Slight bias toward opening a new bin early vs late
    score += 3.0 * (1.0 - progress) * (norm_post.max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual via integer division thresholds.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Dead-space penalty for mid-range residual classes (harmonic bands of capacity).
    let band = post_residual / 10; // integer division class
    if band >= 2 && band <= 5 {
        score += 12.0 * band as f64;
    }

    // Modulo-class coupling: residuals in awkward modulo classes relative to item sizes
    // are harder to fill with typical small items (1..=20 common).
    let mod_class = post_residual % 7;
    if mod_class == 1 || mod_class == 5 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot fit here; penalize wasting a scarce fitting bin
            if fitting_bins_count <= 2 {
                score += 5.0;
            }
        }
    }

    // New-bin candidate handling: only attractive when this bin would be a poor host.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins slightly more early in the stream (more future items to place).
        let new_bin_bias = 25.0 - 15.0 * progress;
        score += new_bin_bias;
        // If the item would leave a large ugly residual anywhere, new bin is competitive.
        if post_residual >= 30 {
            score -= 20.0;
        }
        // Avoid opening new bins when many bins are already open and mean residual is high.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 30.0;
        }
    }

    // Mild global balance: prefer bins below mean residual when many bins are open.
    if open_bins_count > 1 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (items are >= 1 but small gaps waste capacity). Penalize harshly.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Moderate gaps (10..=20) are semi-dead: penalize softly.
    if post_residual > 9 && post_residual <= 20 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening a new empty bin when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 6.0;
        // But if the item fits poorly everywhere (large mean residual mismatch),
        // opening a fresh bin becomes more attractive.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If the next item cannot fit into post_residual but could fit a fresh bin,
    // slightly penalize leaving an over-tight gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late-stream consolidation: as the stream progresses, tighten bin usage.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer bins whose residual is close to the item (tight fits) beyond raw post_residual.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.6 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Lookahead: perfect match — next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits here too; reward closeness of the two-step fill.
            let two_step_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (two_step_waste as f64) / (bin_capacity as f64));
        } else {
            // Next item cannot follow in this bin; penalize if leftover is small (dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
            if post_residual < 10 {
                score += 15.0; // nearly unusable sliver
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-high unless
    // all open fits are poor (large post_residual waste).
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can serve next item well
        }
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; mild penalty for stranding capacity.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the current item is large and mean residual is small (fragmented state).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 12.0;
            // If no open bin fits well (this is the only fitting candidate), allow opening.
            if fitting_bins_count <= 1 && item_size >= 60 {
                score -= 20.0;
            }
            // Heavily fragmented open bins: opening fresh is attractive.
            if mean_residual < item_size as f64 && open_bins_count > 2 {
                score -= 10.0;
            }
        } else {
            score -= 40.0; // first bin is always good
        }
    }

    // Prefer tight fits among open bins: reward small post_residual relative to item.
    score -= (item_size as f64) * 0.1;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, exploit perfect fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Tie-break: prefer bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Late in the stream, waste is more costly, so curvature grows with progress.
    let curvature = 1.0 + 2.0 * progress;
    let mut score = cap * (x * x * curvature + 0.15 * x);

    // Smooth cubic interaction: very small post-residuals are excellent fits;
    // reward them more strongly as the stream progresses.
    let tight_fit = (1.0 - x).powi(3);
    score -= 30.0 * tight_fit * (0.5 + progress);

    // Dead-space coupling with mean residual: if this bin's post-residual is far
    // below the mean, we consolidated space well; penalize scores above mean.
    score += 0.4 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, with a smooth ramp on progress.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead coupling: reward leaving room close to the next item's size,
    // using a smooth Gaussian-like kernel around the exact match.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap * gap / (2.0 * 15.0 * 15.0)).exp();
        score -= 20.0 * kernel * (0.4 + 0.6 * progress);
    }

    // Mild preference for keeping the number of open bins low, smoothed.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate must not win unless it genuinely beats tight fits:
    // give the empty-bin call a smooth baseline cost that shrinks slightly
    // with progress (early stream tolerates more bins).
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space classes modulo 10
    let pr = post_residual as i64;
    let class = pr % 10;
    // Residuals that are hard to fill (small nonzero leftovers) get penalized
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 3.0;
    }
    // Classes divisible by 5 are "harmonic" — easier to fill later
    if class == 0 || class == 5 {
        score -= 12.0;
    }
    // Exact division: post_residual divides capacity evenly -> reusable slots
    if pr > 0 && (bin_capacity as i64) % pr == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n <= pr {
            // next item fits exactly-ish: strong reward
            if n == pr {
                score -= 200.0;
            } else {
                let gap = pr - n;
                // reward small gaps (near-perfect chain), penalize large gaps mildly
                score -= 40.0 - (gap as f64).min(40.0);
                if gap <= 5 {
                    score -= 20.0;
                }
            }
        } else {
            // next item won't fit here: penalize proportionally to overflow
            score += ((n - pr) as f64) * 0.8;
        }
    }

    // Last-chance bin: only fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer opening fresh bin only when fits are poor
    if bin_residual == bin_capacity {
        // mild default bonus toward reuse: new bin slightly penalized
        score += 30.0;
        // but if no open bin fits well (post_residual large relative to item), allow new bin
        if post_residual > bin_capacity / 2 {
            score -= 55.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's "wasted space"
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // Stream progression: late in stream, tighten up (avoid many tiny residuals)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Small residual penalty scaled by open bins count (fragmentation cost)
    if post_residual > 0 && post_residual < 10 {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny gaps are pure waste
        } else if gap < 20.0 {
            // gap usable only by very small items; partial penalty
            score += 25.0 * (20.0 - gap) / 10.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open bins pressure: discourage spreading across many bins when residuals are small
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty for creating dead space for lookahead
        score += 10.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let new_bin_base = 15.0 + 0.2 * open_bins_count as f64;
        // If existing bins would leave large dead space, opening a new bin is attractive
        score = new_bin_base;
        if post_residual > 20 {
            score -= 5.0; // fresh bin keeps large residual flexible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Slack after hypothetically fitting the next item; smaller slack is better.
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Relative to mean residual: favor filling bins that are already low.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin would leave awkward dead space.
    if bin_residual == bin_capacity {
        let tight = post_residual as f64;
        let awkward = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        score += 80.0;
        if awkward {
            score -= 90.0; // opening a fresh bin beats trapping dead space
        }
        if tight < 10.0 {
            score -= 100.0; // never open a new bin when a near-perfect fit exists
        }
    }

    // Mild preference for consolidating: fewer open bins is better.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Exact two-item closure bonus.
        if post_residual == next_item_size && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize by default so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure + 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        // Open a new bin early in the stream when mean residual is high (fragmentation risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 40.0 && progress < 0.5 {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let p = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = p * p * (1.0 - p) * 4.0; // peaks mid-stream
    score -= progress_poly * norm_post * norm_post * 30.0;
    // Penalize dead space more as stream progresses (fewer chances to fill it)
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * (0.2 + 0.8 * p) * 0.5;
    // Reward tight fits (small post_residual) especially late
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 40.0 * p);
    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }
    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // Slight preference for fuller bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;
    // New-bin candidate: keep it neutral-to-slightly-poor unless item is large
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * norm_item;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions.
    // Classes: 0 (perfect fit), small (<=10), medium (<=30), large.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space minimal
    } else if pr <= 30 {
        score -= 8.0;
    } else {
        score += 6.0; // large leftover: penalize
    }

    // Integer-division harmonic class: can a "standard" chunk (10/20/25/50) fit?
    let harmonic_chunk = if pr >= 50 { 50 } else if pr >= 25 { 25 } else if pr >= 20 { 20 } else if pr >= 10 { 10 } else { 0 };
    score -= harmonic_chunk as f64 * 0.4;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 40.0;
        } else if slack <= 10.0 {
            score -= 18.0;
        } else {
            score -= 4.0 + 20.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > 0 {
        score += 10.0; // next item cannot use this residual
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the current bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (pr > 30 && pr < 50) as f64;
        score = cap - 20.0 * (1.0 - progress) - awkward * 10.0
            + if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 0.0 } else { 12.0 }
            + (open_bins_count as f64) * 0.5;
    }

    // Mild tie-break: prefer bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0; // up to +60 for tiny gaps
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading further.
    let open_pressure = (open_bins_count as f64).sqrt() * 2.0;
    score += open_pressure;

    // New-bin candidate handling: empty bin should only win when the fit
    // into open bins is bad. Penalize the fresh bin moderately.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If next item is large and current item leaves a bad gap, a new
        // bin becomes relatively more attractive.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item won't fit in the leftover gap
    }

    // Early in stream: consolidation matters more; late: flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better.
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // 2-step lookahead: strongly reward bins whose post_residual matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + fit_gap);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space creation.
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins with above-average residual (keeps tight bins free).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Last-chance bin bonus: if this is the only bin that can fit, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin unless the fit is poor and lookahead is bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 8.0;
        }
        if item_size >= 70 {
            score -= 12.0;
        }
    }

    // Early in stream: be conservative, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are nearly unusable
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // usable mid-range gap is fine
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: prefer this bin if the next item can still fit the post-residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 6.0;
        } else {
            score += 5.0;
        }
        // Perfect chain: item + next item exactly fills residual
        if post_residual == 0 || (bin_residual as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Default penalty so existing bins are preferred when fit is decent.
        score += 30.0;
        // But open a new bin when the fit into existing bins is poor (large leftover)
        // or when open bins are nearly full on average.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 35.0; // big items deserve a fresh bin
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins are too full anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Mild late-stream pressure to consolidate rather than spawn bins.
        score += 10.0 * progress;
    }

    // Global state: many open bins -> mild pressure to fill existing ones.
    score += 0.4 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins with residual close to item need,
    // penalize bins that are much emptier than average (save them for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, but with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more; early, keep residual flexible
    let tightness = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks at half-full
    score += 20.0 * tightness * (0.5 + progress);

    // Penalize leaving residual that fits neither current nor next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * (ni - pr) / cap * (1.0 - progress);
        } else {
            // reward bins that can also host the next item
            score -= 6.0 * (1.0 - (pr - ni) / cap) * progress;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual below mean residual (denser bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space (1..10) is nearly worthless
    let dead_class = post_residual % 10;
    if post_residual > 0 && post_residual <= 10 {
        score += 30.0 + (10 - post_residual) as f64 * 4.0;
    } else if dead_class == 0 {
        // post_residual is a multiple of 10 -> reusable by common item sizes
        score -= 12.0;
    } else if dead_class < 5 {
        score += 8.0 + dead_class as f64;
    } else {
        score -= 3.0;
    }

    // Lookahead coupling: does post_residual fit the next item nicely?
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item can't go here anyway; slight penalty if this bin is the only option
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        } else {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 200.0; // two-step perfect fit
            } else if slack <= 10 {
                score += 10.0; // would create dead space next step
            } else {
                score -= slack as f64 * 0.5;
            }
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin unless residual is tiny
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline, penalized unless
    // current fit is poor or bin pool is small
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if post_residual == 0 { score -= 100.0; }
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 40.0; // open bins nearly full, opening fresh is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(next_item_size) {
            score -= 5.0;
        }
    }

    // Progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / 10.0).min(3.0);

    // Penalize bins far below mean residual (fragmented pool) mildly
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            40.0 // tiny gap almost certainly unusable (min item 1, but waste-prone)
        } else {
            0.0
        };
        score += dead;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving a gap that can't fit the next item if it could have elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0;
    }

    // Open-bins pressure: fewer bins is better; discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Slight preference for filling tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect two-step chain: place here so next item fills this bin exactly
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to tightness
            let tightness = 1.0 - ((post_residual as f64 - next) / bin_capacity as f64);
            score -= 15.0 * tightness;
        } else {
            // Next item will NOT fit here: dead space penalty scaled by gap
            let gap = (next - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * gap;
        }

        // Double-chain: post_residual equals next item size AND item_size fits a chain too
        if post_residual == next_item_size && bin_residual == item_size + next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate, penalize spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * open_bins_count as f64;

    // Small bonus for very tight fits overall
    if post_residual <= 5 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1
    // is impossible, but small residuals below ~15 are hard to fill).
    if post_residual > 0 && post_residual < 15 {
        score += 8.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to how far off.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
        // Perfect pairing: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // into existing bins is poor or there are few alternatives.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for wasting a fresh bin; grows with number of open bins.
        score += 20.0 + 1.5 * open_bins_count as f64;
        // Early in the stream, strongly discourage new bins (plenty of room ahead).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If many bins already fit the item, make new bin clearly unattractive.
        score += 5.0 * fitting_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual.max(0.0);
        // Exception: very large items that leave awkward slacks benefit from fresh bins.
        if item_size > 60 {
            score -= 12.0;
        }
        // Lookahead: if next item is large and this item is large, a fresh bin
        // for a big pair is reasonable.
        if next_item_size > 50 && item_size > 50 {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open and residuals are high.
    if !is_new_bin && mean_residual > 40.0 && open_bins_count > 3 {
        score += 0.05 * (mean_residual - 40.0);
    }

    // Late-stream consolidation: near the end, prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 5.0 * (progress - 0.8) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / capacity;

    // Base: waste after placement, with a non-linear penalty on small residuals
    let mut score = post;
    score += 40.0 * (1.0 - norm_post).powi(3) * norm_post;

    // Smooth stream-progress coupling: late in the stream, prefer tighter fills
    score -= 25.0 * (1.0 - norm_post) * progress * progress;

    // Interaction between post_residual and mean residual: discourage drifting far from mean
    score += 3.0 * (post - mean_residual).abs() / (1.0 + norm_post);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_post);
    }

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 && (post as u32) >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / capacity);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions and modular structure.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap / 4.0;
    let tenth = cap / 10.0;

    // Perfect fit: huge reward (post_residual == 0 closes the bin cleanly).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover smaller than the smallest plausible item
    // (harmonic class <= C/10) is nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Modular harmonicity of the residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more likely to be filled later.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        if r % 10 == 0 { b += 8.0; }
        if r % 20 == 0 { b += 6.0; }
        if r % 25 == 0 { b += 6.0; }
        if r % 50 == 0 { b += 8.0; }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Next-item lookahead: reward if the next item fits exactly into the
    // post residual (harmonic match), penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual).min(20) as f64 * 0.8;
        }
    }

    // Fraction-of-capacity class of post residual: leftover near quarter
    // divisions is structurally useful.
    let frac = post / cap;
    if (frac - 0.25).abs() < 0.02 || (frac - 0.5).abs() < 0.02 || (frac - 0.75).abs() < 0.02 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin rather
    // than opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // nearly full (small residuals) or too fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        if post_residual > 0 && post_residual < tenth {
            score += 50.0; // would create immediate dead space
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open the first bin
        }
        // Late in the stream, avoid opening bins for marginal fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Prefer tighter bins overall: compare against mean residual.
        score += (mean_residual - post) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever hold
    // typical items are heavily penalized (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // small gap: risky dead space, super-linear penalty
        score += (25.0 - post_residual as f64) * 1.5;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio coupling).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is less costly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate: prefer it only when the item barely fits anywhere
    // or the stream is early (future items may need the space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (bin_residual - item_size) as f64;
        score = tight + pressure * 2.0 + (1.0 - progress) * 10.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // nothing else fits: new bin is fine
        }
    }

    // Lookahead: if next item would fit exactly in the post-residual,
    // reward this placement (creates a perfect slot).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // post-residual too small for the next item: mild dead-space penalty
        score += 8.0;
    }

    // Mild alignment with mean residual: bins already below mean residual
    // are the "most filled" — prefer filling them further.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fits the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin completely
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual -> penalize proportionally
            score += 10.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tight fits relative to mean residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Penalize bins with residual far above mean (hoarding space)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let stream_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: open bins freely; late stream: discourage sprawl
        score = 45.0 - 20.0 * (1.0 - stream_frac);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0; // next item is small; a fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize leaving dead space that the smallest plausible item cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover; penalize large wasted residuals.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item in stream: prefer filling any bin as tightly as possible.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer packing into existing bins over opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score -= 5.0 * pressure.min(3.0);

    // Time horizon: early in the stream, be choosy (penalize mediocre fits);
    // late in the stream, just close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins that are outliers (very full or very empty).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.08 * dev;

    // Mild preference for fuller bins overall.
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post-residual in [0,1]

    // Smooth polynomial coupling of post-residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) - 0.5 * x * x * (1.0 - progress);

    // Penalize dead space that likely cannot serve the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 0.6 * gap * gap;
        // Reward residuals that still fit the lookahead item
        if pr >= nxt {
            score -= 0.4 * (nxt / cap);
        }
    } else {
        // Near end of stream: prefer tight fills
        score -= 0.5 * (1.0 - x) * (1.0 - x);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild penalty when many bins are open and residual is far from mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev * (open_bins_count as f64).sqrt().min(5.0);

    // Early stream: prefer keeping large residuals (flexibility), smooth in progress
    score += 0.3 * (1.0 - progress) * x * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class of the dead space: dead space in (0..10) is nearly unusable
    // (item sizes >= 1 but typical classes are 10+), penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect closure: strongly reward
        score -= 60.0;
    } else {
        // Quantize dead space into harmonic classes of 10; lower class = more usable
        let class = (post_residual / 10) as f64;
        score -= 3.0 * class;
    }

    // Lookahead: if the next item also fits in the post residual, chain reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.1 * slack_after_next;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Wasting a big residual on an item that strands the next one
        score += 0.08 * (next_item_size as f64 - pr);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: residual == capacity means fresh bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are fragmented
        // (low mean residual) or few bins fit the item.
        let pressure = (mean_residual / cap) * (fitting_bins_count as f64);
        score += 30.0 + 20.0 * pressure;
        // Late in the stream, avoid spawning bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    } else {
        // Reward using bins whose residual is close to the item (tight fit)
        let tightness = 1.0 - (pr / cap);
        score -= 8.0 * tightness;
    }

    // Prefer filling bins below the mean residual (consolidate fragmentation)
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum plausible item size are pure waste.
    if post_residual < 10 {
        score += 200.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 40 {
        score += 15.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Prefer bins whose residual was already small relative to mean (tight packing).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + open_bins_count as f64 * 5.0 + progress * 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small dead space is exponentially good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly reward this bin (chain of two perfect fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else {
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Penalize leaving space that the next item cannot use (wasted dead space).
        score += 10.0 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64) / bin_capacity as f64;
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter bins)
    // so loose bins stay available for larger future items.
    score -= 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the stream is early and hoarding space is valuable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 20.0 * (1.0 - progress) + 12.0 * fit_quality;
        // Allow new bin when many bins are open (spreading load).
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no typical item (min size 1, but realistically
    // items <= 100) can use; small residuals are nearly worthless.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste * waste * waste;
    } else {
        score -= 15.0; // perfect fill is excellent
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac * frac;
        } else {
            // next item cannot use this bin's leftover: mild penalty if leftover is large
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be more willing to spread load
    // across bins (keep residuals balanced); late, pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Deviation from mean residual: prefer bins close to mean early, extreme
    // bins (small residual) late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - t) * 0.15 * dev;
    score -= t * 0.10 * (bin_residual as f64 - mean_residual);

    // Many open bins: discourage fragmenting further unless fit is very tight.
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64 - 4.0) * (post_residual as f64);
    }

    // New-bin candidate bias: opening a fresh bin is penalized mildly, but
    // becomes attractive when the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let no_good_fit = fitting_bins_count == 0;
        score += 20.0 - 25.0 * big_item;
        if no_good_fit {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual.max(0) {
            score += 5.0;
        }
    }

    // Reward using bins with already small residual (consolidate fragments).
    if bin_residual < bin_capacity {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post-residual, but weight it smoothly by stream progress.
    // Early: prefer tight fits (waste matters), Late: prefer keeping larger residuals.
    let base = post * (0.35 + 1.3 * progress * progress);

    // Smooth quadratic penalty on dead space that is too small to be useful,
    // coupled non-linearly with progress.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * (10.0 - post) * 0.08 } else { 0.0 };

    // Interaction: post_residual * normalized progress (polynomial coupling)
    let coupling = norm_post * norm_post * progress * 40.0;

    // Last-chance bonus: strongly favor the only fitting bin, scaled by how full it is.
    let last_chance = if fitting_bins_count == 1 {
        -(1.0 - norm_post) * 60.0
    } else {
        0.0
    };

    // Lookahead: reward if next item fits the post residual (smooth falloff).
    let lookahead = if next_item_size > 0 {
        let fit = (post - next_item_size as f64) / cap;
        if fit >= 0.0 { -fit.abs().sqrt() * 25.0 } else { fit.abs() * 15.0 }
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins, smoothed by mean residual.
    let spread = open_bins_count as f64 * 0.15 + mean_residual * 0.05;

    base + dead + coupling + last_chance + lookahead + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // for typical small items (multiples of 10, or >= 20 usable space).
    let pr = post_residual;
    let harmonic_mod = pr % 10;
    if harmonic_mod == 0 {
        score -= 6.0; // perfectly aligned residual
    } else if pr >= 20 {
        score -= 2.0;
    } else if pr > 0 {
        score += 8.0; // dead-space sliver
    }

    // Capacity fraction thresholds on post_residual
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 4.0;
    } else if frac < 0.1 && pr > 0 {
        score += 5.0;
    }

    // Integer-division class of next_item_size vs post_residual:
    // if the lookahead item cannot fit here, penalize slightly less
    // (bin remains for smaller future items) but reward if next item
    // fits exactly into a harmonic class.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let q = pr / next_item_size.max(1);
            score -= 3.0 * q.min(3) as f64;
            if pr % next_item_size.max(1) == 0 {
                score -= 4.0; // exact harmonic fill with lookahead
            }
        } else {
            score += 2.5;
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual
    // classes of current bins are all poor (small usable residuals).
    if bin_residual == bin_capacity {
        score += 14.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 15.0 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 4.0; // late stream: prefer consolidation
        }
    }

    // Mild preference for tight fits overall
    score -= (item_size as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can use well are toxic.
    let dead = if post_residual == 0 {
        -60.0 // perfect fit: strongest reward
    } else if post_residual < 10 {
        120.0 // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        30.0 // nearly dead gap
    } else if post_residual < 40 {
        5.0
    } else {
        -5.0 // roomy residual is reusable
    };
    score += dead;

    // Reward tight relative fit.
    score += 0.35 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation when bins are few,
    // encourage fresh bin when many bins already sprawl with slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: attractive only if it enables a good future pairing.
    if bin_residual == bin_capacity {
        let next_fits_fresh = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        if next_fits_fresh {
            score -= 18.0;
        } else {
            score += 40.0;
        }
    } else if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0; // lookahead exactly fills this bin
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here anyway; slack is less valuable
    }

    // Slight preference for bins tighter than the fleet mean.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: zero waste is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left after hypothetically placing the next item too.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * slack;
            // Perfect 2-chain: post_residual exactly equals next item.
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.2 * (mean_residual - resid_f);
    } else {
        score += 0.2 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // or nothing else fits well (post_residual small means item nearly fills bin).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // New bin is attractive only for large items or late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - 60.0 * fill_ratio - 40.0 * progress;
        // If next item also fits in the fresh remainder, opening is reasonable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Small penalty for spreading across many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), but avoid exact-zero leftovers
    // only when a follow-up item could use them.
    if post_residual == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // leaves room for the lookahead item
    } else if post_residual < 10 {
        score -= 6.0; // small dead space is acceptable
    } else {
        score += (post_residual as f64) * 0.15; // penalize large dead space
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits elsewhere) or the item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) / (bin_capacity as f64) > 0.7;
        let poor_state = mean_residual > 40.0;
        if big_item || (poor_state && fitting_bins_count > 2) {
            score -= 20.0 + 10.0 * t;
        } else {
            score += 35.0; // default: prefer filling existing bins
        }
    }

    // Lookahead coupling: if the next item is large and this bin's post
    // residual cannot hold it, mild penalty for wasting a "medium" bin.
    if next_item_size > post_residual && next_item_size > 50 && post_residual > 0 {
        score += 8.0;
    }

    // Global pressure: many open bins -> consolidate; few open bins -> allow spread.
    if open_bins_count > 8 {
        score -= 3.0;
    } else if open_bins_count <= 2 && !is_new_bin {
        score += 2.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous and mergeable).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Time horizon: late in the stream, tighten up and avoid spreading.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t > 0.8 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Normalized post-residual and its smooth polynomial coupling with progress
    let x = pr / cap;
    let mut score = pr as f64;

    // Quadratic/cubic coupling: tight fits (small post_residual) rewarded more as stream progresses
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);
    score -= 15.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * progress;

    // Penalize dead space: residuals too small for typical future items
    let dead = if x > 0.0 && x < 0.1 { (0.1 - x) / 0.1 } else { 0.0 };
    score += 40.0 * dead * dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            score += 10.0 * (nx - pr) / cap * (0.5 + progress);
        }
    }

    // Mild preference for filling bins when many are open
    score += 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * x;
    score -= 2.0 * (it / cap) * progress;

    // Deviation from mean residual: prefer bins below mean (consolidate emptier space usage)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residues (<10) are "dead space" classes -> penalize strongly.
    let r = post_residual % 10;
    if post_residual > 0 {
        score += (10 - r) as f64 * 1.5; // closer to a class boundary = more wasted
        if post_residual < 10 {
            score += 60.0; // dead space class: bin nearly unusable
        }
    }

    // Harmonic fit: post_residual divisible by common item sizes (10,20,25,50)
    // leaves a re-usable "harmonic" slot -> reward.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 35.0; }
        else if post_residual % 25 == 0 { score -= 22.0; }
        else if post_residual % 20 == 0 { score -= 18.0; }
        else if post_residual % 10 == 0 { score -= 12.0; }
    }

    // Perfect fit
    if post_residual == 0 { score -= 100.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained harmonic placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // next item cannot follow here; leftover may be stranded
            score += (post_residual.min(next_item_size) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new bin has residual == capacity.
    // Its post_residual = capacity - item_size. Prefer reusing open bins with
    // decent fits; only choose new bin when all fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        // but if item is large, filling a fresh bin is harmonic-efficient
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // late in the stream, avoid needless bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor with harmonic bias)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Slight preference for using more crowded bins when many are open
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the minimum item (1) is dead;
    // residuals below a "useful threshold" are progressively penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit: eliminate dead space entirely
    }

    // Reward tight fits (small waste relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins; opening new bins becomes costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = open_bins_count as f64 * (1.0 + progress);
    score += open_pressure * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it;
    // if the next item would leave an even worse gap, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = post_residual - next_item_size;
            if (next_waste as f64) < dead_threshold {
                score -= 6.0; // sets up a good follow-up fit
            } else {
                score -= 2.0;
            }
        } else if (post_residual as f64) < dead_threshold {
            score += 4.0; // this placement strands the next item
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., closer to being filled), keeping large-residual bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // moderately attractive only when no tight fit is available elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + open_pressure * 0.2;
        if post_residual == 0 {
            score -= 0.0;
        }
        // If the item nearly empties the new bin's usefulness, discourage.
        if (item_size as f64) < 0.25 * bin_capacity as f64 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
            // Extra reward for a near-exact two-step match.
            let slack = post_residual - next_item_size;
            score -= (10 - slack.min(10)) as f64 * 1.5;
        } else {
            // Next item won't fit here; mild penalty scaled by mismatch.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // If next item also fits exactly with nothing left, big bonus.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere (handled by above bonuses) or stream is early.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with upcoming large item
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer tighter overall fit: reward small post_residual relative to item size.
    score -= (item_size as f64) * 0.1;

    // Tie-break: prefer bins among many fitting candidates slightly less.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 45.0;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }

    // Lookahead: if the next item exactly fits the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here; mild bonus scaled by fit quality
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item would NOT fit here: penalize consuming space it might need elsewhere
            score += 8.0;
        }
    } else {
        // last item: just fill tightest
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Compare residual against mean residual of open bins.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate logic: empty bin gets a baseline cost; accept it only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        // cheaper to open a new bin early in the stream (long horizon ahead)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if current item is large, a fresh bin is more attractive
        score -= (item_size as f64 / 100.0) * 15.0;
        // if many bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 2 {
            score += 35.0;
        }
    }

    // Slight penalty for very large post residuals (wasteful placement).
    if post_residual > bin_capacity / 2 {
        score += (post_residual as f64 - bin_capacity as f64 / 2.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = post;

    // Smooth non-linear tightness reward: quadratic in fill ratio, amplified by progress
    let fill_ratio = 1.0 - (post / cap);
    score -= 12.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Penalize unusable dead space: small post residual that can't fit typical items is bad
    let dead = 1.0 - (post / cap);
    score += 8.0 * dead * dead * (1.0 - dead);

    // Interaction: post residual vs mean residual — prefer bins tighter than average
    score -= 3.0 * (mean_residual - post) / cap;

    // Lookahead: reward if next item fits into post residual (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (1.0 - (nx / post.max(1.0)).min(1.0)) * (1.0 - (nx / post.max(1.0)).min(1.0));
        score -= 6.0 * fits * (0.5 + 0.5 * progress);
        // penalize leaving residual that exactly wastes next item
        score += 2.0 * (1.0 - (nx / cap)).abs() * (post / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins when residual is large
    score += 0.02 * open_bins_count as f64 * (post / cap);

    // New-bin candidate: empty bin gets neutral-ish score, slightly penalized unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * progress * (mean_residual / cap).min(1.0);
    }

    // Smooth stream-progress coupling: later in stream, be greedier about tight fits
    score *= 1.0 - 0.15 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into quarters of capacity. Small classes are "dead space" -> penalize.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    } else if post_residual < quarter {
        // small leftover, mildly good
        score -= 15.0;
    } else if post_residual == quarter {
        // exact quarter leftover: harmonically reusable, reward
        score -= 25.0;
    } else if post_residual == half {
        // exact half leftover: highly reusable
        score -= 30.0;
    } else if post_residual < half {
        // mid-range leftover: neutral
        score += 5.0;
    } else {
        // large leftover: bin was nearly empty; opening/keeping such bins is fine,
        // but prefer tighter bins when alternatives exist
        score += 10.0;
    }

    // Modulo-10 harmonic bonus: leftovers divisible by 10 pair well with
    // integer item sizes drawn from 1..=100.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: reward proportionally to how well next item uses leftover
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 - (chain_waste as f64) * 0.3;
        } else {
            // next item won't fit here: penalize creating a stranded residual
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).ln() * 6.0
        };
        // base cost of opening a new bin grows with number of open bins
        score += 45.0 + pressure + (open_bins_count as f64) * 1.5;
        // early in the stream, opening bins is cheaper (will amortize)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Tie-break with mean residual: prefer placing into bins below the mean
    // residual (tighter bins) to consolidate space.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when the item fits an open bin
    // badly (large dead space would be created) or stream is early.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: post_residual == item_size here.
        // Penalize slightly so tight fits in open bins always win.
        score += 15.0;
        // But if placing in this item would leave a big usable gap anyway,
        // a fresh bin is fine; discount by open-bin pressure.
        score -= (open_bins_count as f64) * 0.5;
    }

    // Lookahead: if the next item could exactly use the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if next item cannot fit into post_residual and post_residual is small.
    if next_item_size > post_residual && post_residual < 15 && post_residual > 0 {
        score += 15.0;
    }

    // Mild pressure from number of open bins: prefer filling existing bins
    // when many are open.
    score += (open_bins_count as f64) * 0.3;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a "ragged" bin; finishing it off is good.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual - 10.0 {
        score -= 5.0;
    }

    // Progress: later in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits snugly in the leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    }
    // Next item won't fit here: penalize proportionally to wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 15.0 + gap * 0.3;
    }

    // Penalize unusable dead space relative to smallest possible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tight fit reward: leaving almost nothing behind.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Compare against mean residual: filling below-average-residual bins is good.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size >= next_item_size && post_residual < next_item_size {
            score -= 20.0; // big item then next fits elsewhere? keep new-bin cheap
        } else {
            score += 10.0; // discourage opening new bins by default
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted space relative to capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else and there is lookahead room.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 50.0;
        let many_open = (open_bins_count as f64) > 2.0;
        if poor_fit && many_open {
            score -= 25.0;
        } else {
            score += 80.0;
        }
        // New bins are less attractive late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // reward heavily (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use the leftover: mild penalty for dead space.
            score += 10.0;
        }
    }

    // Global state: prefer bins with below-average residual (tighter bins),
    // keeping loose bins available for larger future items.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Prefer consolidating into fewer bins when many are open.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Time horizon: early in stream, be conservative about small leftovers;
    // late in stream, squeeze anything anywhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;
    let mut score = pr;

    // Non-linear coupling: quadratic dead-space penalty scaled by stream progress
    let poly = fit_frac * fit_frac * (0.5 + 2.0 * progress);
    score += 40.0 * poly;

    // Smooth reward for tight fits, stronger early when residuals are precious
    let tightness = 1.0 - fit_frac;
    score -= 15.0 * tightness * tightness * (1.0 - progress);

    // Penalize opening new bins more as stream progresses (consolidate late)
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    } else {
        score -= 3.0;
    }

    // Last-chance bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mean-residual deviation term (smooth, normalized)
    score += (mean_residual - pr).abs() / cap * 10.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "complementary"
    // residue classes (multiples of 10) are more reusable for typical item sizes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit) strongly.
    score -= (cap - pr) / cap * 30.0;

    // Modulo-10 harmonic class: leftovers that are exact multiples of 10 are
    // ideal (items are classically multiples of 10); reward them, penalize
    // awkward residues like 1..9 which create dead space.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 8.0;
    } else {
        score += residue_class as f64 * 0.9;
    }

    // Integer-division thresholds on post_residual: classify leftover utility.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < 10 {
        // Nearly dead space: strong penalty unless bin was almost exactly filled.
        score += 6.0;
    } else if post_residual <= quarter {
        score -= 3.0;
    } else if post_residual <= half {
        score -= 1.5;
    } else {
        // Large leftover: mildly penalize wasting a big-capacity bin on a small item.
        score += (post_residual as f64 - half as f64) * 0.05;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is part of a perfect chain — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover remains useful.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give the fresh bin a moderate baseline so tight fits
    // in existing bins beat it, but bad fits (large post_residual) lose to it.
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.1 * mean_residual - 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, prefer consolidation into open bins even more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mean residual context: if open bins are on average spacious, prefer
    // filling them rather than fragmenting space.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins, but give
        // bonus if placing in this bin would leave a large awkward gap elsewhere
        score += 25.0 + open_pressure;
        if post_residual > 50 {
            score -= 10.0; // fresh bin is fine if item is small relative to capacity
        }
    }

    // Lookahead: if the next item would fit exactly in the post residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; small dead space is less valuable
        score += post_residual as f64 * 0.2;
    }

    // Prefer bins whose residual is above the mean (larger bins absorb items better)
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= (residual_f - mean_residual) * 0.1;
    } else {
        score += (mean_residual - residual_f) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // exact 2-step completion is excellent
            if slack == 0 {
                score -= 500.0;
            } else {
                score -= 80.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // post_residual cannot fit next item: penalize dead space relative to next item
            let gap = next_item_size - post_residual;
            score += 40.0 * (gap as f64 / next_item_size as f64);
        }

        // next item exactly fits current residual (this item then next chain)
        if bin_residual == item_size + next_item_size {
            score -= 400.0;
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Compare against mean residual: bins with residual far below mean are precious tight fits
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.5 * (mean_residual - res_f);
    } else {
        score += 0.3 * (res_f - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new bin only attractive if existing fits are bad (large post_residual elsewhere)
        // handled implicitly: base score = full capacity residual is high
        // but give a mild bonus late in stream when many bins are open and fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0 * progress;
        } else {
            score += 50.0;
        }
    }

    // Slight preference for fuller bins overall
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), superlinear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Last-chance bonus: only one bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the leftover space can still accommodate the next item,
    // reward keeping this bin usable; otherwise penalize stranding space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * post_residual as f64;
        } else if post_residual > 0 {
            score += 0.35 * post_residual as f64; // dead space penalty
        }
    }

    // Prefer filling bins whose residual deviates from the mean (consolidate
    // fragmented space into fewer bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.10 * dev;

    // Time horizon: late in the stream, be more aggressive about using open
    // bins rather than opening new ones (fewer wasted bins at the end).
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize slightly more as stream progresses,
        // but early on allow opening bins when mean residual is low (poor fits).
        let mean_r = mean_residual;
        score += 8.0 * progress - 0.05 * mean_r;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.25 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth non-linear couplings with progress.
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + 0.5 * progress);          // dead space penalized more late in stream
    score -= 20.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - progress); // tight fits rewarded early

    // Cubic interaction: medium residuals are least harmful; extremes penalized.
    let mid = prn - 0.5;
    score += 15.0 * mid * mid * mid * mid;

    // Reward using bins whose residual matches the item closely (smooth kernel).
    let fit = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * fit * fit;

    // Last-chance bonus: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly, more when open bins are empty-ish and early.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
        // But allow a new bin if it perfectly fits the next item too.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 60.0;
        }
    }

    // Lookahead: prefer bins leaving residual compatible with the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 8.0 * (gap / cap);
        if pr >= next_item_size as f64 && gap < 10.0 {
            score -= 12.0;
        }
    }

    // Dampen preference for bins deviating from mean residual (smooth dispersion term).
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual (small leftovers are valuable)
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that no plausible item can use:
    // post_residual < 10 (min item size in classic streams) is wasted unless 0.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic classes: residue classes of post_residual mod 10
    // encourage leftovers that align with common item size fractions.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // leftover is a multiple of 10 -> highly reusable
    } else if class >= 5 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (10 - slack.min(10)) as f64 * 1.5;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit here
    // is poor. Penalize opening a new bin mildly, more when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
    } else {
        // Prefer filling existing bins over opening new ones
        score -= 5.0;
    }

    // Mild global pressure: as stream progresses, avoid leaving many half-full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64) * (10.0 + 10.0 * progress);
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1) can still
    // usefully fill are heavily penalized. Small residuals (< 10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: zero dead space, reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward; if next item barely misses, penalize creating a near-miss gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (handled by post_residual)
        // but add mild open-bin pressure to discourage excessive bin sprawl.
        score += open_bins_count as f64 * 0.4;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with how many are already open.
        score += 30.0 + open_bins_count as f64 * 0.5;
        // Large items are hard to place later; opening a bin for them is ok.
        if item_size >= 60 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins that will end mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for bins below mean residual (balanced packing).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: next item fills this bin perfectly -> strong bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item still fits inside leftover: mild reward scaled by closeness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward residue.
            score += 8.0 * (diff / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 5.0;
    }

    // Penalize large post_residual relative to mean residual across open bins
    // (avoid creating oversized dead space when tighter options exist).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    // Slight reward for being tighter than average.
    score -= 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        // Extra push when the fit is reasonably tight.
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit would be very poor.
    if bin_residual == bin_capacity {
        let avg_load = bin_capacity as f64 - mean_residual;
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if open_bins_count > 0 && !poor_fit {
            score += 25.0;
        }
        // If bins are nearly full on average, opening fresh is fine.
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 20.0;
        }
        let _ = avg_load;
    }

    // Early in the stream, be slightly more willing to spread items
    // (more future flexibility); later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    // Many open bins: discourage spreading, favor tight packing.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, amplify non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward gap
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Next item won't fit here; mild penalty scaled by overflow size.
            score += 5.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 && (bin_residual as f64) > mean_residual {
        score -= 8.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be pickier (penalize loose fits);
    // late in the stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 * 0.15);
    score -= progress * (item_size as f64 * 0.10);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of opening a new bin, discounted by stream progress.
        score += 35.0 + 45.0 * desperation - 20.0 * progress;
        // A new bin is great if the item is large and would leave little waste.
        score -= 0.5 * (post_residual as f64);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let slack = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * slack * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 40.0 * norm_pr * norm_pr * (0.5 + p2);
    score -= 25.0 * norm_pr * (1.0 - p3);
    // penalize tiny dead space that likely becomes unusable
    if pr > 0.0 {
        score += 15.0 * (1.0 - pr / cap).powi(6);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (1.0 - progress);
    }
    // mild pressure to consolidate when many bins open
    score += 0.05 * open_bins_count as f64 * norm_pr;
    // deviation from mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.3 + p3);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small residues (mod classes 1..=3) are "dead space" classes -> penalize.
    let res_mod = post_residual % 10;
    let dead_penalty: f64 = match res_mod {
        0 => -6.0,                    // perfectly reusable class
        1..=3 => 8.0,                 // nearly dead space
        4..=6 => 2.0,
        _ => -2.0,                    // 7..=9 still useful for small items
    };
    score += dead_penalty;

    // Integer division threshold: post_residual / 10 tier.
    let tier = post_residual / 10;
    score -= (tier as f64) * 1.5;     // larger usable residual slightly favored beyond base term

    // Lookahead: does next item fit in post_residual? Reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic coupling: how well next item's residue complements post_residual
            let slack = (post_residual - next_item_size) % 10;
            score -= 10.0 - (slack as f64);
        } else {
            score += 4.0; // next item won't fit here; this bin is closing anyway
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when many bins exist and fits are decent.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        score += 20.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0
                 - fit_quality * 0.3;
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it is an outlier worth filling; if above mean, deprioritize slightly.
    let bin_res = bin_residual as f64;
    score += (bin_res - mean_residual) * 0.05;

    // Early stream: be greedy with tight fits; late stream: consolidate.
    if total_items > 0 && step_index * 2 > total_items {
        score -= post * 0.1; // late phase: extra reward for low post_residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Items are 1..100, so a residual below ~10 can never be reused -> hard penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward" gap: small enough that few items fit, but not zero. Penalize non-linearly.
    if post_residual >= 10 && post_residual < 25 {
        score += 0.9 * (25.0 - post_residual as f64);
    }

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward filling a bin tightly relative to its remaining space (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 10.0; // still better to dump in last bin than open new one
        }
    }

    // Open-bin pressure: discourage proliferation of many open bins,
    // scaled by how crowded we already are.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(0.8) * (0.15 + 0.35 * progress);

    // Mean residual coupling: when open bins are already loose (high mean residual),
    // prefer tightening an existing bin rather than adding slack elsewhere.
    score += 0.10 * mean_residual;

    // Lookahead (k=2): if the next item would fit exactly in the post_residual,
    // this placement sets up a perfect future fit -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0; // sets up near-perfect follow-up
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slight penalty for stranding space
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it unattractive
    // unless the item fits poorly in every open bin. Base cost of opening a new bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If no open bin could fit (fitting_bins_count==0 semantics: this is the only option),
        // the 55.0 penalty is the only competing score, so it will still be chosen.
        // If lookahead says next item is huge, opening fresh may be fine: soften slightly.
        if next_item_size >= 70 && item_size >= 70 {
            score -= 20.0;
        }
        // Late in the stream, opening new bins is less costly relative to fragmentation.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match for next item is a huge win.
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 40.0; // exact two-item pairing
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover too small for the next item: penalize dead space, worse if tiny.
        let waste = post_residual as f64;
        score += 1.5 * waste + 10.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin below-average residual concentrates space elsewhere (good).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, keep bins tight; later, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Slight preference to reuse existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (bin_residual as f64).max(1.0);
    score -= (1.0 - fit_ratio) * 18.0;

    // Exact fit: massive reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Penalize dead space that nothing can ever use (min item size is small; treat <5 as dead)
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: leaves room for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential
            let waste = (next_item_size as f64 - post_residual as f64).min(item_size as f64);
            score += 4.0 + waste * 0.15;
        }
    } else {
        // Last item in stream: just minimize post residual (already base)
        score -= 10.0;
    }

    // New-bin candidate logic: empty bin gets neutral-ish baseline, encourage only when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Prefer new bin when existing residuals are large and fragmented (poor fits likely)
        score = 55.0 + 30.0 * fragmentation - 20.0 * progress;
        // Discourage opening new bins if a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_possible = post_residual as f64; // residual if placed in empty bin
            score += best_possible * 0.35;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // fresh bin pairs well with next item
        }
    }

    // Global state coupling: many open bins with low mean residual -> prefer consolidating into fuller bins
    let density = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= density * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Time horizon: early in stream, be more willing to open bins / keep flexibility; late, pack tight
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 - 0.25 * progress; // late-stage: amplify relative differences downward for tight bins

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress coupling: early on, tolerate larger residuals less; later, reward tight fits more
    let progress_term = 30.0 * progress * (norm_pr - 0.5) * (norm_pr - 0.5) * 4.0;
    score += progress_term * pr / cap;

    // Dead-space penalty: residuals too small for typical items (smooth via quadratic)
    let dead = if pr > 0.0 { (cap / pr - 1.0).max(0.0) } else { 0.0 };
    score += 5.0 * dead * dead / (1.0 + dead);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smooth)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (-gap / 10.0);
    }

    // Crowd control: many open bins -> discourage spreading, favor filling existing
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Mean residual alignment: prefer bins near mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap);
        score += 15.0 + 40.0 * tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: multiples of 10 are "clean" states.
    let pr = post_residual as u32;
    let harmonic = pr % 10;
    score += (5 - harmonic.abs_diff(0).min(5)) as f64 * 2.0; // reward exact decade alignment
    if harmonic == 0 && pr > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: tiny unusable slivers are dead space.
    if pr < 10 {
        score += 12.0;
    } else if pr < 20 {
        score += 4.0;
    }

    // Capacity-fraction coupling: residual as fraction of capacity.
    let frac = post_residual as f64 / cap;
    score += (0.5 - (frac - 0.5).abs()) * 8.0; // prefer residuals near half capacity? invert: prefer small
    score += frac * 10.0;

    // Lookahead harmonic: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score += (slack % 10) as f64 * 0.5;
            if slack < 10 { score -= 5.0; }
        } else {
            // next item cannot fit here; bin will be stranded
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves a bad class.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs().min(20.0) * 0.3;

    // Prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    let min_item = 1u32;
    let dead_threshold = if next_item_size > 0 { next_item_size.max(min_item) } else { min_item };

    if post_residual > 0 && post_residual < dead_threshold {
        // Unusable sliver: heavy penalty, worse the closer it is to zero utility.
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else if post_residual == 0 {
        // Perfect closure of a bin: strongly reward.
        score -= 60.0;
    } else {
        // Reward tight fits quadratically.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a large, reusable gap in existing bins (poor fits).
    if bin_residual == bin_capacity {
        // Mild baseline preference to reuse bins; overcome only by very tight fits there.
        score += 12.0;
    }

    // Mean residual coupling: when open bins are already loose, discourage more slack.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
