pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual wasted relative to the upcoming item.
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the current bin fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_gap = mean_residual - item_size as f64;
        let poor_fit_elsewhere = (mean_gap / bin_capacity as f64).clamp(0.0, 1.0);
        // New bins favored early (future flexibility) and when open bins are wasteful.
        score = 30.0 - 25.0 * (1.0 - progress) - 20.0 * poor_fit_elsewhere
            - 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure toward consolidating into bins with large residuals when many
    // bins are open (reduce fragmentation).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * x * (1.0 + progress) + 0.5 * x * (1.0 - progress);

    // Reward tight fits (small post_residual), more aggressively late in stream
    score -= (1.0 - x) * (1.0 - x) * (0.5 + 1.5 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) / cap * (1.0 + progress);
        } else if pr >= nxt {
            score -= 0.3 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Mild penalty when bin is far below mean residual (fragmentation risk)
    score += 0.2 * ((pr - mean_residual).abs() / cap);

    // New-bin candidate: neutral-ish score driven by progress
    if bin_residual == bin_capacity {
        score = 1.2 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity wasted

    // Dead-space penalty grows super-linearly for unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // tiny unusable gap
    }

    // Harmonic buckets: quarter classes of capacity
    let quarter = (post_residual * 4) / bin_capacity; // 0..3
    match quarter {
        0 => score -= 8.0,               // near-perfect fill
        1 => score += 2.0,               // quarter leftover
        2 => score += 5.0,               // half leftover
        _ => score += 9.0,               // mostly empty bin chosen
    }

    // Reward when leftover can host the lookahead item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // exact pairing: zero future waste
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= (gap.min(20) as f64) * 0.8;
            if gap < 10 { score -= 6.0; }
        } else {
            score += 4.0; // lookahead cannot fit here
        }
    } else {
        // Last item: reward filling as tightly as possible.
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        score += 30.0;
        if !crowded { score += 15.0; }
        if fitting_bins_count == 0 { score -= 60.0; } // no alternative
        if progress > 0.9 { score += 5.0 * (1.0 - progress); }
    }

    // Mild preference for bins below mean residual (balance keeping mid-size gaps).
    if post_f < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Modulo arithmetic on post_residual: values sharing factors with capacity
    // are more reusable by future items (harmonic classes).
    if post_residual > 0 {
        if bin_capacity % post_residual == 0 {
            score -= 5.0; // divides capacity evenly: highly reusable class
        } else if post_residual % 10 == 0 {
            score -= 3.0; // decadal class: common item sizes fit
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // unless the fit is terrible, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + fit_ratio * 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when the item barely fits anywhere else
    // or when existing bins would leave big dead space. Penalize default opening.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if post_residual < 10 {
            score -= 30.0; // new bin leaves a nearly full residual? not possible, but guard
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item exactly fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mean-residual coupling: when average residual is high, prefer bins below mean
    // (consolidate into emptier bins to reduce bin count).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late-stream tightening: as the stream progresses, weight dead space more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // 2-step lookahead: reward if the next item exactly fills post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 40.0 * (1.0 - leftover as f64 / bin_capacity as f64);
            if leftover <= 10 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative residual vs mean: prefer bins tighter than average (concentrate waste).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size are wasted.
    if post_residual < 1 {
        score += 50.0;
    } else if post_residual < 10 {
        score += 20.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but allow opening when all open bins fit poorly (post_residual small).
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize residual space that is too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra bonus for near-perfect chain fit
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of consuming a fresh bin.
        score += 20.0;
        // Favor new bin late in the stream or when open bins are fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        if (mean_residual - item_size as f64) < 5.0 {
            score -= 15.0; // existing bins are nearly full anyway
        }
    }

    // Mild penalty for spreading items across many open bins.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins whose residual is far from the mean (consolidate fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: late in stream,
    // tighten residual preference more aggressively
    let progress_coupling = 1.0 + progress * (norm_pr - 0.5) * (norm_pr - 0.5) * 2.0;
    score *= progress_coupling;

    // Reward tight fits (post_residual near zero) via smooth sigmoid-like term
    score -= 30.0 * (-norm_pr * 8.0).exp();

    // Penalize leaving residuals that are awkward relative to typical item sizes
    score += 10.0 * (norm_pr * (1.0 - norm_pr) * 4.0 - 0.8).abs();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size as u32 <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 {
        // penalize dead space the next item cannot use
        score += 6.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        score = pr + 20.0 + 15.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins with large residuals
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "small
    // dead-space" classes (near capacity fractions) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify leftover by capacity fraction classes.
        let frac = post / cap;
        if frac <= 0.10 {
            score -= 60.0; // tiny leftover is fine (near-full bin)
        } else if frac <= 0.20 {
            score -= 20.0; // still usable
        } else if frac <= 0.30 {
            score += 15.0; // awkward mid zone
        } else if frac <= 0.50 {
            score -= 10.0; // half-bin leftover, reusable
        } else {
            score += 25.0; // wasteful large leftover
        }

        // Modulo-10 harmonic class: leftovers divisible by 10 pair well with
        // typical item sizes (multiples of 10).
        if post_residual % 10 == 0 {
            score -= 12.0;
        }

        // Dead-space penalty: leftover that no plausible next item fits well.
        // If the next item exactly fits the leftover, big bonus.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size <= post_residual {
                let nx = next_item_size as f64;
                // Prefer leaving leftover that pairs with next item's complement class.
                let pair_waste = (post_residual - next_item_size) as f64;
                score -= 30.0 / (1.0 + pair_waste / 20.0);
                // Penalize if next item leaves another awkward class
                let nx_post = pair_waste;
                if nx_post > 0.0 && nx_post < 10.0 {
                    score -= 25.0; // creates near-perfect next fit
                }
            } else {
                // Next item can't use this bin's leftover; if this is the only
                // fitting bin, strongly prefer using it now.
                if fitting_bins_count == 1 {
                    score -= 80.0;
                } else {
                    score += 20.0;
                }
            }
        }
    }

    // Last-chance bin pressure: if only this bin fits, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would create large dead space. Empty-bin call has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; scale with stream progress (late bins cost more).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 300.0 + 150.0 * progress;
        // If next item is huge and current item small, fresh bin can host both later.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    // Mild preference to spread load across bins when many open bins exist.
    score += (open_bins_count as f64) * 0.5;

    // Tie-break toward bins whose residual is close to mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small for typical items (assume min useful ~10,
    // but with unknown distribution use a soft threshold around 15).
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (15.0 - post) / 15.0;
    }
    // Perfect fit reward
    if post == 0.0 {
        score -= 30.0;
    }

    // Tightness reward: reward filling a bin to a high fraction.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += 0.35 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to item
    // (avoid wasting large-residual bins on small items when better fits exist).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 18.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= post + 15.0 {
        score -= 6.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is slightly more acceptable early in the stream.
        score = cap * 0.55 - 20.0 * early + 0.35 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits exactly-ish after this placement
            if diff <= 3.0 {
                score -= 40.0;
            } else if diff <= 10.0 {
                score -= 20.0 / (1.0 + diff);
            } else {
                score -= 10.0 / (1.0 + diff);
            }
        } else {
            // next item would NOT fit after this placement: penalize more as gap grows
            score += 8.0 + 0.15 * (next - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize leaving awkward dead space (small but nonzero residual)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it moderately unattractive unless open bins are very fragmented
    if bin_residual == bin_capacity {
        let avg_fragmentation = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        let pressure = (item_size as f64 / bin_capacity as f64) * 20.0;
        score = 100.0 + pressure - avg_fragmentation.min(30.0);
        // open a fresh bin if next item is huge and would pair with this one
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Late-stream tightening: waste matters more near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100 unknown dist).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't host next item: mild penalty proportional to gap.
        score += 6.0 * (next_item_size - post_residual) as f64 / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64) / (total_items.max(1) as f64);
    score += 10.0 * open_pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate: opening a bin is only attractive when the item is large
    // and the residual is fully fresh; otherwise penalize to reuse existing bins.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if large_item > 0.6 {
            score -= 15.0 * (large_item - 0.6);
        } else {
            score += 20.0 + 25.0 * (1.0 - large_item);
        }
        // Late in the stream, avoid opening bins for small leftovers.
        score += 15.0 * progress;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.05 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nz = pr / cap; // normalized post residual
    let base = pr as f64;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let tight = (1.0 - nz) * (1.0 - nz); // squared fill fraction
    let poly = base - 40.0 * tight * (0.5 + progress);

    // Penalize post-residuals that are small but unusable (dead space), smoothly via cubic
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap * (1.0 + gap)
    } else {
        0.0
    };

    // Last-chance bonus: smooth in fitting_bins_count
    let last_chance = -12.0 / (fitting_bins_count as f64).max(1.0);

    // Mild preference toward consolidating into fewer bins when many open
    let crowd = open_bins_count as f64 * 0.05 * nz;

    // Nudge toward mean residual alignment (smooth quadratic)
    let align = (mean_residual - pr).abs() * 0.1;

    poly + dead * 60.0 + last_chance + crowd + align
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in the smallest band gets big subtraction
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < eighth {
        score -= 25.0;
    } else if post_residual < quarter {
        score -= 10.0;
    } else if post_residual < half {
        score -= 2.0;
    } else {
        // post_residual >= half: large dead space, penalize
        score += 15.0;
    }

    // Modulo classes on post_residual: residues near half-capacity are awkward
    let r = post_residual % half.max(1);
    if r >= 1 && r <= 5 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item exactly fits the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic-style reward decaying with slack
            score -= 30.0 / (1.0 + slack / quarter.max(1) as f64);
        } else {
            // next item cannot use this bin's leftover; penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep neutral-ish, but prefer it when current
    // bin would leave a large awkward residual and mean residual is already low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // open new bins more freely late in the stream when open bins are tight
        let pressure = (mean_residual / cap - 0.5).abs();
        score = 35.0 + 20.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild exploration term via modulo of step index (deterministic jitter)
    let jitter = ((step_index % 7) as f64 - 3.0) * 0.5;
    score += jitter;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0;
    }
    // Moderately small gaps are also risky.
    else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (post_residual near 0 is good unless tiny-but-nonzero).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += 8.0 + pressure * 2.0 + progress * 5.0;
    } else {
        // Existing bin: reward when many bins are open.
        score -= pressure.min(10.0) * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            // Next item cannot use the leftover gap at all.
            score += post_residual as f64 * 0.5;
        }
    }

    // Prefer bins with residual close to item size (best-fit coupling).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin is fully consumed next step
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well the next item nests
            score -= (30.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here; penalize wasted capacity slightly
            score += 5.0;
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - resid_f) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny dead space (unusable fragments)
    if resid_f > 0.0 && resid_f < 10.0 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slightly penalize so real bins with tight fits win
        score += 20.0;
        // but if many bins are open with large mean residual, opening fresh is fine
        if open_bins_count > 0 && mean_residual > 50.0 {
            score -= 15.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild exploration term: spread load when many bins open
    score += 0.05 * open_bins_count as f64;

    score
}
